#!/usr/bin/env node


const APP_URL = process.env.RENDER_EXTERNAL_URL || process.env.APP_URL;
const CRON_SECRET = process.env.CRON_SECRET;

async function triggerSync() {
  const https = await import('node:https');
  console.log(`[CRON] Starting at ${new Date().toISOString()}`);

  if (!APP_URL) {
    console.error('[CRON] APP_URL not set');
    process.exit(1);
  }

  if (!CRON_SECRET) {
    console.error('[CRON] CRON_SECRET not set');
    process.exit(1);
  }

  const url = new URL('/api/cron/sync-emails', APP_URL);

  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: url.hostname,
      port: 443,
      path: url.pathname,
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${CRON_SECRET}`,
        'User-Agent': 'InboxAI-Cron/1.0'
      },
      timeout: 60000
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        console.log(`[CRON] Status: ${res.statusCode}`);

        try {
          const json = JSON.parse(data);
          console.log(`[CRON] Processed: ${json.results?.processed || 0} accounts`);
          console.log(`[CRON] Synced: ${json.results?.synced || 0} emails`);

          if (json.accounts) {
            json.accounts.forEach(r => {
              const status = r.errors?.length ? '✗' : '✓';
              console.log(`  - ${r.email}: ${status} (${r.synced || 0} new)`);
            });
          }
        } catch (e) {
          console.log(`[CRON] Response: ${data}`);
        }

        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve();
        } else {
          reject(new Error(`HTTP ${res.statusCode}`));
        }
      });
    });

    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.end();
  });
}

triggerSync()
  .then(() => {
    console.log('[CRON] Completed successfully');
    process.exit(0);
  })
  .catch((error) => {
    console.error('[CRON] Failed:', error.message);
    process.exit(1);
  });

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { Mail, Lock, ArrowRight, Loader2, Eye, EyeOff } from 'lucide-react'
import { createClient } from '@/lib/supabase/client'

export default function LoginPage() {
  const router = useRouter()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [showPassword, setShowPassword] = useState(false)

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setLoading(true)

    try {
      const supabase = createClient()
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      })

      if (error) {
        setError(error.message)
        return
      }

      router.push('/inbox')
      router.refresh()
    } catch (err) {
      setError('Đã xảy ra lỗi. Vui lòng thử lại.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="bg-[var(--card)] rounded-2xl shadow-executive-lg border border-[var(--border)] p-8">
      <div className="text-center mb-8">
        <h1 className="text-[24px] font-bold text-[var(--foreground)] mb-2">
          Chào mừng trở lại
        </h1>
        <p className="text-[var(--muted)]">
          Đăng nhập để tiếp tục với InboxAI
        </p>
      </div>

      <form onSubmit={handleLogin} className="space-y-4">
        {error && (
          <div className="p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-red-600 dark:text-red-400 text-[14px]">
            {error}
          </div>
        )}

        <div>
          <label htmlFor="email" className="block text-[14px] font-medium text-[var(--foreground)] mb-1">
            Email
          </label>
          <div className="relative">
            <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--muted-foreground)]" strokeWidth={1.5} />
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="email@example.com"
              required
              className="w-full pl-10 pr-4 py-2.5 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
            />
          </div>
        </div>

        <div>
          <label htmlFor="password" className="block text-[14px] font-medium text-[var(--foreground)] mb-1">
            Mật khẩu
          </label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--muted-foreground)]" strokeWidth={1.5} />
            <input
              id="password"
              type={showPassword ? 'text' : 'password'}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              required
              className="w-full pl-10 pr-10 py-2.5 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--muted-foreground)] hover:text-[var(--muted)]"
            >
              {showPassword ? <EyeOff className="w-5 h-5" strokeWidth={1.5} /> : <Eye className="w-5 h-5" strokeWidth={1.5} />}
            </button>
          </div>
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-[var(--primary)] text-[var(--primary-foreground)] py-2.5 rounded-lg font-medium hover:opacity-90 transition-opacity flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? (
            <Loader2 className="w-5 h-5 animate-spin" strokeWidth={1.5} />
          ) : (
            <>
              Đăng nhập
              <ArrowRight className="w-4 h-4" strokeWidth={1.5} />
            </>
          )}
        </button>
      </form>

      <div className="mt-6 text-center text-[14px] text-[var(--muted)]">
        Chưa có tài khoản?{' '}
        <Link href="/signup" className="text-[var(--foreground)] font-medium hover:underline">
          Đăng ký ngay
        </Link>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { Mail, User, Lock, ArrowRight, Loader2, CheckCircle, Clock, AlertCircle } from 'lucide-react'

type Step = 'check_email' | 'signup_form' | 'waitlist_form' | 'success'

export default function SignupPage() {
  const [step, setStep] = useState<Step>('check_email')
  const [email, setEmail] = useState('')
  const [fullName, setFullName] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [message, setMessage] = useState('')
  const [waitlistStatus, setWaitlistStatus] = useState<string | null>(null)

  // Step 1: Check if email is whitelisted
  const handleCheckEmail = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setLoading(true)

    try {
      const res = await fetch('/api/check-whitelist', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email.toLowerCase().trim() })
      })

      const data = await res.json()

      if (data.allowed) {
        // Email is approved or open beta - show signup form
        setMessage(data.message || '')
        setStep('signup_form')
      } else if (data.status === 'exists') {
        // User already registered
        setError(data.message)
      } else if (data.status === 'beta_full') {
        // Beta is full - show waitlist form
        setWaitlistStatus('beta_full')
        setMessage(data.message)
        setStep('waitlist_form')
      } else if (data.status === 'pending') {
        // Already on waitlist, pending
        setWaitlistStatus('pending')
        setMessage(data.message)
        setStep('waitlist_form')
      } else if (data.status === 'rejected') {
        setError(data.message)
      } else {
        // Not on waitlist yet - show waitlist form
        setWaitlistStatus('not_found')
        setStep('waitlist_form')
      }
    } catch (err) {
      setError('Không thể kết nối. Vui lòng thử lại.')
    } finally {
      setLoading(false)
    }
  }

  // Step 2a: Real signup for approved users (auto-confirmed)
  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setLoading(true)

    try {
      // Use server-side API to create user with auto-confirm
      const res = await fetch('/api/signup-whitelist', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: email.toLowerCase().trim(),
          password,
          fullName
        })
      })

      const data = await res.json()

      if (!res.ok) {
        setError(data.error || 'Có lỗi xảy ra. Vui lòng thử lại.')
        return
      }

      setMessage(data.message || 'Đăng ký thành công! Bạn có thể đăng nhập ngay.')
      setStep('success')
    } catch (err) {
      setError('Có lỗi xảy ra. Vui lòng thử lại.')
    } finally {
      setLoading(false)
    }
  }

  // Step 2b: Submit to waitlist
  const handleWaitlist = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setLoading(true)

    try {
      const res = await fetch('/api/waitlist', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email.toLowerCase().trim(), name: fullName })
      })

      const data = await res.json()

      if (res.ok && data.success) {
        setMessage(data.message || 'Đã thêm vào danh sách chờ!')
        setStep('success')
      } else {
        setError(data.error || 'Có lỗi xảy ra. Vui lòng thử lại.')
      }
    } catch (err) {
      setError('Không thể kết nối. Vui lòng thử lại.')
    } finally {
      setLoading(false)
    }
  }

  // Success state
  if (step === 'success') {
    const isApprovedSignup = password.length > 0 // If they entered password, it was real signup

    return (
      <div className="bg-[var(--card)] rounded-2xl shadow-executive-lg border border-[var(--border)] p-8 text-center">
        <div className="w-20 h-20 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-6">
          <CheckCircle className="w-10 h-10 text-green-600 dark:text-green-400" strokeWidth={1.5} />
        </div>

        <h1 className="text-[24px] font-bold text-[var(--foreground)] mb-3">
          {isApprovedSignup ? 'Đăng ký thành công!' : 'Cảm ơn bạn đã đăng ký!'}
        </h1>

        <p className="text-[15px] text-[var(--muted)] mb-6">
          {message}
        </p>

        {isApprovedSignup ? (
          <Link
            href="/login"
            className="inline-flex items-center gap-2 px-6 py-3 bg-[var(--primary)] text-[var(--primary-foreground)] rounded-lg font-medium hover:opacity-90"
          >
            Đăng nhập ngay
            <ArrowRight className="w-4 h-4" strokeWidth={1.5} />
          </Link>
        ) : (
          <Link
            href="/"
            className="inline-flex items-center gap-2 text-[var(--foreground)] font-medium hover:underline"
          >
            Quay lại trang chủ
            <ArrowRight className="w-4 h-4" strokeWidth={1.5} />
          </Link>
        )}
      </div>
    )
  }

  // Step 1: Check email
  if (step === 'check_email') {
    return (
      <div className="bg-[var(--card)] rounded-2xl shadow-executive-lg border border-[var(--border)] p-8">
        <div className="text-center mb-8">
          <h1 className="text-[24px] font-bold text-[var(--foreground)] mb-2">
            Đăng ký InboxAI
          </h1>
          <p className="text-[var(--muted)]">
            Nhập email để kiểm tra quyền truy cập
          </p>
        </div>

        <form onSubmit={handleCheckEmail} className="space-y-4">
          {error && (
            <div className="p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-red-600 dark:text-red-400 text-[14px] flex items-center gap-2">
              <AlertCircle className="w-4 h-4 flex-shrink-0" />
              {error}
            </div>
          )}

          <div>
            <label htmlFor="email" className="block text-[14px] font-medium text-[var(--foreground)] mb-1">
              Email
            </label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--muted-foreground)]" strokeWidth={1.5} />
              <input
                id="email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="email@example.com"
                required
                className="w-full pl-10 pr-4 py-2.5 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
              />
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[var(--primary)] text-[var(--primary-foreground)] py-2.5 rounded-lg font-medium hover:opacity-90 transition-opacity flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" strokeWidth={1.5} />
                Đang kiểm tra...
              </>
            ) : (
              <>
                Tiếp tục
                <ArrowRight className="w-4 h-4" strokeWidth={1.5} />
              </>
            )}
          </button>
        </form>

        <div className="mt-6 text-center text-[14px] text-[var(--muted)]">
          Đã có tài khoản?{' '}
          <Link href="/login" className="text-[var(--foreground)] font-medium hover:underline">
            Đăng nhập
          </Link>
        </div>
      </div>
    )
  }

  // Step 2a: Real signup form (for approved users or open beta)
  if (step === 'signup_form') {
    const isOpenBeta = message.includes('Open Beta')

    return (
      <div className="bg-[var(--card)] rounded-2xl shadow-executive-lg border border-[var(--border)] p-8">
        <div className="text-center mb-6">
          <div className="w-12 h-12 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-4">
            <CheckCircle className="w-6 h-6 text-green-600 dark:text-green-400" strokeWidth={1.5} />
          </div>
          <h1 className="text-[24px] font-bold text-[var(--foreground)] mb-2">
            {isOpenBeta ? 'Tạo tài khoản' : 'Email đã được duyệt!'}
          </h1>
          <p className="text-[var(--muted)]">
            {isOpenBeta ? message : 'Hoàn tất đăng ký để sử dụng InboxAI'}
          </p>
        </div>

        <form onSubmit={handleSignup} className="space-y-4">
          {error && (
            <div className="p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-red-600 dark:text-red-400 text-[14px] flex items-center gap-2">
              <AlertCircle className="w-4 h-4 flex-shrink-0" />
              {error}
            </div>
          )}

          <div className="p-3 bg-[var(--secondary)] rounded-lg">
            <p className="text-[14px] text-[var(--muted-foreground)]">
              <strong>Email:</strong> {email}
            </p>
          </div>

          <div>
            <label htmlFor="fullName" className="block text-[14px] font-medium text-[var(--foreground)] mb-1">
              Họ và tên
            </label>
            <div className="relative">
              <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--muted-foreground)]" strokeWidth={1.5} />
              <input
                id="fullName"
                type="text"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                placeholder="Nguyễn Văn A"
                required
                className="w-full pl-10 pr-4 py-2.5 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
              />
            </div>
          </div>

          <div>
            <label htmlFor="password" className="block text-[14px] font-medium text-[var(--foreground)] mb-1">
              Mật khẩu
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--muted-foreground)]" strokeWidth={1.5} />
              <input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Tối thiểu 6 ký tự"
                required
                minLength={6}
                className="w-full pl-10 pr-4 py-2.5 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
              />
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[var(--primary)] text-[var(--primary-foreground)] py-2.5 rounded-lg font-medium hover:opacity-90 transition-opacity flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" strokeWidth={1.5} />
                Đang tạo tài khoản...
              </>
            ) : (
              <>
                Tạo tài khoản
                <ArrowRight className="w-4 h-4" strokeWidth={1.5} />
              </>
            )}
          </button>
        </form>

        <button
          onClick={() => { setStep('check_email'); setError(null) }}
          className="w-full mt-4 text-[14px] text-[var(--muted)] hover:text-[var(--foreground)]"
        >
          Dùng email khác
        </button>
      </div>
    )
  }

  // Step 2b: Waitlist form (for non-approved users)
  if (step === 'waitlist_form') {
    return (
      <div className="bg-[var(--card)] rounded-2xl shadow-executive-lg border border-[var(--border)] p-8">
        <div className="text-center mb-6">
          <div className="w-12 h-12 bg-orange-100 dark:bg-orange-900/30 rounded-full flex items-center justify-center mx-auto mb-4">
            <Clock className="w-6 h-6 text-orange-600 dark:text-orange-400" strokeWidth={1.5} />
          </div>

          {waitlistStatus === 'pending' ? (
            <>
              <h1 className="text-[24px] font-bold text-[var(--foreground)] mb-2">
                Đang chờ duyệt
              </h1>
              <p className="text-[var(--muted)]">
                {message || 'Yêu cầu của bạn đang được xem xét'}
              </p>
            </>
          ) : waitlistStatus === 'beta_full' ? (
            <>
              <h1 className="text-[24px] font-bold text-[var(--foreground)] mb-2">
                Beta đã đầy
              </h1>
              <p className="text-[var(--muted)]">
                {message || 'Đăng ký waitlist để được thông báo'}
              </p>
            </>
          ) : (
            <>
              <h1 className="text-[24px] font-bold text-[var(--foreground)] mb-2">
                Đăng ký Waitlist
              </h1>
              <p className="text-[var(--muted)]">
                InboxAI đang trong Private Beta
              </p>
            </>
          )}
        </div>

        {waitlistStatus === 'pending' ? (
          <div className="space-y-4">
            <div className="p-4 bg-orange-50 dark:bg-orange-900/20 border border-orange-200 dark:border-orange-800 rounded-lg">
              <p className="text-[14px] text-orange-700 dark:text-orange-300">
                Email <strong>{email}</strong> đã đăng ký và đang chờ duyệt.
                Bạn sẽ nhận được email khi được chấp nhận.
              </p>
            </div>

            <Link
              href="/"
              className="w-full bg-[var(--secondary)] text-[var(--foreground)] py-2.5 rounded-lg font-medium hover:bg-[var(--hover)] transition-colors flex items-center justify-center gap-2"
            >
              Quay lại trang chủ
            </Link>
          </div>
        ) : (
          <form onSubmit={handleWaitlist} className="space-y-4">
            {error && (
              <div className="p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-red-600 dark:text-red-400 text-[14px] flex items-center gap-2">
                <AlertCircle className="w-4 h-4 flex-shrink-0" />
                {error}
              </div>
            )}

            <div className="p-3 bg-[var(--secondary)] rounded-lg">
              <p className="text-[14px] text-[var(--muted-foreground)]">
                <strong>Email:</strong> {email}
              </p>
            </div>

            <div>
              <label htmlFor="fullName" className="block text-[14px] font-medium text-[var(--foreground)] mb-1">
                Họ và tên
              </label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--muted-foreground)]" strokeWidth={1.5} />
                <input
                  id="fullName"
                  type="text"
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  placeholder="Nguyễn Văn A"
                  required
                  className="w-full pl-10 pr-4 py-2.5 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-[var(--primary)] text-[var(--primary-foreground)] py-2.5 rounded-lg font-medium hover:opacity-90 transition-opacity flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" strokeWidth={1.5} />
                  Đang đăng ký...
                </>
              ) : (
                <>
                  Đăng ký Waitlist
                  <ArrowRight className="w-4 h-4" strokeWidth={1.5} />
                </>
              )}
            </button>
          </form>
        )}

        <button
          onClick={() => { setStep('check_email'); setError(null); setWaitlistStatus(null) }}
          className="w-full mt-4 text-[14px] text-[var(--muted)] hover:text-[var(--foreground)]"
        >
          Dùng email khác
        </button>

        <div className="mt-4 p-3 bg-[var(--secondary)] rounded-lg">
          <p className="text-[12px] text-[var(--muted-foreground)] text-center">
            Chúng tôi sẽ gửi email mời khi có slot mới.
          </p>
        </div>
      </div>
    )
  }

  return null
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import {
  ListTodo, CheckCircle2, Circle, Clock, HelpCircle,
  Calendar, RefreshCw, AlertTriangle, Loader2, Filter,
  ChevronDown, Mail, Sparkles
} from 'lucide-react'
import { cn } from '@/lib/utils'

interface ActionItem {
  id: string
  type: 'task' | 'deadline' | 'question' | 'meeting' | 'follow_up'
  title: string
  description: string | null
  due_date: string | null
  priority: 'high' | 'medium' | 'low'
  status: 'pending' | 'in_progress' | 'completed' | 'dismissed'
  context: string
  email?: {
    id: string
    subject: string
    from_name: string | null
    from_address: string
    received_at: string
  }
}

const typeIcons: Record<string, React.ComponentType<{ className?: string }>> = {
  task: ListTodo,
  deadline: Clock,
  question: HelpCircle,
  meeting: Calendar,
  follow_up: RefreshCw,
}

const typeLabels: Record<string, string> = {
  task: 'Việc cần làm',
  deadline: 'Hạn chót',
  question: 'Câu hỏi',
  meeting: 'Cuộc họp',
  follow_up: 'Theo dõi',
}

const priorityColors: Record<string, string> = {
  high: 'text-gray-900 dark:text-white bg-red-50 dark:bg-red-500/10',
  medium: 'text-gray-900 dark:text-white bg-amber-50 dark:bg-amber-500/10',
  low: 'text-gray-900 dark:text-white bg-gray-50 dark:bg-gray-500/10',
}

const priorityLabels: Record<string, string> = {
  high: 'Gấp',
  medium: 'Trung bình',
  low: 'Thấp',
}

const statusFilters = [
  { value: '', label: 'Tất cả' },
  { value: 'pending', label: 'Chưa làm' },
  { value: 'completed', label: 'Đã hoàn thành' },
]

const typeFilters = [
  { value: '', label: 'Tất cả loại' },
  { value: 'task', label: 'Việc cần làm' },
  { value: 'deadline', label: 'Hạn chót' },
  { value: 'question', label: 'Câu hỏi' },
  { value: 'meeting', label: 'Cuộc họp' },
  { value: 'follow_up', label: 'Theo dõi' },
]

export default function ActionsPage() {
  const router = useRouter()
  const [actions, setActions] = useState<ActionItem[]>([])
  const [loading, setLoading] = useState(true)
  const [statusFilter, setStatusFilter] = useState('')
  const [typeFilter, setTypeFilter] = useState('')
  const [showFilters, setShowFilters] = useState(false)

  useEffect(() => {
    fetchActions()
  }, [statusFilter, typeFilter])

  const fetchActions = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams()
      if (statusFilter) params.set('status', statusFilter)
      if (typeFilter) params.set('type', typeFilter)

      const res = await fetch(`/api/action-items?${params.toString()}`)
      const data = await res.json()
      setActions(data.actions || [])
    } catch (error) {
      console.error('Failed to fetch actions:', error)
    } finally {
      setLoading(false)
    }
  }

  const toggleStatus = async (actionId: string, currentStatus: string) => {
    const newStatus = currentStatus === 'completed' ? 'pending' : 'completed'

    setActions(prev => prev.map(a =>
      a.id === actionId ? { ...a, status: newStatus as ActionItem['status'] } : a
    ))

    try {
      await fetch(`/api/action-items/${actionId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus })
      })
    } catch (error) {
      setActions(prev => prev.map(a =>
        a.id === actionId ? { ...a, status: currentStatus as ActionItem['status'] } : a
      ))
      console.error('Failed to update status:', error)
    }
  }

  const formatDueDate = (date: string | null) => {
    if (!date) return null
    const d = new Date(date)
    const today = new Date()
    const tomorrow = new Date(today)
    tomorrow.setDate(tomorrow.getDate() + 1)

    if (d.toDateString() === today.toDateString()) return 'Hôm nay'
    if (d.toDateString() === tomorrow.toDateString()) return 'Ngày mai'

    const diffDays = Math.ceil((d.getTime() - today.getTime()) / (1000 * 60 * 60 * 24))
    if (diffDays < 0) return `Quá hạn ${Math.abs(diffDays)} ngày`
    if (diffDays <= 7) return `${diffDays} ngày nữa`

    return d.toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' })
  }

  const goToEmail = (emailId: string) => {
    router.push(`/inbox?email=${emailId}`)
  }

  // Group actions by priority
  const highPriority = actions.filter(a => a.priority === 'high' && a.status !== 'completed')
  const mediumPriority = actions.filter(a => a.priority === 'medium' && a.status !== 'completed')
  const lowPriority = actions.filter(a => a.priority === 'low' && a.status !== 'completed')
  const completed = actions.filter(a => a.status === 'completed')

  const pendingCount = actions.filter(a => a.status !== 'completed').length

  return (
    <div className="flex-1 overflow-y-auto bg-[var(--background)]">
      <div className="max-w-4xl mx-auto py-8 px-6">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-3">
            <ListTodo className="w-6 h-6 text-gray-500 dark:text-gray-400" strokeWidth={1.5} />
            <div>
              <h1 className="text-[20px] font-semibold text-[var(--foreground)]">
                Actions
              </h1>
              <p className="text-[14px] text-[var(--muted)]">
                {pendingCount} việc cần làm từ email
              </p>
            </div>
          </div>

          {/* Filter toggle */}
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={cn(
              'flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors',
              showFilters
                ? 'bg-[var(--primary)] text-[var(--primary-foreground)]'
                : 'bg-[var(--secondary)] text-[var(--foreground)] hover:bg-[var(--hover)]'
            )}
          >
            <Filter className="w-4 h-4" />
            Lọc
            <ChevronDown className={cn('w-4 h-4 transition-transform', showFilters && 'rotate-180')} />
          </button>
        </div>

        {/* Filters */}
        {showFilters && (
          <div className="flex flex-wrap gap-3 mb-6 p-4 bg-[var(--card)] rounded-xl border border-[var(--border)]">
            <div>
              <label className="block text-xs font-medium text-[var(--muted)] mb-1.5">Trạng thái</label>
              <div className="flex gap-1">
                {statusFilters.map(f => (
                  <button
                    key={f.value}
                    onClick={() => setStatusFilter(f.value)}
                    className={cn(
                      'px-3 py-1.5 text-sm rounded-lg transition-colors',
                      statusFilter === f.value
                        ? 'bg-[var(--primary)] text-[var(--primary-foreground)]'
                        : 'bg-[var(--secondary)] text-[var(--foreground)] hover:bg-[var(--hover)]'
                    )}
                  >
                    {f.label}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-[var(--muted)] mb-1.5">Loại</label>
              <div className="flex flex-wrap gap-1">
                {typeFilters.map(f => (
                  <button
                    key={f.value}
                    onClick={() => setTypeFilter(f.value)}
                    className={cn(
                      'px-3 py-1.5 text-sm rounded-lg transition-colors',
                      typeFilter === f.value
                        ? 'bg-[var(--primary)] text-[var(--primary-foreground)]'
                        : 'bg-[var(--secondary)] text-[var(--foreground)] hover:bg-[var(--hover)]'
                    )}
                  >
                    {f.label}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Loading */}
        {loading && (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin text-[var(--muted)]" />
          </div>
        )}

        {/* Empty state */}
        {!loading && actions.length === 0 && (
          <div className="flex flex-col items-center justify-center py-16 text-center">
            <div className="w-16 h-16 rounded-2xl bg-[var(--secondary)] flex items-center justify-center mb-4">
              <Sparkles className="w-8 h-8 text-[var(--muted)]" />
            </div>
            <h3 className="text-lg font-semibold text-[var(--foreground)] mb-2">
              Chưa có action nào
            </h3>
            <p className="text-sm text-[var(--muted)] max-w-sm">
              Mở một email và nhấn &quot;Trích xuất Actions&quot; để AI phân tích và tìm các việc cần làm
            </p>
          </div>
        )}

        {/* Action sections */}
        {!loading && actions.length > 0 && (
          <div className="space-y-6">
            {/* High priority */}
            {highPriority.length > 0 && (
              <ActionSection
                title="Gấp"
                icon={AlertTriangle}
                iconBg="bg-red-100 dark:bg-red-500/20"
                iconColor="text-gray-900 dark:text-white"
                actions={highPriority}
                onToggle={toggleStatus}
                onGoToEmail={goToEmail}
                formatDueDate={formatDueDate}
              />
            )}

            {/* Medium priority */}
            {mediumPriority.length > 0 && (
              <ActionSection
                title="Trung bình"
                icon={Clock}
                iconBg="bg-amber-100 dark:bg-amber-500/20"
                iconColor="text-gray-900 dark:text-white"
                actions={mediumPriority}
                onToggle={toggleStatus}
                onGoToEmail={goToEmail}
                formatDueDate={formatDueDate}
              />
            )}

            {/* Low priority */}
            {lowPriority.length > 0 && (
              <ActionSection
                title="Thấp"
                icon={ListTodo}
                iconBg="bg-gray-100 dark:bg-gray-500/20"
                iconColor="text-gray-900 dark:text-white"
                actions={lowPriority}
                onToggle={toggleStatus}
                onGoToEmail={goToEmail}
                formatDueDate={formatDueDate}
              />
            )}

            {/* Completed */}
            {completed.length > 0 && (
              <ActionSection
                title="Đã hoàn thành"
                icon={CheckCircle2}
                iconBg="bg-green-100 dark:bg-green-500/20"
                iconColor="text-gray-900 dark:text-white"
                actions={completed}
                onToggle={toggleStatus}
                onGoToEmail={goToEmail}
                formatDueDate={formatDueDate}
                collapsed
              />
            )}
          </div>
        )}
      </div>
    </div>
  )
}

interface ActionSectionProps {
  title: string
  icon: React.ComponentType<{ className?: string }>
  iconBg: string
  iconColor: string
  actions: ActionItem[]
  onToggle: (id: string, status: string) => void
  onGoToEmail: (emailId: string) => void
  formatDueDate: (date: string | null) => string | null
  collapsed?: boolean
}

function ActionSection({
  title,
  icon: Icon,
  iconBg,
  iconColor,
  actions,
  onToggle,
  onGoToEmail,
  formatDueDate,
  collapsed = false
}: ActionSectionProps) {
  const [isExpanded, setIsExpanded] = useState(!collapsed)

  return (
    <div className="bg-[var(--card)] rounded-xl border border-[var(--border)] overflow-hidden">
      {/* Section header */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="w-full flex items-center justify-between p-4 hover:bg-[var(--hover)] transition-colors"
      >
        <div className="flex items-center gap-3">
          <Icon className={cn('w-5 h-5', iconColor)} />
          <span className="font-semibold text-[var(--foreground)]">
            {title} ({actions.length})
          </span>
        </div>
        <ChevronDown className={cn(
          'w-5 h-5 text-[var(--muted)] transition-transform',
          isExpanded && 'rotate-180'
        )} />
      </button>

      {/* Actions */}
      {isExpanded && (
        <div className="border-t border-[var(--border)] divide-y divide-[var(--border)]">
          {actions.map(action => {
            const TypeIcon = typeIcons[action.type] || ListTodo
            const isCompleted = action.status === 'completed'
            const dueDateText = formatDueDate(action.due_date)
            const isOverdue = dueDateText?.includes('Quá hạn')

            return (
              <div
                key={action.id}
                className={cn(
                  'flex items-start gap-3 p-4 hover:bg-[var(--hover)] transition-colors',
                  isCompleted && 'opacity-60'
                )}
              >
                {/* Checkbox */}
                <button
                  onClick={() => onToggle(action.id, action.status)}
                  className={cn(
                    'flex-shrink-0 mt-0.5 transition-colors',
                    isCompleted
                      ? 'text-green-500'
                      : 'text-[var(--muted-foreground)] hover:text-green-500'
                  )}
                >
                  {isCompleted ? (
                    <CheckCircle2 className="w-5 h-5" />
                  ) : (
                    <Circle className="w-5 h-5" />
                  )}
                </button>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-start justify-between gap-2">
                    <p className={cn(
                      'text-sm font-medium text-[var(--foreground)]',
                      isCompleted && 'line-through'
                    )}>
                      {action.title}
                    </p>
                    <span className={cn(
                      'flex-shrink-0 px-2 py-0.5 text-[11px] font-semibold rounded',
                      priorityColors[action.priority]
                    )}>
                      {priorityLabels[action.priority]}
                    </span>
                  </div>

                  {/* Meta row */}
                  <div className="flex items-center gap-3 mt-1.5 flex-wrap">
                    <span className="flex items-center gap-1 text-xs text-[var(--muted)]">
                      <TypeIcon className="w-3 h-3" />
                      {typeLabels[action.type]}
                    </span>
                    {dueDateText && (
                      <span className={cn(
                        'flex items-center gap-1 text-xs',
                        isOverdue
                          ? 'text-red-600 dark:text-red-400 font-medium'
                          : 'text-[var(--muted)]'
                      )}>
                        <Clock className="w-3 h-3" />
                        {dueDateText}
                      </span>
                    )}
                    {action.email && (
                      <button
                        onClick={() => onGoToEmail(action.email!.id)}
                        className="flex items-center gap-1 text-xs text-blue-600 dark:text-blue-400 hover:underline"
                      >
                        <Mail className="w-3 h-3" />
                        {action.email.subject || '(Không tiêu đề)'}
                      </button>
                    )}
                  </div>

                  {/* Context quote */}
                  {action.context && (
                    <p className="mt-2 text-xs text-[var(--foreground-subtle)] italic line-clamp-2 pl-2 border-l-2 border-[var(--border)]">
                      {`"${action.context}"`}
                    </p>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

