  const handleEmptyTrash = async () => {
    if (confirm(`Xóa vĩnh viễn ${emails.length} email? Hành động này không thể hoàn tác.`)) {
      setIsEmptying(true)
      await emptyTrash()
      setIsEmptying(false)
