                </pre>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { NextRequest, NextResponse } from 'next/server'
import { createClientForRequest } from '@/lib/supabase/server'

interface BriefingItem {
  type: 'urgent' | 'deadline' | 'waiting' | 'vip'
  icon: string
  title: string
  description: string
  count: number
  emailIds: string[]
}

interface CleanupItem {
  type: 'newsletter' | 'promotion'
  title: string
  description: string
  action: 'archive' | 'delete'
  emailIds: string[]
}

function getGreeting(): string {
  const hour = new Date().getHours()
  if (hour >= 5 && hour < 12) return 'Chào buổi sáng'
  if (hour >= 12 && hour < 18) return 'Chào buổi chiều'
  if (hour >= 18 && hour < 22) return 'Chào buổi tối'
  return 'Làm việc khuya'
}

// GET - Daily briefing (supports mobile + web auth)
export async function GET(request: NextRequest) {
  const supabase = await createClientForRequest(request)
  const { data: { user } } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const now = new Date()
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const yesterday = new Date(today.getTime() - 24 * 60 * 60 * 1000)
  const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000)

  // Fetch all relevant emails
  const { data: emails } = await supabase
    .from('emails')
    .select('*')
    .eq('user_id', user.id)
    .eq('is_deleted', false)
    .eq('is_archived', false)
    .order('received_at', { ascending: false })

  if (!emails) {
    return NextResponse.json({ error: 'Failed to fetch emails' }, { status: 500 })
  }

  // === URGENT ITEMS ===

  // Emails cần trả lời (needs_reply = true, chưa đọc)
  const needsReply = emails.filter(e =>
    e.needs_reply &&
    !e.is_read &&
    e.direction === 'inbound'
  )

  // Emails quan trọng chưa đọc (priority >= 4)
  const urgentUnread = emails.filter(e =>
    !e.is_read &&
    (e.priority || 3) >= 4
  )

  // Emails có deadline hôm nay hoặc quá hạn
  const hasDeadlineToday = emails.filter(e => {
    if (!e.detected_deadline) return false
    const deadline = new Date(e.detected_deadline)
    return deadline <= new Date(today.getTime() + 24 * 60 * 60 * 1000)
  })

  // Emails chờ reply quá 24h
  const waitingReplyLong = emails.filter(e => {
    if (!e.needs_reply || e.is_read) return false
    const received = new Date(e.received_at)
    return received < yesterday
  })

  // === STATS ===

  const unreadCount = emails.filter(e => !e.is_read).length
  const todayCount = emails.filter(e => new Date(e.received_at) >= today).length

  // Category breakdown
  const byCategory = {
    work: emails.filter(e => e.category === 'work' && !e.is_read).length,
    personal: emails.filter(e => e.category === 'personal' && !e.is_read).length,
    newsletter: emails.filter(e => e.category === 'newsletter' && !e.is_read).length,
    promotion: emails.filter(e => e.category === 'promotion' && !e.is_read).length,
    transaction: emails.filter(e => e.category === 'transaction' && !e.is_read).length,
  }

  // === CLEANUP SUGGESTIONS ===

  // Newsletter cũ (>7 ngày, chưa đọc)
  const oldNewsletter = emails.filter(e => {
    if (e.category !== 'newsletter' || e.is_read) return false
    return new Date(e.received_at) < weekAgo
  })

  // Promotion cũ (>7 ngày, chưa đọc)
  const oldPromotion = emails.filter(e => {
    if (e.category !== 'promotion' || e.is_read) return false
    return new Date(e.received_at) < weekAgo
  })

  // === VIP SENDERS ===
  const { data: vipSenders } = await supabase
    .from('sender_scores')
    .select('sender_email, sender_name')
    .eq('user_id', user.id)
    .eq('is_vip', true)

  const vipEmails = vipSenders
    ? emails.filter(e =>
      !e.is_read &&
      vipSenders.some(v => v.sender_email === e.from_address)
    )
    : []

  // === GENERATE BRIEFING ===
  const greeting = getGreeting()

  const briefingItems: BriefingItem[] = []

  if (urgentUnread.length > 0) {
    briefingItems.push({
      type: 'urgent',
      icon: 'AlertCircle',
      title: `${urgentUnread.length} email quan trọng`,
      description: 'Cần xem ngay',
      count: urgentUnread.length,
      emailIds: urgentUnread.slice(0, 5).map(e => e.id)
    })
  }

  if (hasDeadlineToday.length > 0) {
    briefingItems.push({
      type: 'deadline',
      icon: 'Clock',
      title: `${hasDeadlineToday.length} email có deadline`,
      description: 'Hôm nay hoặc đã quá hạn',
      count: hasDeadlineToday.length,
      emailIds: hasDeadlineToday.map(e => e.id)
    })
  }

  if (waitingReplyLong.length > 0) {
    briefingItems.push({
      type: 'waiting',
      icon: 'MessageCircle',
      title: `${waitingReplyLong.length} email chờ phản hồi`,
      description: 'Quá 24 giờ chưa trả lời',
      count: waitingReplyLong.length,
      emailIds: waitingReplyLong.map(e => e.id)
    })
  }

  if (vipEmails.length > 0) {
    briefingItems.push({
      type: 'vip',
      icon: 'Star',
      title: `${vipEmails.length} email từ VIP`,
      description: 'Người gửi quan trọng',
      count: vipEmails.length,
      emailIds: vipEmails.map(e => e.id)
    })
  }

  // Cleanup suggestions
  const cleanupItems: CleanupItem[] = []

  if (oldNewsletter.length >= 3) {
    cleanupItems.push({
      type: 'newsletter',
      title: `${oldNewsletter.length} newsletter cũ`,
      description: 'Chưa đọc hơn 7 ngày',
      action: 'archive',
      emailIds: oldNewsletter.map(e => e.id)
    })
  }

  if (oldPromotion.length >= 3) {
    cleanupItems.push({
      type: 'promotion',
      title: `${oldPromotion.length} khuyến mãi cũ`,
      description: 'Chưa đọc hơn 7 ngày',
      action: 'delete',
      emailIds: oldPromotion.map(e => e.id)
    })
  }

  return NextResponse.json({
    greeting,
    summary: {
      total: emails.length,
      unread: unreadCount,
      today: todayCount,
      byCategory
    },
    briefingItems,
    cleanupItems,
    generatedAt: now.toISOString()
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { createClient as createServiceClient } from '@supabase/supabase-js'
import { classifyEmail } from '@/lib/ai/classifier'

const supabaseService = createServiceClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
)

export async function POST(request: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Get all unclassified emails (ai_confidence is null or low)
  const { data: emails, error } = await supabaseService
    .from('emails')
    .select('*')
    .eq('user_id', user.id)
    .or('ai_confidence.is.null,ai_confidence.lt.0.5')
    .limit(20)

  if (error || !emails) {
    return NextResponse.json({ error: 'Failed to fetch emails' }, { status: 500 })
  }

  if (emails.length === 0) {
    return NextResponse.json({
      message: 'No emails to classify',
      total: 0,
      results: []
    })
  }

  const results = []

  for (const email of emails) {
    try {
      const classification = await classifyEmail({
        from_address: email.from_address,
        from_name: email.from_name,
        subject: email.subject,
        body_text: email.body_text,
        body_html: email.body_html
      })

      await supabaseService
        .from('emails')
        .update({
          priority: classification.priority,
          category: classification.category,
          summary: classification.summary,
          detected_deadline: classification.deadline,
          needs_reply: classification.needs_reply,
          ai_confidence: classification.confidence,
          ai_suggestions: {
            suggested_labels: classification.suggested_labels,
            suggested_action: classification.suggested_action,
            key_entities: classification.key_entities
          }
        })
        .eq('id', email.id)

      results.push({
        id: email.id,
        subject: email.subject,
        status: 'success',
        classification: {
          priority: classification.priority,
          category: classification.category,
          summary: classification.summary
        }
      })
    } catch (err) {
      results.push({
        id: email.id,
        subject: email.subject,
        status: 'error',
        error: String(err)
      })
    }
  }

  return NextResponse.json({
    total: emails.length,
    success: results.filter(r => r.status === 'success').length,
    failed: results.filter(r => r.status === 'error').length,
    results
  })
}

/**
 * POST /api/ai/features/[emailId]/auto
 * Batch run all auto-enabled AI features in PARALLEL
 * Optimized for single API call instead of multiple sequential calls
 *
 * Supports both:
 * - Cookie-based auth (web)
 * - Bearer token auth (mobile apps)
 */

import { NextRequest, NextResponse } from 'next/server';
import { createClientForRequest } from '@/lib/supabase/server';
import {
  getFeatureAllocationForEmail,
  getAIFeatureAllocationService,
  AIFeatureKey,
  FEATURE_COSTS,
} from '@/lib/ai/feature-allocation';
import { getAIFeatureRunner } from '@/lib/ai/feature-runner';
import { ensureAIModuleInitialized } from '@/lib/ai/setup';
import { aiLogger } from '@/lib/logger';

interface FeatureResultWithMeta {
  status: 'success' | 'error';
  data?: unknown;
  error?: string;
  cost: number;
  timeMs: number;
  cached?: boolean;
}

/**
 * Strip HTML tags and decode entities to get plain text
 * Used for existing emails that have body_html but empty body_text
 */
function stripHtmlTags(html: string): string {
  // Remove script and style tags with their content
  let text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

  // Replace block elements with newlines
  text = text.replace(/<\/(p|div|tr|li|h[1-6]|br)>/gi, '\n');
  text = text.replace(/<br\s*\/?>/gi, '\n');

  // Remove all remaining tags
  text = text.replace(/<[^>]+>/g, ' ');

  // Decode common HTML entities
  text = text.replace(/&nbsp;/gi, ' ');
  text = text.replace(/&amp;/gi, '&');
  text = text.replace(/&lt;/gi, '<');
  text = text.replace(/&gt;/gi, '>');
  text = text.replace(/&quot;/gi, '"');
  text = text.replace(/&#39;/gi, "'");
  text = text.replace(/&rsquo;/gi, "'");
  text = text.replace(/&lsquo;/gi, "'");
  text = text.replace(/&rdquo;/gi, '"');
  text = text.replace(/&ldquo;/gi, '"');
  text = text.replace(/&mdash;/gi, '—');
  text = text.replace(/&ndash;/gi, '–');

  // Clean up whitespace
  text = text.replace(/\n\s*\n/g, '\n\n');
  text = text.replace(/[ \t]+/g, ' ');
  text = text.trim();

  return text;
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ emailId: string }> }
) {
  const startTime = Date.now();
  aiLogger.debug('[BatchAPI] === START ===');

  try {
    // Step 1: Get params
    const { emailId } = await params;
    aiLogger.debug('[BatchAPI] Step 1 - emailId:', emailId);

    if (!emailId) {
      aiLogger.debug('[BatchAPI] ERROR: No emailId');
      return NextResponse.json({ error: 'emailId is required' }, { status: 400 });
    }

    // Step 2: Ensure AI module is initialized
    aiLogger.debug('[BatchAPI] Step 2 - Initializing AI module...');
    await ensureAIModuleInitialized();
    aiLogger.debug('[BatchAPI] Step 2 - AI module initialized');

    // Step 3: Create Supabase client (supports both Bearer token and cookies)
    aiLogger.debug('[BatchAPI] Step 3 - Creating Supabase client...');
    const supabase = await createClientForRequest(request);
    aiLogger.debug('[BatchAPI] Step 3 - Supabase client created');

    // Step 4: Get current user
    aiLogger.debug('[BatchAPI] Step 4 - Getting user...');
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    aiLogger.debug('[BatchAPI] Step 4 - User:', user?.id, 'AuthError:', authError?.message);

    if (authError || !user) {
      aiLogger.debug('[BatchAPI] ERROR: Unauthorized');
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Step 5: Get email data
    aiLogger.debug('[BatchAPI] Step 5 - Fetching email:', emailId);
    const { data: email, error: emailError } = await supabase
      .from('emails')
      .select(`
        id,
        category,
        priority,
        from_address,
        from_name,
        subject,
        body_text,
        body_html,
        summary,
        ai_suggestions,
        ai_features_used,
        ai_total_cost_usd
      `)
      .eq('id', emailId)
      .eq('user_id', user.id)
      .single();

    aiLogger.debug('[BatchAPI] Step 5 - Email found:', !!email, 'Error:', emailError?.message);

    if (emailError || !email) {
      aiLogger.debug('[BatchAPI] ERROR: Email not found');
      return NextResponse.json({ error: 'Email not found' }, { status: 404 });
    }

    // FIX: If body_text is empty but body_html exists, extract text from HTML
    let bodyText = email.body_text as string | null;
    const bodyHtml = email.body_html as string | null;

    aiLogger.debug('[BatchAPI] DEBUG body_text length:', bodyText?.length || 0);
    aiLogger.debug('[BatchAPI] DEBUG body_html length:', bodyHtml?.length || 0);

    if ((!bodyText || bodyText.trim().length < 20) && bodyHtml && bodyHtml.length > 0) {
      aiLogger.debug('[BatchAPI] body_text empty/short, extracting from HTML...');
      bodyText = stripHtmlTags(bodyHtml);
      aiLogger.debug('[BatchAPI] Extracted text length:', bodyText.length);
      aiLogger.debug('[BatchAPI] Extracted text preview:', bodyText.slice(0, 200));

      // Update email object for processing (don't save to DB here, just for this request)
      (email as Record<string, unknown>).body_text = bodyText;
    }

    aiLogger.debug('[BatchAPI] Final word count:', bodyText?.split(/\s+/).filter(w => w.length > 0).length || 0);

    // Step 6: Get allocation
    aiLogger.debug('[BatchAPI] Step 6 - Getting allocation...');
    const allocation = await getFeatureAllocationForEmail(user.id, email);
    aiLogger.debug('[BatchAPI] Step 6 - Allocation category:', allocation.category);
    aiLogger.debug('[BatchAPI] Step 6 - Auto features:', allocation.autoEnabledFeatures);
    aiLogger.debug('[BatchAPI] Step 6 - Available buttons:', allocation.availableButtons);

    // Collect existing results from database (cached)
    const existingResults: Record<string, FeatureResultWithMeta> = {};

    if (email.summary) {
      existingResults.summary = {
        status: 'success',
        data: email.summary,
        cost: 0,
        timeMs: 0,
        cached: true
      };
    }

    if (email.ai_suggestions) {
      const suggestions = email.ai_suggestions as Record<string, unknown>;

      if (suggestions.smart_replies || suggestions.smart_reply) {
        existingResults.smart_reply = {
          status: 'success',
          data: suggestions.smart_replies || suggestions.smart_reply,
          cost: 0,
          timeMs: 0,
          cached: true
        };
      }
      if (suggestions.action_items) {
        existingResults.action_items = {
          status: 'success',
          data: suggestions.action_items,
          cost: 0,
          timeMs: 0,
          cached: true
        };
      }
      if (suggestions.follow_up) {
        existingResults.follow_up = {
          status: 'success',
          data: suggestions.follow_up,
          cost: 0,
          timeMs: 0,
          cached: true
        };
      }
      if (suggestions.sentiment) {
        existingResults.sentiment = {
          status: 'success',
          data: suggestions.sentiment,
          cost: 0,
          timeMs: 0,
          cached: true
        };
      }
    }

    // Filter features that need to run (auto-enabled and not already cached)
    const featuresToRun = allocation.features
      .filter(f => f.isAutoEnabled && !existingResults[f.featureKey])
      .map(f => f.featureKey);

    // DEBUG: Log features to run
    aiLogger.debug('[BatchAPI] featuresToRun:', featuresToRun);
    aiLogger.debug('[BatchAPI] existingResults keys:', Object.keys(existingResults));

    // Run features in PARALLEL using Promise.allSettled
    const newResults: Record<string, FeatureResultWithMeta> = {};

    if (featuresToRun.length > 0) {
      const runner = getAIFeatureRunner();
      const service = getAIFeatureAllocationService();

      // DEBUG: Log registered executors
      aiLogger.debug('[BatchAPI] Registered executors:', runner.getRegisteredFeatures());

      // Create parallel promises
      const featurePromises = featuresToRun.map(async (featureKey): Promise<[AIFeatureKey, FeatureResultWithMeta]> => {
        const featureStartTime = Date.now();

        try {
          // Run the feature
          const result = await runner.runManualFeature(
            user.id,
            emailId,
            email as Record<string, unknown>,
            featureKey
          );

          const timeMs = Date.now() - featureStartTime;

          return [featureKey, {
            status: result.success ? 'success' : 'error',
            data: result.data,
            error: result.error,
            cost: result.cost,
            timeMs,
          }];
        } catch (error) {
          aiLogger.error(`Error running feature ${featureKey}:`, error);
          return [featureKey, {
            status: 'error',
            error: error instanceof Error ? error.message : 'Unknown error',
            cost: 0,
            timeMs: Date.now() - featureStartTime,
          }];
        }
      });

      // Wait for all features to complete (parallel)
      const settledResults = await Promise.allSettled(featurePromises);

      // Collect results
      for (const result of settledResults) {
        if (result.status === 'fulfilled') {
          const [key, value] = result.value;
          newResults[key] = value;
          aiLogger.debug(`[BatchAPI] Feature ${key} result:`, value.status, value.error || 'OK');
        } else {
          aiLogger.error('[BatchAPI] Promise rejected:', result.reason);
        }
      }

      // Save results to database
      const updateData: Record<string, unknown> = {};
      const aiSuggestions = (email.ai_suggestions as Record<string, unknown>) || {};

      for (const [featureKey, result] of Object.entries(newResults)) {
        if (result.status === 'success' && result.data) {
          if (featureKey === 'summary') {
            updateData.summary = result.data;
          } else {
            aiSuggestions[featureKey === 'smart_reply' ? 'smart_replies' : featureKey] = result.data;
          }
        }
      }

      if (Object.keys(aiSuggestions).length > 0) {
        updateData.ai_suggestions = aiSuggestions;
      }

      // Update features used
      const featuresUsed = [
        ...((email.ai_features_used as string[]) || []),
        ...Object.entries(newResults)
          .filter(([, r]) => r.status === 'success')
          .map(([k]) => k)
      ];
      updateData.ai_features_used = [...new Set(featuresUsed)];

      // Calculate total cost from new results
      const newCost = Object.values(newResults)
        .filter(r => r.status === 'success')
        .reduce((sum, r) => sum + (r.cost || 0), 0);

      if (newCost > 0) {
        updateData.ai_total_cost_usd = ((email.ai_total_cost_usd as number) || 0) + newCost;
      }

      if (Object.keys(updateData).length > 0) {
        await supabase
          .from('emails')
          .update(updateData)
          .eq('id', emailId);
      }
    }

    // Merge existing + new results
    const allResults = { ...existingResults, ...newResults };

    // Get buttons that can still be triggered manually
    const availableButtons = allocation.features
      .filter(f => f.isButtonVisible && !f.isAutoEnabled && !allResults[f.featureKey])
      .map(f => f.featureKey);

    // Calculate totals
    const totalCost = Object.values(newResults)
      .reduce((sum, r) => sum + (r.cost || 0), 0);

    const totalTimeMs = Date.now() - startTime;

    const response = {
      emailId,
      allocation: {
        category: allocation.category,
        priority: allocation.priority,
        isVipSender: allocation.isVipSender,
        contentTriggers: allocation.contentTriggers,
      },
      results: allResults,
      availableButtons,
      totalCost,
      totalTimeMs,
      cached: featuresToRun.length === 0,
    };

    // Step 7: Return response
    aiLogger.debug('[BatchAPI] Step 7 - Success! Results count:', Object.keys(allResults).length);
    aiLogger.debug('[BatchAPI] === END (success) ===');

    return NextResponse.json(response);

  } catch (error) {
    aiLogger.error('[BatchAPI] === ERROR ===');
    aiLogger.error('[BatchAPI] Error type:', error?.constructor?.name);
    aiLogger.error('[BatchAPI] Error message:', error instanceof Error ? error.message : String(error));
    aiLogger.error('[BatchAPI] Error stack:', error instanceof Error ? error.stack : 'N/A');
    return NextResponse.json(
      { error: 'Internal server error', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'

interface SenderScore {
  id: string
  sender_email: string
  sender_name: string | null
  importance_score: number
  engagement_score: number
  annoyance_score: number
  total_received: number
  total_opened: number
  total_replied: number
  total_deleted: number
  total_archived: number
  avg_read_time: number
  is_vip: boolean
  is_muted: boolean
}

export async function GET(request: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Get sender scores
  const { data: senders, error } = await supabase
    .from('sender_scores')
    .select('*')
    .eq('user_id', user.id)
    .order('total_received', { ascending: false })
    .limit(50)

  if (error) {
    console.error('Failed to fetch sender scores:', error)
    return NextResponse.json({ error: 'Failed to fetch data' }, { status: 500 })
  }

  const allSenders = (senders || []) as SenderScore[]

  // Categorize senders
  const vipSenders = allSenders.filter(s => s.importance_score >= 70 || s.is_vip)
  const engagedSenders = allSenders.filter(s => s.engagement_score >= 60)
  const annoyingSenders = allSenders.filter(s => s.annoyance_score >= 50)
  const topSenders = allSenders.slice(0, 10)

  // Calculate stats
  const totalEmails = allSenders.reduce((sum, s) => sum + s.total_received, 0)
  const totalOpened = allSenders.reduce((sum, s) => sum + s.total_opened, 0)
  const totalReplied = allSenders.reduce((sum, s) => sum + s.total_replied, 0)
  const totalDeleted = allSenders.reduce((sum, s) => sum + s.total_deleted, 0)

  const overallOpenRate = totalEmails > 0 ? Math.round((totalOpened / totalEmails) * 100) : 0
  const overallReplyRate = totalEmails > 0 ? Math.round((totalReplied / totalEmails) * 100) : 0
  const overallDeleteRate = totalEmails > 0 ? Math.round((totalDeleted / totalEmails) * 100) : 0

  return NextResponse.json({
    vipSenders,
    engagedSenders,
    annoyingSenders,
    topSenders,
    totalTracked: allSenders.length,
    stats: {
      totalEmails,
      totalOpened,
      totalReplied,
      totalDeleted,
      overallOpenRate,
      overallReplyRate,
      overallDeleteRate
    }
  })
}

// Update VIP status
export async function PATCH(request: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { senderEmail, isVip, isMuted } = await request.json()

  if (!senderEmail) {
    return NextResponse.json({ error: 'Missing sender email' }, { status: 400 })
  }

  const updates: Record<string, unknown> = { updated_at: new Date().toISOString() }

  if (typeof isVip === 'boolean') {
    updates.is_vip = isVip
  }

  if (typeof isMuted === 'boolean') {
    updates.is_muted = isMuted
  }

  const { error } = await supabase
    .from('sender_scores')
    .update(updates)
    .eq('user_id', user.id)
    .eq('sender_email', senderEmail)

  if (error) {
    console.error('Failed to update sender:', error)
    return NextResponse.json({ error: 'Update failed' }, { status: 500 })
  }

  return NextResponse.json({ success: true })
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { decryptPassword } from '@/lib/email/imap-client'

export const maxDuration = 30

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ attachmentId: string }> }
) {
  const { attachmentId } = await params
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Get attachment with email and source account info
  const { data: attachment, error } = await supabase
    .from('attachments')
    .select(`
      *,
      emails!inner (
        id, original_uid, user_id,
        source_accounts (
          id, imap_host, imap_port, imap_secure,
          username, password_encrypted
        )
      )
    `)
    .eq('id', attachmentId)
    .single()

  if (error || !attachment) {
    return NextResponse.json({ error: 'Attachment not found' }, { status: 404 })
  }

  // Verify user owns this email
  const emailData = attachment.emails as { user_id: string }
  if (emailData.user_id !== user.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
  }

  const email = attachment.emails as {
    id: string
    original_uid: string
    source_accounts: {
      id: string
      imap_host: string
      imap_port: number
      imap_secure: boolean
      username: string
      password_encrypted: string
    }
  }

  const account = email?.source_accounts

  if (!account || !email?.original_uid) {
    return NextResponse.json({ error: 'Source account not found' }, { status: 400 })
  }

  // Decrypt password
  let password: string
  try {
    password = decryptPassword(account.password_encrypted)
  } catch (e) {
    return NextResponse.json({ error: 'Decrypt failed' }, { status: 500 })
  }

  // Connect IMAP and fetch attachment
  try {
    const { ImapFlow } = await import('imapflow')
    const { simpleParser } = await import('mailparser')

    const client = new ImapFlow({
      host: account.imap_host,
      port: account.imap_port,
      secure: account.imap_secure !== false,
      auth: { user: account.username, pass: password },
      logger: false
    })

    await client.connect()
    const lock = await client.getMailboxLock('INBOX')

    try {
      // Fetch email by UID
      const message = await client.fetchOne(email.original_uid, {
        source: true
      }, { uid: true }) as { source?: Buffer } | false

      if (!message || !message.source) {
        return NextResponse.json({ error: 'Email not found on server' }, { status: 404 })
      }

      // Parse email
      const parsed = await simpleParser(message.source)

      // Find attachment by filename or content ID
      const att = parsed.attachments?.find(a =>
        a.filename === attachment.filename ||
        a.contentId?.replace(/[<>]/g, '') === attachment.content_id
      )

      if (!att) {
        return NextResponse.json({ error: 'Attachment not found in email' }, { status: 404 })
      }

      // Return attachment content
      const headers = new Headers()
      headers.set('Content-Type', att.contentType || 'application/octet-stream')
      headers.set('Content-Disposition', `inline; filename="${encodeURIComponent(att.filename || 'attachment')}"`)
      headers.set('Content-Length', att.size?.toString() || '0')
      headers.set('Cache-Control', 'private, max-age=3600')

      // Convert Buffer to Uint8Array for NextResponse
      const content = new Uint8Array(att.content)
      return new NextResponse(content, { headers })

    } finally {
      lock.release()
      try { await client.logout() } catch {}
    }

  } catch (e: unknown) {
    const errorMsg = e instanceof Error ? e.message : 'Unknown error'
    console.error('[ATTACHMENT] Error:', errorMsg)
    return NextResponse.json({ error: errorMsg }, { status: 500 })
  }
}

import { requireCronAuthorization } from '@/lib/security/cron'
import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { syncEmails } from '@/lib/email/imap-client'
import { getUnsubscribeService } from '@/lib/email/unsubscribe-service'
import { classifyEmail } from '@/lib/ai/classifier'
import { notifySyncComplete, notifyAiClassified } from '@/lib/notifications/create'

export const maxDuration = 300 // 5 minutes
export const dynamic = 'force-dynamic'

// OPTIMIZED CRON SETTINGS
const CRON_EMAILS_PER_ACCOUNT = 100 // Increased from 30
const CLASSIFY_BATCH_SIZE = 5 // Emails to classify per account

// Classify newly synced emails for a user
async function classifyUserEmails(
  userId: string,
  limit: number = CLASSIFY_BATCH_SIZE
): Promise<number> {
  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  )

  try {
    const { data: emails } = await supabase
      .from('emails')
      .select('id, from_address, from_name, subject, body_text, body_html')
      .eq('user_id', userId)
      .or('category.is.null,category.eq.uncategorized')
      .order('received_at', { ascending: false })
      .limit(limit)

    if (!emails || emails.length === 0) return 0

    let classified = 0
    for (const email of emails) {
      try {
        const classification = await classifyEmail({
          email_id: email.id,
          from_address: email.from_address,
          from_name: email.from_name,
          subject: email.subject,
          body_text: email.body_text,
          body_html: email.body_html,
          user_id: userId
        })

        await supabase
          .from('emails')
          .update({
            priority: classification.priority,
            category: classification.category,
            summary: classification.summary,
            detected_deadline: classification.deadline,
            needs_reply: classification.needs_reply,
            ai_confidence: classification.confidence,
            ai_suggestions: {
              suggested_labels: classification.suggested_labels,
              suggested_action: classification.suggested_action,
              key_entities: classification.key_entities
            }
          })
          .eq('id', email.id)

        classified++
      } catch {
        // Continue with next email
      }
    }

    return classified
  } catch {
    return 0
  }
}

export async function GET(request: NextRequest) {
  const denied = requireCronAuthorization(request)
  if (denied) return denied

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  )

  try {
    const startTime = Date.now()
    const results: {
      processed: number
      synced: number
      classified: number
      filtered: number
      errors: string[]
      accounts: Array<{
        email: string
        synced: number
        classified: number
        errors: string[]
      }>
    } = {
      processed: 0,
      synced: 0,
      classified: 0,
      filtered: 0,
      errors: [],
      accounts: []
    }

    // Get all active source accounts
    const { data: accounts, error: accountsError } = await supabase
      .from('source_accounts')
      .select('*')
      .eq('is_active', true)
      .order('last_sync_at', { ascending: true, nullsFirst: true })
      .limit(10) // Process max 10 accounts per run

    if (accountsError) {
      console.error('[CRON] Error fetching accounts:', accountsError)
      return NextResponse.json({
        error: 'Failed to fetch accounts',
        details: accountsError.message
      }, { status: 500 })
    }

    if (!accounts || accounts.length === 0) {
      return NextResponse.json({
        message: 'No active accounts to sync',
        duration: Date.now() - startTime
      })
    }

    console.log(`[CRON] Syncing ${accounts.length} accounts`)

    const unsubscribeService = getUnsubscribeService(supabase)

    // Process each account
    for (const account of accounts) {
      results.processed++
      const accountResult = {
        email: account.email_address,
        synced: 0,
        classified: 0,
        errors: [] as string[]
      }

      try {
        // Check if account was synced recently (within 1 minute)
        if (account.last_sync_at) {
          const lastSync = new Date(account.last_sync_at)
          const oneMinuteAgo = new Date(Date.now() - 60 * 1000)
          if (lastSync > oneMinuteAgo) {
            console.log(`[CRON] Skipping ${account.email_address} - synced recently`)
            continue
          }
        }

        console.log(`[CRON] Syncing: ${account.email_address}`)

        // Perform OPTIMIZED IMAP sync
        const syncResult = await syncEmails(account, {
          limit: CRON_EMAILS_PER_ACCOUNT,
          fullSync: false
        })

        if (syncResult.success) {
          accountResult.synced = syncResult.synced
          results.synced += syncResult.synced
          console.log(`[CRON] Synced ${syncResult.synced} emails for ${account.email_address}`)

          // Classify newly synced emails for this user
          if (syncResult.synced > 0) {
            const classified = await classifyUserEmails(
              account.user_id,
              Math.min(syncResult.synced, CLASSIFY_BATCH_SIZE)
            )
            accountResult.classified = classified
            results.classified += classified
            console.log(`[CRON] Classified ${classified} emails for ${account.email_address}`)

            // Send notifications
            if (syncResult.synced > 0) {
              notifySyncComplete(account.user_id, syncResult.synced).catch(() => {})
            }
            if (classified > 0) {
              notifyAiClassified(account.user_id, classified).catch(() => {})
            }
          }
        } else {
          accountResult.errors = syncResult.errors
          results.errors.push(`${account.email_address}: ${syncResult.errors.join(', ')}`)
        }

      } catch (error) {
        const errorMsg = error instanceof Error ? error.message : 'Unknown error'
        accountResult.errors.push(errorMsg)
        results.errors.push(`${account.email_address}: ${errorMsg}`)

        // Update sync error
        await supabase
          .from('source_accounts')
          .update({
            sync_error: errorMsg
          })
          .eq('id', account.id)
      }

      results.accounts.push(accountResult)

      // Check timeout
      if (Date.now() - startTime > 280000) { // 280 seconds
        console.log('[CRON] Approaching timeout, stopping')
        break
      }
    }

    const duration = Date.now() - startTime

    return NextResponse.json({
      success: true,
      message: `Cron sync completed`,
      results: {
        processed: results.processed,
        synced: results.synced,
        classified: results.classified,
        errors: results.errors.length
      },
      accounts: results.accounts,
      duration: `${duration}ms`,
      timestamp: new Date().toISOString()
    })
  } catch (error) {
    console.error('[CRON] Sync error:', error)
    const errorMessage = error instanceof Error ? error.message : 'Unknown error'
    return NextResponse.json({
      error: 'Sync failed',
      details: errorMessage
    }, { status: 500 })
  }
}

// Also allow POST for manual triggers
export async function POST(request: NextRequest) {
  return GET(request)
}

/**
 * GET /api/dashboard/stats
 * Consolidated dashboard statistics
 * Replaces multiple API calls with single request
 */

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';

export async function GET(request: NextRequest) {
  const startTime = Date.now();

  try {
    const supabase = await createClient();

    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Execute all queries in parallel for maximum performance
    const [
      emailCountsResult,
      categoryCounts,
      recentActivity,
      aiUsageResult,
      unreadByPriority,
      sourceAccountsResult,
      followUpsResult,
    ] = await Promise.all([
      // Total email counts
      supabase
        .from('emails')
        .select('id, is_read, is_starred, is_archived, is_deleted')
        .eq('user_id', user.id),

      // Emails by category (active only)
      supabase
        .from('emails')
        .select('category')
        .eq('user_id', user.id)
        .eq('is_deleted', false)
        .eq('is_archived', false),

      // Recent activity (last 7 days)
      supabase
        .from('emails')
        .select('id, received_at')
        .eq('user_id', user.id)
        .eq('is_deleted', false)
        .gte('received_at', new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString())
        .order('received_at', { ascending: false }),

      // AI usage this month
      supabase
        .from('ai_feature_usage')
        .select('feature_key, cost_usd')
        .eq('user_id', user.id)
        .gte('created_at', new Date(new Date().setDate(1)).toISOString()),

      // Unread by priority
      supabase
        .from('emails')
        .select('priority')
        .eq('user_id', user.id)
        .eq('is_read', false)
        .eq('is_deleted', false)
        .eq('is_archived', false),

      // Source accounts summary
      supabase
        .from('source_accounts')
        .select('id, email_address, provider, is_active, last_sync_at, total_emails_synced')
        .eq('user_id', user.id),

      // Pending follow-ups
      supabase
        .from('follow_ups')
        .select('id, status')
        .eq('user_id', user.id)
        .eq('status', 'pending'),
    ]);

    // Process email counts
    const emails = emailCountsResult.data || [];
    const emailStats = {
      total: emails.filter(e => !e.is_deleted).length,
      unread: emails.filter(e => !e.is_read && !e.is_deleted && !e.is_archived).length,
      starred: emails.filter(e => e.is_starred && !e.is_deleted).length,
      archived: emails.filter(e => e.is_archived && !e.is_deleted).length,
      trash: emails.filter(e => e.is_deleted).length,
    };

    // Process category counts
    const categoryData = categoryCounts.data || [];
    const categoryStats: Record<string, number> = {};
    categoryData.forEach(e => {
      const cat = e.category || 'uncategorized';
      categoryStats[cat] = (categoryStats[cat] || 0) + 1;
    });

    // Process recent activity (group by day)
    const activityData = recentActivity.data || [];
    const dailyActivity: Record<string, number> = {};
    activityData.forEach(e => {
      const day = new Date(e.received_at).toISOString().split('T')[0];
      dailyActivity[day] = (dailyActivity[day] || 0) + 1;
    });

    // Process AI usage
    const aiData = aiUsageResult.data || [];
    const aiStats = {
      totalRequests: aiData.length,
      totalCost: Math.round(aiData.reduce((sum, u) => sum + (u.cost_usd || 0), 0) * 100) / 100,
      byFeature: aiData.reduce((acc, u) => {
        acc[u.feature_key] = (acc[u.feature_key] || 0) + 1;
        return acc;
      }, {} as Record<string, number>),
    };

    // Process priority stats
    const priorityData = unreadByPriority.data || [];
    const priorityStats = {
      urgent: priorityData.filter(e => (e.priority || 0) >= 4).length,
      high: priorityData.filter(e => (e.priority || 0) === 3).length,
      normal: priorityData.filter(e => (e.priority || 0) === 2).length,
      low: priorityData.filter(e => (e.priority || 0) <= 1).length,
    };

    // Process source accounts
    const accountsData = sourceAccountsResult.data || [];
    const accountStats = {
      total: accountsData.length,
      active: accountsData.filter(a => a.is_active).length,
      totalSynced: accountsData.reduce((sum, a) => sum + (a.total_emails_synced || 0), 0),
      accounts: accountsData.map(a => ({
        email: a.email_address,
        provider: a.provider,
        isActive: a.is_active,
        lastSync: a.last_sync_at,
        emailsSynced: a.total_emails_synced || 0,
      })),
    };

    // Process follow-ups
    const followUpsData = followUpsResult.data || [];
    const followUpStats = {
      pending: followUpsData.length,
    };

    const duration = Date.now() - startTime;

    // Set cache headers - short cache for real-time feel
    const response = NextResponse.json({
      emails: emailStats,
      categories: categoryStats,
      activity: dailyActivity,
      ai: aiStats,
      priority: priorityStats,
      accounts: accountStats,
      followUps: followUpStats,
      meta: {
        generatedAt: new Date().toISOString(),
        duration: `${duration}ms`,
      },
    });

    response.headers.set(
      'Cache-Control',
      'private, s-maxage=30, stale-while-revalidate=60'
    );

    return response;

  } catch (error) {
    console.error('Dashboard stats error:', error);
    return NextResponse.json(
      { error: 'Failed to fetch stats', details: error instanceof Error ? error.message : 'Unknown' },
      { status: 500 }
    );
  }
}

/**
 * DEBUG API: Gmail Sync Diagnostics
 * Deep dive into Gmail sync issues
 */

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';
import { createClient as createSupabaseAdmin } from '@supabase/supabase-js';
import { isTokenExpired, refreshAccessToken } from '@/lib/oauth/google';

// Lazy admin client
function getSupabaseAdmin() {
  return createSupabaseAdmin(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  );
}

interface DiagnosticStep {
  step: string;
  status: 'ok' | 'warning' | 'error';
  message: string;
  data?: unknown;
  duration?: number;
}

export async function GET(request: NextRequest) {
  // Diagnostics expose mailbox metadata and previously leaked token prefixes.
  if (process.env.NODE_ENV === 'production') {
    return NextResponse.json({ error: 'Not found' }, { status: 404 });
  }
  const diagnostics: DiagnosticStep[] = [];
  const startTime = Date.now();

  try {
    // Step 1: Check authentication
    const supabase = await createClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();

    if (authError || !user) {
      diagnostics.push({
        step: '1. Authentication',
        status: 'error',
        message: 'User not authenticated',
        data: { error: authError?.message }
      });
      return NextResponse.json({ diagnostics, totalTime: Date.now() - startTime });
    }

    diagnostics.push({
      step: '1. Authentication',
      status: 'ok',
      message: `User authenticated: ${user.email}`,
      data: { userId: user.id, email: user.email }
    });

    // Step 2: Get source accounts (OAuth Gmail)
    const adminClient = getSupabaseAdmin();
    const { data: accounts, error: accountsError } = await adminClient
      .from('source_accounts')
      .select('*')
      .eq('user_id', user.id)
      .eq('auth_type', 'oauth_google');

    if (accountsError) {
      diagnostics.push({
        step: '2. Source Accounts Query',
        status: 'error',
        message: 'Failed to query source_accounts',
        data: { error: accountsError.message, code: accountsError.code }
      });
      return NextResponse.json({ diagnostics, totalTime: Date.now() - startTime });
    }

    if (!accounts || accounts.length === 0) {
      diagnostics.push({
        step: '2. Source Accounts Query',
        status: 'error',
        message: 'No Gmail OAuth accounts found',
        data: { accountCount: 0 }
      });
      return NextResponse.json({ diagnostics, totalTime: Date.now() - startTime });
    }

    diagnostics.push({
      step: '2. Source Accounts Query',
      status: 'ok',
      message: `Found ${accounts.length} Gmail OAuth account(s)`,
      data: accounts.map(a => ({
        id: a.id,
        email: a.email_address,
        provider: a.provider,
        auth_type: a.auth_type,
        is_active: a.is_active,
        is_connected: a.is_connected,
        last_sync_at: a.last_sync_at,
        last_error: a.last_error,
        has_access_token: !!a.oauth_access_token,
        has_refresh_token: !!a.oauth_refresh_token,
        oauth_expires_at: a.oauth_expires_at,
        total_emails_synced: a.total_emails_synced
      }))
    });

    // Process first Gmail account
    const account = accounts[0];

    // Step 3: Check OAuth tokens
    if (!account.oauth_access_token) {
      diagnostics.push({
        step: '3. OAuth Token Check',
        status: 'error',
        message: 'No access token stored',
        data: {
          has_access_token: false,
          has_refresh_token: !!account.oauth_refresh_token
        }
      });
      return NextResponse.json({ diagnostics, totalTime: Date.now() - startTime });
    }

    const tokenExpired = account.oauth_expires_at
      ? isTokenExpired(new Date(account.oauth_expires_at))
      : false;

    diagnostics.push({
      step: '3. OAuth Token Check',
      status: tokenExpired ? 'warning' : 'ok',
      message: tokenExpired ? 'Access token expired, needs refresh' : 'Access token valid',
      data: {
        has_access_token: true,
        has_refresh_token: !!account.oauth_refresh_token,
        expires_at: account.oauth_expires_at,
        is_expired: tokenExpired,
      }
    });

    // Step 4: Refresh token if needed
    let accessToken = account.oauth_access_token;

    if (tokenExpired) {
      if (!account.oauth_refresh_token) {
        diagnostics.push({
          step: '4. Token Refresh',
          status: 'error',
          message: 'Token expired but no refresh token available',
          data: { has_refresh_token: false }
        });
        return NextResponse.json({ diagnostics, totalTime: Date.now() - startTime });
      }

      try {
        const refreshStart = Date.now();
        const newTokens = await refreshAccessToken(account.oauth_refresh_token);
        accessToken = newTokens.access_token;

        // Update database
        const expiresAt = new Date(Date.now() + newTokens.expires_in * 1000);
        await adminClient
          .from('source_accounts')
          .update({
            oauth_access_token: newTokens.access_token,
            oauth_expires_at: expiresAt.toISOString(),
            ...(newTokens.refresh_token && { oauth_refresh_token: newTokens.refresh_token }),
          })
          .eq('id', account.id);

        diagnostics.push({
          step: '4. Token Refresh',
          status: 'ok',
          message: 'Token refreshed successfully',
          duration: Date.now() - refreshStart,
          data: {
            new_expires_in: newTokens.expires_in,
            new_expires_at: expiresAt.toISOString(),
            got_new_refresh_token: !!newTokens.refresh_token
          }
        });
      } catch (refreshError) {
        diagnostics.push({
          step: '4. Token Refresh',
          status: 'error',
          message: 'Failed to refresh token',
          data: {
            error: refreshError instanceof Error ? refreshError.message : 'Unknown error',
            refresh_token_preview: account.oauth_refresh_token?.substring(0, 20) + '...'
          }
        });
        return NextResponse.json({ diagnostics, totalTime: Date.now() - startTime });
      }
    } else {
      diagnostics.push({
        step: '4. Token Refresh',
        status: 'ok',
        message: 'Token still valid, no refresh needed'
      });
    }

    // Step 5: Test Gmail API - List messages
    const gmailApiStart = Date.now();
    const GMAIL_API_BASE = 'https://gmail.googleapis.com/gmail/v1';

    try {
      // First, test basic profile access
      const profileResponse = await fetch(`${GMAIL_API_BASE}/users/me/profile`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });

      if (!profileResponse.ok) {
        const profileError = await profileResponse.text();
        diagnostics.push({
          step: '5. Gmail API - Profile',
          status: 'error',
          message: `Failed to get Gmail profile (${profileResponse.status})`,
          data: {
            status: profileResponse.status,
            error: profileError
          }
        });
        return NextResponse.json({ diagnostics, totalTime: Date.now() - startTime });
      }

      const profile = await profileResponse.json();
      diagnostics.push({
        step: '5. Gmail API - Profile',
        status: 'ok',
        message: `Gmail profile OK: ${profile.emailAddress}`,
        duration: Date.now() - gmailApiStart,
        data: {
          emailAddress: profile.emailAddress,
          messagesTotal: profile.messagesTotal,
          threadsTotal: profile.threadsTotal,
          historyId: profile.historyId
        }
      });

      // Step 6: List messages
      const listStart = Date.now();
      const params = new URLSearchParams({
        maxResults: '10',
        labelIds: 'INBOX'
      });

      const listResponse = await fetch(
        `${GMAIL_API_BASE}/users/me/messages?${params.toString()}`,
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );

      if (!listResponse.ok) {
        const listError = await listResponse.text();
        diagnostics.push({
          step: '6. Gmail API - List Messages',
          status: 'error',
          message: `Failed to list messages (${listResponse.status})`,
          data: {
            status: listResponse.status,
            error: listError,
            url: `${GMAIL_API_BASE}/users/me/messages?${params.toString()}`
          }
        });
        return NextResponse.json({ diagnostics, totalTime: Date.now() - startTime });
      }

      const messageList = await listResponse.json();
      diagnostics.push({
        step: '6. Gmail API - List Messages',
        status: messageList.messages?.length > 0 ? 'ok' : 'warning',
        message: messageList.messages?.length > 0
          ? `Found ${messageList.messages.length} messages in INBOX`
          : 'INBOX is empty or no messages returned',
        duration: Date.now() - listStart,
        data: {
          messageCount: messageList.messages?.length || 0,
          resultSizeEstimate: messageList.resultSizeEstimate,
          hasNextPage: !!messageList.nextPageToken,
          firstMessageIds: messageList.messages?.slice(0, 3).map((m: {id: string}) => m.id)
        }
      });

      // Step 7: Check if messages already exist in database
      if (messageList.messages?.length > 0) {
        const messageIds = messageList.messages.map((m: {id: string}) => m.id);
        const { data: existingEmails, error: checkError } = await adminClient
          .from('emails')
          .select('message_id')
          .eq('user_id', user.id)
          .in('message_id', messageIds);

        if (checkError) {
          diagnostics.push({
            step: '7. Database - Check Duplicates',
            status: 'error',
            message: 'Failed to check existing emails',
            data: { error: checkError.message }
          });
        } else {
          const existingCount = existingEmails?.length || 0;
          const newCount = messageIds.length - existingCount;

          diagnostics.push({
            step: '7. Database - Check Duplicates',
            status: newCount > 0 ? 'ok' : 'warning',
            message: newCount > 0
              ? `${newCount} new messages to sync (${existingCount} already exist)`
              : `All ${existingCount} messages already synced`,
            data: {
              totalFromGmail: messageIds.length,
              alreadyInDb: existingCount,
              newToSync: newCount,
              existingMessageIds: existingEmails?.map(e => e.message_id)
            }
          });
        }

        // Step 8: Fetch one message details for testing
        const testMsgId = messageList.messages[0].id;
        const msgStart = Date.now();

        const msgResponse = await fetch(
          `${GMAIL_API_BASE}/users/me/messages/${testMsgId}?format=full`,
          { headers: { Authorization: `Bearer ${accessToken}` } }
        );

        if (!msgResponse.ok) {
          const msgError = await msgResponse.text();
          diagnostics.push({
            step: '8. Gmail API - Get Message Detail',
            status: 'error',
            message: `Failed to get message detail (${msgResponse.status})`,
            data: {
              messageId: testMsgId,
              status: msgResponse.status,
              error: msgError
            }
          });
        } else {
          const message = await msgResponse.json();
          const headers: Record<string, string> = {};
          message.payload?.headers?.forEach((h: {name: string, value: string}) => {
            headers[h.name.toLowerCase()] = h.value;
          });

          diagnostics.push({
            step: '8. Gmail API - Get Message Detail',
            status: 'ok',
            message: 'Successfully fetched message details',
            duration: Date.now() - msgStart,
            data: {
              messageId: message.id,
              threadId: message.threadId,
              subject: headers['subject']?.substring(0, 50),
              from: headers['from']?.substring(0, 50),
              date: headers['date'],
              labelIds: message.labelIds,
              snippet: message.snippet?.substring(0, 100),
              hasPayload: !!message.payload,
              hasParts: !!message.payload?.parts
            }
          });
        }
      }

    } catch (apiError) {
      diagnostics.push({
        step: '5-8. Gmail API',
        status: 'error',
        message: 'Gmail API call failed',
        data: { error: apiError instanceof Error ? apiError.message : 'Unknown error' }
      });
    }

    // Step 9: Check database write permissions
    const testStart = Date.now();
    try {
      // Try to update source_accounts
      const { error: updateError } = await adminClient
        .from('source_accounts')
        .update({ last_error: null })
        .eq('id', account.id);

      if (updateError) {
        diagnostics.push({
          step: '9. Database - Write Test',
          status: 'error',
          message: 'Cannot write to source_accounts',
          data: { error: updateError.message, code: updateError.code }
        });
      } else {
        diagnostics.push({
          step: '9. Database - Write Test',
          status: 'ok',
          message: 'Database write permission OK',
          duration: Date.now() - testStart
        });
      }
    } catch (dbError) {
      diagnostics.push({
        step: '9. Database - Write Test',
        status: 'error',
        message: 'Database write failed',
        data: { error: dbError instanceof Error ? dbError.message : 'Unknown error' }
      });
    }

    // Summary
    const errors = diagnostics.filter(d => d.status === 'error');
    const warnings = diagnostics.filter(d => d.status === 'warning');

    return NextResponse.json({
      summary: {
        status: errors.length > 0 ? 'FAILED' : warnings.length > 0 ? 'WARNING' : 'OK',
        totalSteps: diagnostics.length,
        errors: errors.length,
        warnings: warnings.length,
        totalTime: Date.now() - startTime
      },
      diagnostics,
      recommendation: errors.length > 0
        ? `Fix ${errors.length} error(s): ${errors.map(e => e.step).join(', ')}`
        : warnings.length > 0
          ? `Check ${warnings.length} warning(s): ${warnings.map(w => w.step).join(', ')}`
          : 'All checks passed. Try running sync again.'
    });

  } catch (error) {
    diagnostics.push({
      step: 'Unexpected Error',
      status: 'error',
      message: error instanceof Error ? error.message : 'Unknown error',
      data: { stack: error instanceof Error ? error.stack : undefined }
    });

    return NextResponse.json({
      summary: { status: 'FAILED', totalTime: Date.now() - startTime },
      diagnostics
    });
  }
}

