import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { createClient as createSupabaseAdmin } from '@supabase/supabase-js'
import { fetchEmailBody, decryptPassword } from '@/lib/email/imap-client'

export const maxDuration = 55

const supabaseAdmin = createSupabaseAdmin(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
)

export async function POST(request: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { accountId, limit = 20 } = await request.json()

  if (!accountId) {
    return NextResponse.json({ error: 'Account ID required' }, { status: 400 })
  }

  // Get account
  const { data: account, error: accountError } = await supabaseAdmin
    .from('source_accounts')
    .select('*')
    .eq('id', accountId)
    .eq('user_id', user.id)
    .single()

  if (accountError || !account) {
    return NextResponse.json({ error: 'Account not found' }, { status: 404 })
  }

  // Get emails without body (body_text is null or empty)
  const { data: emails, error: emailsError } = await supabaseAdmin
    .from('emails')
    .select('id, original_uid')
    .eq('source_account_id', accountId)
    .eq('user_id', user.id)
    .or('body_text.is.null,body_text.eq.')
    .not('original_uid', 'is', null)
    .order('received_at', { ascending: false })
    .limit(Math.min(limit, 30))

  if (emailsError) {
    return NextResponse.json({ error: emailsError.message }, { status: 500 })
  }

  if (!emails || emails.length === 0) {
    return NextResponse.json({
      success: true,
      refetched: 0,
      message: 'Tất cả emails đã có nội dung'
    })
  }

  console.log(`[REFETCH] Found ${emails.length} emails without body for account ${accountId}`)

  let refetched = 0
  const errors: string[] = []

  for (const email of emails) {
    if (!email.original_uid) continue

    try {
      const body = await fetchEmailBody(account, email.original_uid)

      if (body) {
        const { error: updateError } = await supabaseAdmin
          .from('emails')
          .update({
            body_text: body.body_text,
            body_html: body.body_html,
            body_fetched: true
          })
          .eq('id', email.id)

        if (!updateError) {
          refetched++
          console.log(`[REFETCH] Updated email ${email.id}`)
        } else {
          errors.push(`Email ${email.id}: ${updateError.message}`)
        }
      }
    } catch (err) {
      const errMsg = err instanceof Error ? err.message : 'Unknown error'
      console.error(`[REFETCH] Error for email ${email.id}:`, errMsg)
      errors.push(`Email ${email.id}: ${errMsg}`)
    }
  }

  return NextResponse.json({
    success: true,
    refetched,
    total: emails.length,
    errors: errors.slice(0, 5),
    message: refetched > 0
      ? `Đã cập nhật nội dung cho ${refetched}/${emails.length} emails`
      : 'Không thể cập nhật nội dung. Vui lòng thử sync lại.'
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'

export async function GET(request: NextRequest) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Fetch all emails
  const { data: emails, error } = await supabase
    .from('emails')
    .select('*')
    .eq('user_id', user.id)
    .eq('is_deleted', false)
    .eq('is_archived', false)
    .order('received_at', { ascending: false })

  if (error) {
    return NextResponse.json({ error: 'Failed to fetch' }, { status: 500 })
  }

  const allEmails = emails || []

  // === SMART GROUPINGS ===

  // 1. Nhóm theo độ ưu tiên
  const byPriority = {
    urgent: allEmails.filter(e => e.priority === 5),
    high: allEmails.filter(e => e.priority === 4),
    normal: allEmails.filter(e => e.priority === 3),
    low: allEmails.filter(e => (e.priority || 3) <= 2),
  }

  // 2. Nhóm theo người gửi (top senders)
  const senderCounts: Record<string, { count: number; emails: typeof allEmails; name: string }> = {}
  allEmails.forEach(e => {
    const key = e.from_address
    if (!senderCounts[key]) {
      senderCounts[key] = { count: 0, emails: [], name: e.from_name || e.from_address }
    }
    senderCounts[key].count++
    senderCounts[key].emails.push(e)
  })
  const bySender = Object.entries(senderCounts)
    .sort((a, b) => b[1].count - a[1].count)
    .slice(0, 10)
    .map(([email, data]) => ({
      email,
      name: data.name,
      count: data.count,
      emails: data.emails
    }))

  // 3. Nhóm theo category
  const byCategory = {
    work: allEmails.filter(e => e.category === 'work'),
    personal: allEmails.filter(e => e.category === 'personal'),
    transaction: allEmails.filter(e => e.category === 'transaction'),
    newsletter: allEmails.filter(e => e.category === 'newsletter'),
    promotion: allEmails.filter(e => e.category === 'promotion'),
    social: allEmails.filter(e => e.category === 'social'),
    uncategorized: allEmails.filter(e => !e.category || e.category === 'uncategorized'),
  }

  // 4. Nhóm theo thời gian
  const now = new Date()
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000)
  const monthAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000)

  const byTime = {
    today: allEmails.filter(e => new Date(e.received_at) >= today),
    thisWeek: allEmails.filter(e => {
      const d = new Date(e.received_at)
      return d >= weekAgo && d < today
    }),
    thisMonth: allEmails.filter(e => {
      const d = new Date(e.received_at)
      return d >= monthAgo && d < weekAgo
    }),
    older: allEmails.filter(e => new Date(e.received_at) < monthAgo),
  }

  // 5. Action items (cần hành động)
  const actionItems = {
    needsReply: allEmails.filter(e => e.needs_reply && !e.is_read),
    hasDeadline: allEmails.filter(e => e.detected_deadline),
    unreadImportant: allEmails.filter(e => !e.is_read && (e.priority || 3) >= 4),
    unreadLongTime: allEmails.filter(e => {
      if (e.is_read) return false
      const daysSinceReceived = (now.getTime() - new Date(e.received_at).getTime()) / (1000 * 60 * 60 * 24)
      return daysSinceReceived > 3
    }),
  }

  // 6. Cleanup suggestions
  const cleanupSuggestions = {
    oldUnreadPromo: allEmails.filter(e => {
      if (e.is_read || e.category !== 'promotion') return false
      const days = (now.getTime() - new Date(e.received_at).getTime()) / (1000 * 60 * 60 * 24)
      return days > 7
    }),
    oldUnreadNewsletter: allEmails.filter(e => {
      if (e.is_read || e.category !== 'newsletter') return false
      const days = (now.getTime() - new Date(e.received_at).getTime()) / (1000 * 60 * 60 * 24)
      return days > 14
    }),
  }

  return NextResponse.json({
    total: allEmails.length,
    byPriority,
    bySender,
    byCategory,
    byTime,
    actionItems,
    cleanupSuggestions,
    stats: {
      unread: allEmails.filter(e => !e.is_read).length,
      needsReply: actionItems.needsReply.length,
      hasDeadline: actionItems.hasDeadline.length,
    }
  })
}

'use client';

/**
 * AI Feature Button
 * Button to manually trigger an AI feature
 */

import { useState } from 'react';
import { Loader2, Sparkles } from 'lucide-react';
import { cn } from '@/lib/utils';
import { AIFeatureKey, AI_FEATURES_INFO } from '@/types/ai-features';

interface AIFeatureButtonProps {
  featureKey: AIFeatureKey;
  emailId: string;
  onTrigger: (featureKey: AIFeatureKey) => Promise<void>;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  variant?: 'default' | 'outline' | 'ghost';
  showIcon?: boolean;
  className?: string;
}

export function AIFeatureButton({
  featureKey,
  emailId,
  onTrigger,
  disabled = false,
  size = 'sm',
  variant = 'outline',
  showIcon = true,
  className,
}: AIFeatureButtonProps) {
  const [isLoading, setIsLoading] = useState(false);

  const featureInfo = AI_FEATURES_INFO.find(f => f.key === featureKey);
  if (!featureInfo) return null;

  const handleClick = async () => {
    if (isLoading || disabled) return;

    setIsLoading(true);
    try {
      // Let the parent handle the API call (useAIFeatures hook)
      await onTrigger(featureKey);
    } catch (error) {
      console.error('Error triggering AI feature:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const sizeClasses = {
    sm: 'px-2.5 py-1.5 text-xs',
    md: 'px-3 py-2 text-sm',
    lg: 'px-4 py-2.5 text-base',
  };

  const variantClasses = {
    default: 'bg-primary text-primary-foreground hover:bg-primary/90',
    outline: cn(
      'border bg-transparent hover:bg-gray-100 dark:hover:bg-gray-800',
      'border-gray-300 dark:border-gray-600',
      'text-gray-700 dark:text-gray-300'
    ),
    ghost: 'hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-700 dark:text-gray-300',
  };

  return (
    <button
      onClick={handleClick}
      disabled={isLoading || disabled}
      className={cn(
        'inline-flex items-center gap-1.5 rounded-md font-medium transition-colors',
        'disabled:opacity-50 disabled:cursor-not-allowed',
        sizeClasses[size],
        variantClasses[variant],
        className
      )}
    >
      {isLoading ? (
        <Loader2 className="w-3.5 h-3.5 animate-spin" />
      ) : showIcon ? (
        <Sparkles className="w-3.5 h-3.5" />
      ) : null}
      <span>{featureInfo.nameVi}</span>
    </button>
  );
}

