                    <Archive className="w-5 h-5 text-gray-500 dark:text-gray-400" strokeWidth={1.5} />
                  ) : (
                    <Trash2 className="w-5 h-5 text-gray-500 dark:text-gray-400" strokeWidth={1.5} />
                  )}
                  <div>
                    <p className="text-[14px] font-medium text-[var(--foreground)]">
                      {item.title}
                    </p>
                    <p className="text-[13px] text-[var(--muted-foreground)]">
                      {item.description}
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => handleCleanupAction(item.action, item.emailIds)}
                  disabled={processingAction === item.action}
                  className={cn(
                    'px-3 py-1.5 rounded-lg text-[13px] font-medium transition-colors',
                    item.action === 'archive'
                      ? 'bg-[var(--secondary)] text-[var(--foreground)] hover:bg-[var(--border)]'
                      : 'bg-red-50 dark:bg-red-500/10 text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-500/20',
                    processingAction === item.action && 'opacity-50 cursor-not-allowed'
                  )}
                >
                  {processingAction === item.action ? (
                    <Loader2 className="w-3.5 h-3.5 animate-spin" strokeWidth={1.5} />
                  ) : (
                    item.action === 'archive' ? 'Archive' : 'Xóa'
                  )}
                </button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import {
  Sparkles,
  Zap,
  FileText,
  Search,
  ChevronDown,
  Copy,
  Check,
  RefreshCw,
  Send,
  Loader2,
  MessageSquare,
  Clock,
  AlertCircle,
  X
} from 'lucide-react'
import type { Email } from '@/types'
import type { EmailAnalysis } from '@/lib/ai/email-analyzer'
import type { GeneratedDraft } from '@/lib/ai/draft-generator'
import type { ResearchResult } from '@/lib/ai/research-service'

interface ReplyAssistantProps {
  email: Email
  onUseDraft: (subject: string, body: string) => void
  onClose?: () => void
}

type TabType = 'quick' | 'draft' | 'research'

export function ReplyAssistant({ email, onUseDraft, onClose }: ReplyAssistantProps) {
  const [activeTab, setActiveTab] = useState<TabType>('quick')
  const [analysis, setAnalysis] = useState<EmailAnalysis | null>(null)
  const [draft, setDraft] = useState<GeneratedDraft | null>(null)
  const [research, setResearch] = useState<ResearchResult | null>(null)
  const [loading, setLoading] = useState<Record<string, boolean>>({})
  const [error, setError] = useState<string | null>(null)
  const [copied, setCopied] = useState(false)

  // Draft options
  const [draftOptions, setDraftOptions] = useState({
    tone: 'neutral' as 'formal' | 'friendly' | 'neutral',
    length: 'medium' as 'short' | 'medium' | 'long',
    includeGreeting: true,
    includeSignature: true,
    customInstructions: ''
  })

  useEffect(() => {
    analyzeEmail()
  }, [email.id])

  const analyzeEmail = async () => {
    setLoading(prev => ({ ...prev, analyze: true }))
    setError(null)

    try {
      const res = await fetch('/api/ai/analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ emailId: email.id })
      })

      if (!res.ok) throw new Error('Failed to analyze')

      const data = await res.json()
      setAnalysis(data)
    } catch (err) {
      setError('Không thể phân tích email')
    } finally {
      setLoading(prev => ({ ...prev, analyze: false }))
    }
  }

  const generateDraft = async () => {
    if (!analysis) return

    setLoading(prev => ({ ...prev, draft: true }))
    setError(null)

    try {
      const res = await fetch('/api/ai/draft', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          emailId: email.id,
          analysis,
          options: draftOptions,
          relatedEmails: research?.relatedEmails
        })
      })

      if (!res.ok) throw new Error('Failed to generate draft')

      const data = await res.json()
      setDraft(data)
    } catch (err) {
      setError('Không thể tạo bản nháp')
    } finally {
      setLoading(prev => ({ ...prev, draft: false }))
    }
  }

  const fetchResearch = async () => {
    setLoading(prev => ({ ...prev, research: true }))
    setError(null)

    try {
      const res = await fetch('/api/ai/research', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ emailId: email.id })
      })

      if (!res.ok) throw new Error('Failed to research')

      const data = await res.json()
      setResearch(data)
    } catch (err) {
      setError('Không thể tìm thông tin liên quan')
    } finally {
      setLoading(prev => ({ ...prev, research: false }))
    }
  }

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const handleQuickReply = (content: string) => {
    onUseDraft(`Re: ${email.subject}`, content)
  }

  const intentLabels: Record<string, string> = {
    question: 'Câu hỏi',
    request: 'Yêu cầu',
    information: 'Thông tin',
    complaint: 'Khiếu nại',
    followup: 'Theo dõi',
    introduction: 'Giới thiệu',
    other: 'Khác'
  }

  const urgencyLabels: Record<string, { label: string; color: string }> = {
    high: { label: 'Khẩn cấp', color: 'bg-red-50 dark:bg-red-500/10 text-red-600 dark:text-red-400' },
    medium: { label: 'Trung bình', color: 'bg-amber-50 dark:bg-amber-500/10 text-amber-600 dark:text-amber-400' },
    low: { label: 'Thấp', color: 'bg-[var(--secondary)] text-[var(--muted-foreground)]' }
  }

  return (
    <div className="bg-[var(--card)] border border-[var(--border)] rounded-xl shadow-sm overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[var(--border)] bg-[var(--secondary)]">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-[var(--foreground)] rounded-lg flex items-center justify-center">
            <Sparkles className="w-4 h-4 text-[var(--background)]" strokeWidth={1.5} />
          </div>
          <div>
            <h3 className="font-semibold text-[var(--foreground)]">Trợ lý phản hồi AI</h3>
            <p className="text-[12px] text-[var(--muted-foreground)]">Phân tích và gợi ý phản hồi thông minh</p>
          </div>
        </div>
        {onClose && (
          <button
            onClick={onClose}
            className="p-2 hover:bg-[var(--hover)] rounded-lg transition-colors"
          >
            <X className="w-4 h-4 text-[var(--muted-foreground)]" strokeWidth={1.5} />
          </button>
        )}
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[var(--border)]">
        {[
          { id: 'quick' as const, label: 'Trả lời nhanh', icon: Zap },
          { id: 'draft' as const, label: 'Soạn thảo', icon: FileText },
          { id: 'research' as const, label: 'Nghiên cứu', icon: Search }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => {
              setActiveTab(tab.id)
              if (tab.id === 'research' && !research) {
                fetchResearch()
              }
            }}
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-[14px] font-medium transition-colors ${
              activeTab === tab.id
                ? 'text-[var(--foreground)] border-b-2 border-[var(--foreground)]'
                : 'text-[var(--muted-foreground)] hover:text-[var(--foreground)]'
            }`}
          >
            <tab.icon className="w-4 h-4" strokeWidth={1.5} />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Content */}
      <div className="p-4">
        {error && (
          <div className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/30 rounded-lg text-red-600 dark:text-red-400 text-[14px] mb-4">
            <AlertCircle className="w-4 h-4" strokeWidth={1.5} />
            {error}
          </div>
        )}

        {/* Analysis Summary (shown in all tabs) */}
        {loading.analyze ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 animate-spin text-[var(--muted-foreground)]" strokeWidth={1.5} />
          </div>
        ) : analysis && (
          <div className="mb-4 p-3 bg-[var(--secondary)] rounded-lg border border-[var(--border)]">
            <div className="flex flex-wrap gap-2 mb-2">
              <span className="px-2 py-1 bg-[var(--background)] rounded text-[12px] text-[var(--foreground)]">
                {intentLabels[analysis.intent] || analysis.intent}
              </span>
              <span className={`px-2 py-1 rounded text-[12px] ${urgencyLabels[analysis.urgency]?.color || 'bg-[var(--secondary)] text-[var(--muted-foreground)]'}`}>
                {urgencyLabels[analysis.urgency]?.label || analysis.urgency}
              </span>
            </div>
            <p className="text-[13px] text-[var(--muted-foreground)]">
              <strong>Điểm chính:</strong> {analysis.keyPoints.join(', ')}
            </p>
          </div>
        )}

        {/* Quick Reply Tab */}
        {activeTab === 'quick' && analysis && (
          <div className="space-y-3">
            <h4 className="text-[14px] font-medium text-[var(--foreground)]">Phản hồi gợi ý</h4>
            {analysis.quickReplies.map((reply, index) => (
              <button
                key={index}
                onClick={() => handleQuickReply(reply.content)}
                className="w-full p-3 text-left bg-[var(--card)] border border-[var(--border)] rounded-lg hover:border-[var(--foreground)] hover:shadow-sm transition-all group"
              >
                <div className="flex items-center justify-between mb-1">
                  <span className="text-[14px] font-medium text-[var(--foreground)]">{reply.label}</span>
                  <span className="text-[12px] text-[var(--muted)] capitalize">{reply.tone}</span>
                </div>
                <p className="text-[13px] text-[var(--muted-foreground)] line-clamp-2">{reply.content}</p>
                <div className="flex items-center gap-1 mt-2 text-[12px] text-[var(--foreground)] opacity-0 group-hover:opacity-100 transition-opacity">
                  <Send className="w-3 h-3" strokeWidth={1.5} />
                  Sử dụng
                </div>
              </button>
            ))}

            {analysis.suggestedActions.length > 0 && (
              <div className="mt-4 pt-4 border-t border-[var(--border)]">
                <h4 className="text-[14px] font-medium text-[var(--foreground)] mb-2">Hành động gợi ý</h4>
                <ul className="space-y-1">
                  {analysis.suggestedActions.map((action, index) => (
                    <li key={index} className="flex items-center gap-2 text-[13px] text-[var(--muted-foreground)]">
                      <Check className="w-3 h-3 text-green-600 dark:text-green-400" strokeWidth={2} />
                      {action}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}

        {/* Draft Tab */}
        {activeTab === 'draft' && (
          <div className="space-y-4">
            {/* Options */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[12px] font-medium text-[var(--muted-foreground)] mb-1">
                  Giọng điệu
                </label>
                <select
                  value={draftOptions.tone}
                  onChange={(e) => setDraftOptions(prev => ({ ...prev, tone: e.target.value as 'formal' | 'friendly' | 'neutral' }))}
                  className="w-full px-3 py-2 border border-[var(--border)] rounded-lg text-[14px] bg-[var(--background)] text-[var(--foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                >
                  <option value="formal">Trang trọng</option>
                  <option value="friendly">Thân thiện</option>
                  <option value="neutral">Trung tính</option>
                </select>
              </div>
              <div>
                <label className="block text-[12px] font-medium text-[var(--muted-foreground)] mb-1">
                  Độ dài
                </label>
                <select
                  value={draftOptions.length}
                  onChange={(e) => setDraftOptions(prev => ({ ...prev, length: e.target.value as 'short' | 'medium' | 'long' }))}
                  className="w-full px-3 py-2 border border-[var(--border)] rounded-lg text-[14px] bg-[var(--background)] text-[var(--foreground)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                >
                  <option value="short">Ngắn</option>
                  <option value="medium">Trung bình</option>
                  <option value="long">Dài</option>
                </select>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <label className="flex items-center gap-2 text-[13px] text-[var(--muted-foreground)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={draftOptions.includeGreeting}
                  onChange={(e) => setDraftOptions(prev => ({ ...prev, includeGreeting: e.target.checked }))}
                  className="w-4 h-4 rounded border-[var(--border)] text-[var(--primary)] focus:ring-[var(--primary)]"
                />
                Lời chào
              </label>
              <label className="flex items-center gap-2 text-[13px] text-[var(--muted-foreground)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={draftOptions.includeSignature}
                  onChange={(e) => setDraftOptions(prev => ({ ...prev, includeSignature: e.target.checked }))}
                  className="w-4 h-4 rounded border-[var(--border)] text-[var(--primary)] focus:ring-[var(--primary)]"
                />
                Chữ ký
              </label>
            </div>

            <div>
              <label className="block text-[12px] font-medium text-[var(--muted-foreground)] mb-1">
                Yêu cầu thêm (tùy chọn)
              </label>
              <input
                type="text"
                value={draftOptions.customInstructions}
                onChange={(e) => setDraftOptions(prev => ({ ...prev, customInstructions: e.target.value }))}
                placeholder="VD: Nhấn mạnh deadline, đề cập đến cuộc họp..."
                className="w-full px-3 py-2 border border-[var(--border)] rounded-lg text-[14px] bg-[var(--background)] text-[var(--foreground)] placeholder-[var(--muted)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
              />
            </div>

            <button
              onClick={generateDraft}
              disabled={loading.draft || !analysis}
              className="w-full flex items-center justify-center gap-2 py-2.5 bg-[var(--primary)] text-[var(--primary-foreground)] rounded-lg font-medium hover:opacity-90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading.draft ? (
                <Loader2 className="w-4 h-4 animate-spin" strokeWidth={1.5} />
              ) : (
                <>
                  <Sparkles className="w-4 h-4" strokeWidth={1.5} />
                  Tạo bản nháp
                </>
              )}
            </button>

            {/* Generated Draft */}
            {draft && (
              <div className="mt-4 p-4 bg-[var(--secondary)] rounded-lg border border-[var(--border)]">
                <div className="flex items-center justify-between mb-3">
                  <h4 className="text-[14px] font-medium text-[var(--foreground)]">{draft.subject}</h4>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => handleCopy(draft.body)}
                      className="p-1.5 hover:bg-[var(--hover)] rounded transition-colors"
                      title="Sao chép"
                    >
                      {copied ? (
                        <Check className="w-4 h-4 text-green-600 dark:text-green-400" strokeWidth={1.5} />
                      ) : (
                        <Copy className="w-4 h-4 text-[var(--muted-foreground)]" strokeWidth={1.5} />
                      )}
                    </button>
                    <button
                      onClick={generateDraft}
                      className="p-1.5 hover:bg-[var(--hover)] rounded transition-colors"
                      title="Tạo lại"
                    >
                      <RefreshCw className="w-4 h-4 text-[var(--muted-foreground)]" strokeWidth={1.5} />
                    </button>
                  </div>
                </div>
                <pre className="text-[13px] text-[var(--foreground)] whitespace-pre-wrap font-sans mb-3">
                  {draft.body}
                </pre>
                <button
                  onClick={() => onUseDraft(draft.subject, draft.body)}
                  className="w-full flex items-center justify-center gap-2 py-2 bg-[var(--primary)] text-[var(--primary-foreground)] rounded-lg text-[14px] font-medium hover:opacity-90 transition-colors"
                >
                  <Send className="w-4 h-4" strokeWidth={1.5} />
                  Sử dụng bản nháp này
                </button>

                {/* Alternative versions */}
                {draft.alternativeVersions && draft.alternativeVersions.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-[var(--border)]">
                    <h5 className="text-[13px] font-medium text-[var(--muted-foreground)] mb-2">Phiên bản khác</h5>
                    {draft.alternativeVersions.map((alt, index) => (
                      <div key={index} className="p-3 bg-[var(--card)] rounded-lg border border-[var(--border)] mb-2">
                        <div className="flex items-center justify-between mb-2">
                          <span className="text-[12px] text-[var(--muted)] capitalize">{alt.tone}</span>
                          <button
                            onClick={() => onUseDraft(draft.subject, alt.body)}
                            className="text-[12px] text-[var(--foreground)] font-medium hover:underline"
                          >
                            Sử dụng
                          </button>
                        </div>
                        <p className="text-[13px] text-[var(--muted-foreground)] line-clamp-3">{alt.body}</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* Research Tab */}
        {activeTab === 'research' && (
          <div className="space-y-4">
            {loading.research ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-[var(--muted-foreground)]" strokeWidth={1.5} />
              </div>
            ) : research ? (
              <>
                {/* Sender History */}
                <div className="p-4 bg-[var(--secondary)] rounded-lg border border-[var(--border)]">
                  <h4 className="text-[14px] font-medium text-[var(--foreground)] mb-3">Lịch sử với người gửi</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-[12px] text-[var(--muted)]">Tổng email</p>
                      <p className="text-[16px] font-semibold text-[var(--foreground)]">{research.senderHistory.totalEmails}</p>
                    </div>
                    <div>
                      <p className="text-[12px] text-[var(--muted)]">Liên hệ gần nhất</p>
                      <p className="text-[14px] text-[var(--foreground)]">
                        {research.senderHistory.lastContact
                          ? new Date(research.senderHistory.lastContact).toLocaleDateString('vi-VN')
                          : 'N/A'}
                      </p>
                    </div>
                  </div>
                  {research.senderHistory.commonTopics.length > 0 && (
                    <div className="mt-3">
                      <p className="text-[12px] text-[var(--muted)] mb-1">Chủ đề thường gặp</p>
                      <div className="flex flex-wrap gap-1">
                        {research.senderHistory.commonTopics.map((topic, index) => (
                          <span key={index} className="px-2 py-0.5 bg-[var(--background)] rounded text-[12px] text-[var(--muted-foreground)]">
                            {topic}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                {/* Thread Context */}
                {research.threadContext.length > 0 && (
                  <div>
                    <h4 className="text-[14px] font-medium text-[var(--foreground)] mb-2 flex items-center gap-2">
                      <MessageSquare className="w-4 h-4" strokeWidth={1.5} />
                      Chuỗi email ({research.threadContext.length})
                    </h4>
                    <div className="space-y-2">
                      {research.threadContext.map(threadEmail => (
                        <div key={threadEmail.id} className="p-3 bg-[var(--secondary)] rounded-lg border border-[var(--border)]">
                          <div className="flex items-center justify-between mb-1">
                            <span className="text-[13px] font-medium text-[var(--foreground)] truncate">
                              {threadEmail.from_name || threadEmail.from_address}
                            </span>
                            <span className="text-[12px] text-[var(--muted)]">
                              {threadEmail.received_at ? new Date(threadEmail.received_at).toLocaleDateString('vi-VN') : ''}
                            </span>
                          </div>
                          <p className="text-[12px] text-[var(--muted-foreground)] line-clamp-2">{threadEmail.snippet}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Related Emails */}
                {research.relatedEmails.length > 0 && (
                  <div>
                    <h4 className="text-[14px] font-medium text-[var(--foreground)] mb-2 flex items-center gap-2">
                      <Clock className="w-4 h-4" strokeWidth={1.5} />
                      Email liên quan ({research.relatedEmails.length})
                    </h4>
                    <div className="space-y-2 max-h-60 overflow-auto">
                      {research.relatedEmails.map(relatedEmail => (
                        <div key={relatedEmail.id} className="p-3 bg-[var(--secondary)] rounded-lg border border-[var(--border)]">
                          <p className="text-[13px] font-medium text-[var(--foreground)] truncate mb-1">
                            {relatedEmail.subject || '(Không có tiêu đề)'}
                          </p>
                          <p className="text-[12px] text-[var(--muted)]">
                            {relatedEmail.from_name || relatedEmail.from_address} • {relatedEmail.received_at ? new Date(relatedEmail.received_at).toLocaleDateString('vi-VN') : ''}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {research.relatedEmails.length === 0 && research.threadContext.length === 0 && (
                  <div className="text-center py-8 text-[var(--muted-foreground)]">
                    <Search className="w-8 h-8 mx-auto mb-2 opacity-50" strokeWidth={1.5} />
                    <p className="text-[14px]">Không tìm thấy email liên quan</p>
                  </div>
                )}
              </>
            ) : (
              <div className="text-center py-8">
                <button
                  onClick={fetchResearch}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--secondary)] rounded-lg text-[14px] text-[var(--foreground)] font-medium hover:bg-[var(--border)] transition-colors"
                >
                  <Search className="w-4 h-4" strokeWidth={1.5} />
                  Tìm kiếm thông tin
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { AlertCircle, X, ArrowRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import { IconBox } from '@/components/ui/icon-box'
import { Button } from '@/components/ui/button'

interface UrgentEmail {
  id: string
  from_name: string | null
  from_address: string
  subject: string
  priority: number
}

interface Props {
  onSelectEmail: (id: string) => void
}

export function UrgentAlert({ onSelectEmail }: Props) {
  const [alerts, setAlerts] = useState<UrgentEmail[]>([])
  const [dismissed, setDismissed] = useState<Set<string>>(new Set())

  useEffect(() => {
    const checkUrgentEmails = async () => {
      try {
        const res = await fetch('/api/ai/urgent-check')
        if (res.ok) {
          const data = await res.json()
          setAlerts(data.urgentEmails || [])
        }
      } catch (error) {
        console.error('Failed to check urgent emails:', error)
      }
    }

    checkUrgentEmails()
    // Refresh every 10 minutes (was 5 minutes - performance optimization)
    const interval = setInterval(checkUrgentEmails, 10 * 60 * 1000)
    return () => clearInterval(interval)
  }, [])

  const handleDismiss = (id: string) => {
    setDismissed(prev => new Set(prev).add(id))
  }

  const handleSelect = (id: string) => {
    onSelectEmail(id)
    handleDismiss(id)
  }

  const visibleAlerts = alerts.filter(a => !dismissed.has(a.id))

  if (visibleAlerts.length === 0) return null

  return (
    <div className="fixed bottom-6 right-6 z-50 space-y-3 max-w-sm">
      {visibleAlerts.slice(0, 3).map((email, index) => (
        <div
          key={email.id}
          className={cn(
            'bg-[var(--card)] border border-[var(--border)] rounded-xl shadow-executive-lg p-4',
            'animate-in slide-in-from-right-5 fade-in duration-300'
          )}
          style={{ animationDelay: `${index * 100}ms` }}
        >
          <div className="flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-red-500 dark:text-red-400 flex-shrink-0 mt-0.5" strokeWidth={1.5} />
            <div className="flex-1 min-w-0">
              <p className="text-[12px] text-gray-900 dark:text-white font-medium mb-1">
                Email quan trọng
              </p>
              <p className="text-[14px] font-medium text-[var(--foreground)] truncate">
                {email.from_name || email.from_address}
              </p>
              <p className="text-[13px] text-[var(--muted-foreground)] truncate">
                {email.subject || '(Không có tiêu đề)'}
              </p>
            </div>
            <button
              onClick={() => handleDismiss(email.id)}
              className="p-1 rounded-lg hover:bg-[var(--secondary)] transition-colors"
            >
              <X className="w-4 h-4 text-[var(--muted)]" strokeWidth={1.5} />
            </button>
          </div>
          <Button
            onClick={() => handleSelect(email.id)}
            size="sm"
            className="mt-3 w-full"
            icon={<ArrowRight className="w-3.5 h-3.5" strokeWidth={1.5} />}
          >
            Xem ngay
          </Button>
        </div>
      ))}
    </div>
  )
}

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { ChevronDown, Check, Mail } from 'lucide-react'
import { cn } from '@/lib/utils'

interface SourceAccount {
  id: string
  email_address: string
  display_name?: string
  provider: string
  avatar_url?: string
  is_primary: boolean
  color: string
  is_active: boolean
  email_count?: number
  unread_count?: number
}

interface AccountSwitcherProps {
  selectedAccountIds: string[]
  onAccountChange: (accountIds: string[]) => void
  className?: string
}

export function AccountSwitcher({
  selectedAccountIds,
  onAccountChange,
  className
}: AccountSwitcherProps) {
  const [accounts, setAccounts] = useState<SourceAccount[]>([])
  const [loading, setLoading] = useState(true)
  const [isOpen, setIsOpen] = useState(false)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // Fetch accounts
  const fetchAccounts = useCallback(async () => {
    try {
      const res = await fetch('/api/source-accounts')
      if (res.ok) {
        const data = await res.json()
        setAccounts(data.accounts || [])
      }
    } catch (error) {
      console.error('Failed to fetch accounts:', error)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const toggleAccount = (accountId: string) => {
    if (selectedAccountIds.includes(accountId)) {
      // Remove account
      const newIds = selectedAccountIds.filter(id => id !== accountId)
      onAccountChange(newIds)
    } else {
      // Add account
      onAccountChange([...selectedAccountIds, accountId])
    }
  }

  const selectAll = () => {
    onAccountChange([]) // Empty array means "all accounts"
  }

  const isAllSelected = selectedAccountIds.length === 0

  // Get display label
  const getDisplayLabel = () => {
    if (isAllSelected || selectedAccountIds.length === 0) {
      return 'Tất cả tài khoản'
    }
    if (selectedAccountIds.length === 1) {
      const account = accounts.find(a => a.id === selectedAccountIds[0])
      return account?.display_name || account?.email_address || 'Tài khoản'
    }
    return `${selectedAccountIds.length} tài khoản`
  }

  // Get selected accounts for avatar display
  const selectedAccounts = selectedAccountIds.length > 0
    ? accounts.filter(a => selectedAccountIds.includes(a.id))
    : []

  if (loading) {
    return (
      <div className={cn("h-9 w-40 bg-[var(--secondary)] rounded-lg animate-pulse", className)} />
    )
  }

  if (accounts.length <= 1) {
    // Don't show switcher if only one account
    return null
  }

  return (
    <div className={cn("relative", className)} ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          "flex items-center gap-2 px-3 py-2 rounded-lg border border-[var(--border)] bg-[var(--card)] hover:bg-[var(--hover)] transition-colors",
          isOpen && "bg-[var(--hover)]"
        )}
      >
        {/* Avatar stack */}
        <div className="flex -space-x-2">
          {selectedAccounts.length > 0 ? (
            selectedAccounts.slice(0, 3).map((account, index) => (
              <div
                key={account.id}
                className="w-6 h-6 rounded-full border-2 border-[var(--card)] flex items-center justify-center text-white text-[10px] font-medium"
                style={{ backgroundColor: account.color, zIndex: 3 - index }}
              >
                {account.avatar_url ? (
                  <img src={account.avatar_url} alt="" className="w-full h-full rounded-full object-cover" />
                ) : (
                  account.email_address[0].toUpperCase()
                )}
              </div>
            ))
          ) : (
            <div className="w-6 h-6 rounded-full bg-[var(--primary)] flex items-center justify-center">
              <Mail className="w-3 h-3 text-white" />
            </div>
          )}
          {selectedAccounts.length > 3 && (
            <div className="w-6 h-6 rounded-full bg-[var(--muted)] border-2 border-[var(--card)] flex items-center justify-center text-[10px] font-medium text-[var(--muted-foreground)]">
              +{selectedAccounts.length - 3}
            </div>
          )}
        </div>

        <span className="text-[13px] text-[var(--foreground)] font-medium">
          {getDisplayLabel()}
        </span>

        <ChevronDown className={cn("w-4 h-4 text-[var(--muted-foreground)] transition-transform", isOpen && "rotate-180")} />
      </button>

      {/* Dropdown */}
      {isOpen && (
        <div className="absolute left-0 top-full mt-1 w-64 bg-[var(--card)] border border-[var(--border)] rounded-lg shadow-lg py-1 z-50">
          {/* All accounts option */}
          <button
            onClick={() => {
              selectAll()
              setIsOpen(false)
            }}
            className="w-full flex items-center gap-3 px-3 py-2 hover:bg-[var(--hover)] transition-colors"
          >
            <div className="w-6 h-6 rounded-full bg-[var(--primary)] flex items-center justify-center">
              <Mail className="w-3 h-3 text-white" />
            </div>
            <div className="flex-1 text-left">
              <p className="text-[13px] font-medium text-[var(--foreground)]">Tất cả tài khoản</p>
              <p className="text-[11px] text-[var(--muted-foreground)]">
                {accounts.reduce((sum, a) => sum + (a.email_count || 0), 0)} email
              </p>
            </div>
            {isAllSelected && (
              <Check className="w-4 h-4 text-[var(--primary)]" />
            )}
          </button>

          <div className="border-t border-[var(--border)] my-1" />

          {/* Individual accounts */}
          {accounts.map(account => {
            const isSelected = selectedAccountIds.includes(account.id)
            return (
              <button
                key={account.id}
                onClick={() => toggleAccount(account.id)}
                className="w-full flex items-center gap-3 px-3 py-2 hover:bg-[var(--hover)] transition-colors"
              >
                <div className="relative">
                  {account.avatar_url ? (
                    <img
                      src={account.avatar_url}
                      alt={account.display_name || account.email_address}
                      className="w-6 h-6 rounded-full object-cover"
                    />
                  ) : (
                    <div
                      className="w-6 h-6 rounded-full flex items-center justify-center text-white text-[10px] font-medium"
                      style={{ backgroundColor: account.color }}
                    >
                      {account.email_address[0].toUpperCase()}
                    </div>
                  )}
                  {/* Color indicator */}
                  <div
                    className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border border-[var(--card)]"
                    style={{ backgroundColor: account.color }}
                  />
                </div>

                <div className="flex-1 text-left min-w-0">
                  <p className="text-[13px] font-medium text-[var(--foreground)] truncate">
                    {account.display_name || account.email_address}
                  </p>
                  <p className="text-[11px] text-[var(--muted-foreground)] truncate">
                    {account.email_count || 0} email
                    {account.unread_count ? ` (${account.unread_count} mới)` : ''}
                  </p>
                </div>

                {isSelected && (
                  <Check className="w-4 h-4 text-[var(--primary)] flex-shrink-0" />
                )}
              </button>
            )
          })}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import {
  CheckCircle2, Circle, Clock, HelpCircle, Calendar,
  AlertTriangle, Loader2, ChevronDown, ChevronUp,
  ListTodo, Sparkles, RefreshCw, ExternalLink
} from 'lucide-react'
import { cn } from '@/lib/utils'

interface ActionItem {
  id: string
  type: 'task' | 'deadline' | 'question' | 'meeting' | 'follow_up'
  title: string
  description: string | null
  due_date: string | null
  priority: 'high' | 'medium' | 'low'
  status: 'pending' | 'in_progress' | 'completed' | 'dismissed'
  context: string
}

interface ActionItemsCardProps {
  emailId: string
  onViewAll?: () => void
}

const typeIcons: Record<string, React.ComponentType<{ className?: string }>> = {
  task: ListTodo,
  deadline: Clock,
  question: HelpCircle,
  meeting: Calendar,
  follow_up: RefreshCw,
}

const typeLabels: Record<string, string> = {
  task: 'Việc cần làm',
  deadline: 'Hạn chót',
  question: 'Câu hỏi',
  meeting: 'Cuộc họp',
  follow_up: 'Theo dõi',
}

// Use CSS variables for text to ensure correct theme contrast
const priorityColors: Record<string, string> = {
  high: 'text-[var(--foreground)] bg-red-100 dark:bg-red-500/10',
  medium: 'text-[var(--foreground)] bg-amber-100 dark:bg-amber-500/10',
  low: 'text-[var(--foreground)] bg-gray-100 dark:bg-gray-500/10',
}

const priorityLabels: Record<string, string> = {
  high: 'Gấp',
  medium: 'Trung bình',
  low: 'Thấp',
}

export function ActionItemsCard({ emailId, onViewAll }: ActionItemsCardProps) {
  const [actions, setActions] = useState<ActionItem[]>([])
  const [loading, setLoading] = useState(false)
  const [extracting, setExtracting] = useState(false)
  const [expanded, setExpanded] = useState(true)
  const [hasLoaded, setHasLoaded] = useState(false)

  // Reset when email changes
  useEffect(() => {
    setActions([])
    setHasLoaded(false)
  }, [emailId])

  useEffect(() => {
    if (emailId && !hasLoaded) {
      fetchActions()
    }
  }, [emailId, hasLoaded])

  const fetchActions = async () => {
    setLoading(true)
    setHasLoaded(true)
    try {
      const res = await fetch(`/api/emails/${emailId}/extract-actions`)
      const data = await res.json()
      setActions(data.actions || [])
    } catch (error) {
      console.error('Failed to fetch actions:', error)
    } finally {
      setLoading(false)
    }
  }

  const extractActions = async () => {
    setExtracting(true)
    try {
      const res = await fetch(`/api/emails/${emailId}/extract-actions`, {
        method: 'POST'
      })
      const data = await res.json()
      setActions(data.actions || [])
    } catch (error) {
      console.error('Failed to extract actions:', error)
    } finally {
      setExtracting(false)
    }
  }

  const toggleStatus = async (actionId: string, currentStatus: string) => {
    const newStatus = currentStatus === 'completed' ? 'pending' : 'completed'

    // Optimistic update
    setActions(prev => prev.map(a =>
      a.id === actionId ? { ...a, status: newStatus as ActionItem['status'] } : a
    ))

    try {
      await fetch(`/api/action-items/${actionId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus })
      })
    } catch (error) {
      // Revert on error
      setActions(prev => prev.map(a =>
        a.id === actionId ? { ...a, status: currentStatus as ActionItem['status'] } : a
      ))
      console.error('Failed to update status:', error)
    }
  }

  const formatDueDate = (date: string | null) => {
    if (!date) return null
    const d = new Date(date)
    const today = new Date()
    const tomorrow = new Date(today)
    tomorrow.setDate(tomorrow.getDate() + 1)

    if (d.toDateString() === today.toDateString()) return 'Hôm nay'
    if (d.toDateString() === tomorrow.toDateString()) return 'Ngày mai'

    const diffDays = Math.ceil((d.getTime() - today.getTime()) / (1000 * 60 * 60 * 24))
    if (diffDays < 0) return `Quá hạn ${Math.abs(diffDays)} ngày`
    if (diffDays <= 7) return `${diffDays} ngày nữa`

    return d.toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' })
  }

  if (loading) {
    return (
      <div className="mb-4 p-4 bg-[var(--secondary)] rounded-xl border border-[var(--border)]">
        <div className="flex items-center gap-3">
          <Loader2 className="w-5 h-5 animate-spin text-purple-500" />
          <span className="text-sm text-[var(--foreground-secondary)]">Đang tải actions...</span>
        </div>
      </div>
    )
  }

  // Show extract button if no actions
  if (actions.length === 0 && hasLoaded) {
    return (
      <div className="mb-4">
        <button
          onClick={extractActions}
          disabled={extracting}
          className={cn(
            'w-full flex items-center justify-center gap-2 py-3 px-4 rounded-xl',
            'bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-500/10 dark:to-indigo-500/10',
            'border border-purple-100 dark:border-purple-500/20',
            'text-[var(--foreground)] font-medium text-sm',
            'hover:from-purple-100 hover:to-indigo-100 dark:hover:from-purple-500/20 dark:hover:to-indigo-500/20',
            'transition-all disabled:opacity-50'
          )}
        >
          {extracting ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Đang trích xuất...
            </>
          ) : (
            <>
              <Sparkles className="w-4 h-4" />
              Trích xuất Actions từ email
            </>
          )}
        </button>
      </div>
    )
  }

  if (actions.length === 0) return null

  const pendingActions = actions.filter(a => a.status !== 'completed')
  const hasHighPriority = pendingActions.some(a => a.priority === 'high')

  return (
    <div className={cn(
      'mb-4 rounded-xl border overflow-hidden transition-all duration-200',
      hasHighPriority
        ? 'bg-gradient-to-r from-red-50/50 to-orange-50/50 dark:from-red-500/5 dark:to-orange-500/5 border-red-100 dark:border-red-500/20'
        : 'bg-gradient-to-r from-purple-50/50 to-indigo-50/50 dark:from-purple-500/5 dark:to-indigo-500/5 border-purple-100 dark:border-purple-500/20'
    )}>
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between p-3 hover:bg-white/50 dark:hover:bg-white/5 transition-colors"
      >
        <div className="flex items-center gap-3">
          <ListTodo className={cn(
            'w-5 h-5',
            hasHighPriority
              ? 'text-red-500 dark:text-red-400'
              : 'text-gray-500 dark:text-gray-400'
          )} />
          <div className="text-left">
            <div className="flex items-center gap-2">
              <p className="text-sm font-semibold text-[var(--foreground)]">
                Actions ({pendingActions.length})
              </p>
              {hasHighPriority && (
                <span className="flex items-center gap-1 px-1.5 py-0.5 text-[10px] font-bold bg-red-100 dark:bg-red-500/20 text-[var(--foreground)] rounded">
                  <AlertTriangle className="w-3 h-3" />
                  GẤP
                </span>
              )}
            </div>
            <p className="text-xs text-[var(--foreground-muted)]">
              Việc cần làm từ email này
            </p>
          </div>
        </div>
        {expanded ? (
          <ChevronUp className="w-5 h-5 text-[var(--foreground-muted)]" />
        ) : (
          <ChevronDown className="w-5 h-5 text-[var(--foreground-muted)]" />
        )}
      </button>

      {/* Content */}
      {expanded && (
        <div className="px-3 pb-3 space-y-2">
          {actions.map((action) => {
            const Icon = typeIcons[action.type] || ListTodo
            const isCompleted = action.status === 'completed'
            const dueDateText = formatDueDate(action.due_date)
            const isOverdue = dueDateText?.includes('Quá hạn')

            return (
              <div
                key={action.id}
                className={cn(
                  'flex items-start gap-3 p-3 rounded-lg bg-white/70 dark:bg-white/5',
                  'border border-transparent hover:border-[var(--border)]',
                  'transition-all',
                  isCompleted && 'opacity-60'
                )}
              >
                {/* Checkbox */}
                <button
                  onClick={() => toggleStatus(action.id, action.status)}
                  className={cn(
                    'flex-shrink-0 mt-0.5 transition-colors',
                    isCompleted
                      ? 'text-green-500'
                      : 'text-[var(--muted-foreground)] hover:text-green-500'
                  )}
                >
                  {isCompleted ? (
                    <CheckCircle2 className="w-5 h-5" />
                  ) : (
                    <Circle className="w-5 h-5" />
                  )}
                </button>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-start justify-between gap-2">
                    <p className={cn(
                      'text-sm font-medium text-[var(--foreground)]',
                      isCompleted && 'line-through'
                    )}>
                      {action.title}
                    </p>
                    <span className={cn(
                      'flex-shrink-0 px-1.5 py-0.5 text-[10px] font-semibold rounded',
                      priorityColors[action.priority]
                    )}>
                      {priorityLabels[action.priority]}
                    </span>
                  </div>

                  {/* Meta row */}
                  <div className="flex items-center gap-2 mt-1 flex-wrap">
                    <span className="flex items-center gap-1 text-xs text-[var(--foreground-muted)]">
                      <Icon className="w-3 h-3" />
                      {typeLabels[action.type]}
                    </span>
                    {dueDateText && (
                      <span className={cn(
                        'flex items-center gap-1 text-xs',
                        isOverdue
                          ? 'text-red-600 dark:text-red-400 font-medium'
                          : 'text-[var(--foreground-muted)]'
                      )}>
                        <Clock className="w-3 h-3" />
                        {dueDateText}
                      </span>
                    )}
                  </div>

                  {/* Context quote */}
                  {action.context && (
                    <p className="mt-2 text-xs text-[var(--foreground-subtle)] italic line-clamp-2 pl-2 border-l-2 border-[var(--border)]">
                      {`"${action.context}"`}
                    </p>
                  )}
                </div>
              </div>
            )
          })}

          {/* View all link */}
          {onViewAll && (
            <button
              onClick={onViewAll}
              className="w-full flex items-center justify-center gap-1.5 py-2 text-xs font-medium text-[var(--foreground-secondary)] hover:text-[var(--foreground)] transition-colors"
            >
              Xem tất cả Actions
              <ExternalLink className="w-3 h-3" />
            </button>
          )}
        </div>
      )}
    </div>
  )
}

'use client';

/**
 * AI Bottom Bar
 * Compact AI features bar at bottom of email detail
 */

import { memo, useState, useCallback } from 'react';
import {
  Sparkles,
  FileText,
  MessageSquare,
  CheckSquare,
  ChevronUp,
  ChevronDown,
  Loader2,
  Copy,
  Check,
  Zap,
  X,
  AlertCircle,
  RefreshCw,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useAIFeatures } from '@/hooks/use-ai-features';

interface AIBottomBarProps {
  emailId: string;
  category?: string | null;
  priority?: number | null;
  onReplySelect?: (reply: string) => void;
  className?: string;
}

type ExpandedSection = 'summary' | 'replies' | 'actions' | null;

export const AIBottomBar = memo(function AIBottomBar({
  emailId,
  category,
  priority,
  onReplySelect,
  className,
}: AIBottomBarProps) {
  const [expandedSection, setExpandedSection] = useState<ExpandedSection>(null);
  const [copiedReply, setCopiedReply] = useState<number | null>(null);

  const {
    results,
    isLoading,
    triggerFeature,
    refresh,
  } = useAIFeatures(emailId);

  // ALL useCallback hooks MUST be called before any early returns (React rules of hooks)
  const toggleSection = useCallback((section: ExpandedSection) => {
    setExpandedSection(prev => prev === section ? null : section);
  }, []);

  const handleCopyReply = useCallback((reply: string, index: number) => {
    navigator.clipboard.writeText(reply);
    setCopiedReply(index);
    setTimeout(() => setCopiedReply(null), 2000);
  }, []);

  const handleSelectReply = useCallback((reply: string) => {
    onReplySelect?.(reply);
  }, [onReplySelect]);

  // Retry handlers for each feature
  const handleRetrySummary = useCallback(() => {
    triggerFeature('summary');
  }, [triggerFeature]);

  const handleRetryReplies = useCallback(() => {
    triggerFeature('smart_reply');
  }, [triggerFeature]);

  const handleRetryActions = useCallback(() => {
    triggerFeature('action_items');
  }, [triggerFeature]);

  // Don't show for spam (after all hooks)
  if (category === 'spam') {
    return null;
  }

  // Extract results - handle different data structures
  const summaryData = results.summary?.status === 'success' ? results.summary.data : null;

  // Extract summary as array of bullet points for better display
  const getSummaryBullets = (data: unknown): string[] | null => {
    if (!data) return null;

    // If it's a JSON string, parse it first
    let parsed = data;
    if (typeof data === 'string') {
      if (data.startsWith('{') || data.startsWith('[')) {
        try {
          parsed = JSON.parse(data);
        } catch {
          // Not JSON, return as single item
          return [data];
        }
      } else {
        return [data];
      }
    }

    // If it's an array of strings, return directly
    if (Array.isArray(parsed)) {
      return parsed.filter(item => typeof item === 'string');
    }

    // If it's an object with summary array
    const obj = parsed as Record<string, unknown>;
    if (Array.isArray(obj.summary)) {
      return obj.summary.filter(item => typeof item === 'string');
    }
    if (typeof obj.summary === 'string') {
      return [obj.summary];
    }
    if (typeof obj.text === 'string') {
      return [obj.text];
    }

    return null;
  };

  const summaryBullets = getSummaryBullets(summaryData);
  const summary = summaryBullets ? summaryBullets.join(' ') : null; // For hasData check

  const smartRepliesData = results.smart_reply?.status === 'success' ? results.smart_reply.data : null;
  // Smart replies can be: { replies: string[] } OR string[] OR { suggestions: string[] }
  const getSmartReplies = (data: unknown): string[] | null => {
    if (!data) return null;
    if (Array.isArray(data)) return data.filter(r => typeof r === 'string');
    const obj = data as Record<string, unknown>;
    if (Array.isArray(obj.replies)) return obj.replies.filter(r => typeof r === 'string');
    if (Array.isArray(obj.suggestions)) return obj.suggestions.filter(r => typeof r === 'string');
    return null;
  };
  const smartReplies = getSmartReplies(smartRepliesData);

  const actionItemsData = results.action_items?.status === 'success' ? results.action_items.data : null;
  // Action items can be: { items: [] } OR [] OR { actions: [] }
  const getActionItems = (data: unknown): unknown[] | null => {
    if (!data) return null;
    if (Array.isArray(data)) return data;
    const obj = data as Record<string, unknown>;
    if (Array.isArray(obj.items)) return obj.items;
    if (Array.isArray(obj.actions)) return obj.actions;
    if (Array.isArray(obj.tasks)) return obj.tasks;
    return null;
  };
  const actionItems = getActionItems(actionItemsData);

  // Loading states - use isLoading when we don't have data yet (batch API in progress)
  const summaryLoading = results.summary?.status === 'loading' || (isLoading && !results.summary);
  const repliesLoading = results.smart_reply?.status === 'loading' || (isLoading && !results.smart_reply);
  const actionsLoading = results.action_items?.status === 'loading' || (isLoading && !results.action_items);

  // Check if any AI features are available or loading
  const hasAnyData = summary || (smartReplies && smartReplies.length > 0) || (actionItems && actionItems.length > 0);
  const anyLoading = isLoading || summaryLoading || repliesLoading || actionsLoading;

  // Always show bar - either loading or has data
  // Only hide if definitely no data and not loading
  if (!hasAnyData && !anyLoading && Object.keys(results).length > 0) {
    // API returned but no useful data - still show empty bar for consistency
  }

  return (
    <div className={cn(
      'flex-shrink-0 border-t border-[var(--border)] bg-[var(--secondary)]',
      className
    )}>
      {/* Collapsed Bar */}
      <div className="flex items-center gap-1 px-4 py-2">
        {/* AI Icon */}
        <div className="flex items-center gap-2 mr-2">
          <Sparkles className="w-4 h-4 text-purple-500" />
          <span className="text-xs font-medium text-purple-500">AI</span>
        </div>

        {/* Summary Button */}
        <FeatureButton
          icon={FileText}
          label="Tóm tắt"
          isLoading={summaryLoading}
          hasData={!!summary}
          hasError={results.summary?.status === 'error'}
          isExpanded={expandedSection === 'summary'}
          onClick={() => toggleSection('summary')}
          onRetry={handleRetrySummary}
        />

        {/* Smart Replies Button */}
        <FeatureButton
          icon={MessageSquare}
          label="Gợi ý"
          isLoading={repliesLoading}
          hasData={!!smartReplies && Array.isArray(smartReplies) && smartReplies.length > 0}
          hasError={results.smart_reply?.status === 'error'}
          isExpanded={expandedSection === 'replies'}
          onClick={() => toggleSection('replies')}
          onRetry={handleRetryReplies}
          count={Array.isArray(smartReplies) ? smartReplies.length : undefined}
        />

        {/* Action Items Button */}
        <FeatureButton
          icon={CheckSquare}
          label="Actions"
          isLoading={actionsLoading}
          hasData={!!actionItems && Array.isArray(actionItems) && actionItems.length > 0}
          hasError={results.action_items?.status === 'error'}
          isExpanded={expandedSection === 'actions'}
          onClick={() => toggleSection('actions')}
          onRetry={handleRetryActions}
          count={Array.isArray(actionItems) ? actionItems.length : undefined}
        />

        {/* Priority indicator */}
        {(priority || 0) >= 4 && (
          <div className="ml-auto flex items-center gap-1 px-2 py-1 bg-red-100 dark:bg-red-900/30 rounded text-xs text-red-600 dark:text-red-400">
            <Zap className="w-3 h-3" />
            <span>Quan trọng</span>
          </div>
        )}
      </div>

      {/* Expanded Content */}
      {expandedSection && (
        <div className="border-t border-[var(--border)]">
          {/* Summary Section */}
          {expandedSection === 'summary' && (
            <ExpandedPanel
              title="Tóm tắt AI"
              onClose={() => setExpandedSection(null)}
            >
              {summaryLoading ? (
                <LoadingState />
              ) : summaryBullets && summaryBullets.length > 0 ? (
                <ul className="space-y-1.5">
                  {summaryBullets.map((bullet, index) => (
                    <li key={index} className="flex items-start gap-2 text-sm text-[var(--foreground)]">
                      <span className="text-purple-500 mt-1">•</span>
                      <span>{bullet}</span>
                    </li>
                  ))}
                </ul>
              ) : results.summary?.status === 'success' && !results.summary?.data ? (
                <EmptyState message="Email quá ngắn để tóm tắt" />
              ) : (
                <EmptyState message="Không có tóm tắt" />
              )}
            </ExpandedPanel>
          )}

          {/* Smart Replies Section */}
          {expandedSection === 'replies' && (
            <ExpandedPanel
              title="Gợi ý trả lời"
              onClose={() => setExpandedSection(null)}
            >
              {repliesLoading ? (
                <LoadingState />
              ) : smartReplies && Array.isArray(smartReplies) && smartReplies.length > 0 ? (
                <div className="flex flex-wrap gap-2">
                  {smartReplies.map((reply: string, index: number) => (
                    <SmartReplyChip
                      key={index}
                      reply={reply}
                      index={index}
                      isCopied={copiedReply === index}
                      onCopy={() => handleCopyReply(reply, index)}
                      onSelect={() => handleSelectReply(reply)}
                    />
                  ))}
                </div>
              ) : (
                <EmptyState message="Không có gợi ý" />
              )}
            </ExpandedPanel>
          )}

          {/* Action Items Section */}
          {expandedSection === 'actions' && (
            <ExpandedPanel
              title="Công việc cần làm"
              onClose={() => setExpandedSection(null)}
            >
              {actionsLoading ? (
                <LoadingState />
              ) : actionItems && Array.isArray(actionItems) && actionItems.length > 0 ? (
                <ul className="space-y-2">
                  {actionItems.map((item: unknown, index: number) => (
                    <li key={index} className="flex items-start gap-2">
                      <CheckSquare className="w-4 h-4 text-green-500 mt-0.5 flex-shrink-0" />
                      <span className="text-sm text-[var(--foreground)]">
                        {typeof item === 'string' ? item : (item as { task?: string; description?: string })?.task || (item as { task?: string; description?: string })?.description || ''}
                      </span>
                    </li>
                  ))}
                </ul>
              ) : (
                <EmptyState message="Không có công việc" />
              )}
            </ExpandedPanel>
          )}
        </div>
      )}
    </div>
  );
});

