interface FeatureButtonProps {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  isLoading?: boolean;
  hasData?: boolean;
  hasError?: boolean;
  isExpanded?: boolean;
  onClick?: () => void;
  onRetry?: () => void;
  count?: number;
}

const FeatureButton = memo(function FeatureButton({
  icon: Icon,
  label,
  isLoading,
  hasData,
  hasError,
  isExpanded,
  onClick,
  onRetry,
  count,
}: FeatureButtonProps) {
  const handleClick = () => {
    if (hasError && onRetry) {
      onRetry();
    } else {
      onClick?.();
    }
  };

  return (
    <button
      onClick={handleClick}
      disabled={isLoading}
      className={cn(
        'flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all',
        isExpanded
          ? 'bg-purple-100 dark:bg-purple-900/30 text-[var(--foreground)]'
          : hasError
            ? 'bg-red-100 dark:bg-red-900/20 text-[var(--foreground)] hover:bg-red-200 dark:hover:bg-red-900/30'
            : hasData
              ? 'bg-[var(--card)] text-[var(--foreground)] hover:bg-[var(--hover)] shadow-sm'
              : 'text-[var(--muted-foreground)] hover:text-[var(--foreground)]',
        isLoading && 'opacity-50 cursor-wait'
      )}
    >
      {isLoading ? (
        <Loader2 className="w-3.5 h-3.5 animate-spin" />
