'use client'

import { useState } from 'react'
import {
  Paperclip, FileText, Image, FileSpreadsheet,
  File, Download, Eye, X, Loader2
} from 'lucide-react'
import { cn } from '@/lib/utils'

interface Attachment {
  id: string
  filename: string
  content_type: string
  size: number
  is_inline: boolean
}

interface AttachmentListProps {
  attachments: Attachment[]
}

// Get icon based on content type
function getFileIcon(contentType: string) {
  if (contentType.startsWith('image/')) return Image
  if (contentType.includes('pdf')) return FileText
  if (contentType.includes('spreadsheet') || contentType.includes('excel')) return FileSpreadsheet
  if (contentType.includes('document') || contentType.includes('word')) return FileText
  return File
}

// Get color based on content type
function getFileColor(contentType: string) {
  if (contentType.startsWith('image/')) return 'bg-purple-100 dark:bg-purple-500/20 text-purple-600 dark:text-purple-400'
  if (contentType.includes('pdf')) return 'bg-red-100 dark:bg-red-500/20 text-red-600 dark:text-red-400'
  if (contentType.includes('spreadsheet') || contentType.includes('excel')) return 'bg-green-100 dark:bg-green-500/20 text-green-600 dark:text-green-400'
  if (contentType.includes('document') || contentType.includes('word')) return 'bg-blue-100 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400'
  return 'bg-[var(--secondary)] text-[var(--muted-foreground)]'
}

// Format file size
function formatSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export function AttachmentList({ attachments }: AttachmentListProps) {
  const [previewUrl, setPreviewUrl] = useState<string | null>(null)
  const [previewName, setPreviewName] = useState<string>('')
  const [previewType, setPreviewType] = useState<string>('')
  const [loading, setLoading] = useState<string | null>(null)

  // Filter out inline attachments (shown in email body)
  const visibleAttachments = attachments.filter(a => !a.is_inline)

  if (visibleAttachments.length === 0) return null

  const handlePreview = async (attachment: Attachment) => {
    if (!attachment.content_type.startsWith('image/') && !attachment.content_type.includes('pdf')) {
      // Direct download for non-previewable files
      handleDownload(attachment)
      return
    }

    setLoading(attachment.id)
    try {
      const url = `/api/attachments/${attachment.id}`
      setPreviewUrl(url)
      setPreviewName(attachment.filename)
      setPreviewType(attachment.content_type)
    } finally {
      setLoading(null)
    }
  }

  const handleDownload = (attachment: Attachment) => {
    const link = document.createElement('a')
    link.href = `/api/attachments/${attachment.id}`
    link.download = attachment.filename
    link.click()
  }

  const closePreview = () => {
    setPreviewUrl(null)
    setPreviewName('')
    setPreviewType('')
  }

  return (
    <>
      {/* Attachment List */}
      <div className="border-t border-[var(--border)] mt-4 pt-4">
        <div className="flex items-center gap-2 mb-3">
          <Paperclip className="w-4 h-4 text-[var(--muted)]" />
          <span className="text-[13px] font-medium text-[var(--muted)]">
            {visibleAttachments.length} tệp đính kèm
          </span>
        </div>

        <div className="flex flex-wrap gap-2">
          {visibleAttachments.map((att) => {
            const Icon = getFileIcon(att.content_type)
            const colorClass = getFileColor(att.content_type)
            const isPreviewable = att.content_type.startsWith('image/') || att.content_type.includes('pdf')

            return (
              <div
                key={att.id}
                className="flex items-center gap-2 px-3 py-2 bg-[var(--secondary)] rounded-lg hover:bg-[var(--border)] transition-colors group"
              >
                {/* Icon */}
                <div className={cn('w-8 h-8 rounded-lg flex items-center justify-center', colorClass)}>
                  <Icon className="w-4 h-4" />
                </div>

                {/* Info */}
                <div className="min-w-0">
                  <div className="text-[13px] font-medium text-[var(--foreground)] truncate max-w-[150px]">
                    {att.filename}
                  </div>
                  <div className="text-[11px] text-[var(--muted)]">
                    {formatSize(att.size)}
                  </div>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1 ml-2 opacity-0 group-hover:opacity-100 transition-opacity">
                  {isPreviewable && (
                    <button
                      onClick={() => handlePreview(att)}
                      disabled={loading === att.id}
                      className="p-1.5 rounded-lg hover:bg-[var(--card)] text-[var(--muted-foreground)]"
                      title="Xem trước"
                    >
                      {loading === att.id ? (
                        <Loader2 className="w-4 h-4 animate-spin" />
                      ) : (
                        <Eye className="w-4 h-4" />
                      )}
                    </button>
                  )}
                  <button
                    onClick={() => handleDownload(att)}
                    className="p-1.5 rounded-lg hover:bg-[var(--card)] text-[var(--muted-foreground)]"
                    title="Tải xuống"
                  >
                    <Download className="w-4 h-4" />
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      </div>

      {/* Preview Modal */}
      {previewUrl && (
        <div className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4">
          {/* Close button */}
          <button
            onClick={closePreview}
            className="absolute top-4 right-4 p-2 rounded-full bg-white/10 text-white hover:bg-white/20 transition-colors z-10"
          >
            <X className="w-6 h-6" />
          </button>

          {/* Filename */}
          <div className="absolute top-4 left-4 text-white text-[14px] font-medium">
            {previewName}
          </div>

          {/* Download button */}
          <a
            href={previewUrl}
            download={previewName}
            className="absolute top-4 right-16 p-2 rounded-full bg-white/10 text-white hover:bg-white/20 transition-colors"
          >
            <Download className="w-6 h-6" />
          </a>

          {/* Preview content */}
          <div className="max-w-full max-h-full overflow-auto">
            {previewType.includes('pdf') ? (
              <iframe
                src={previewUrl}
                className="w-[90vw] h-[85vh] bg-white rounded-lg"
                title={previewName}
              />
            ) : (
              <img
                src={previewUrl}
                alt={previewName}
                className="max-w-[90vw] max-h-[85vh] object-contain rounded-lg"
              />
            )}
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import {
  Star, Archive, Trash2, Reply, Forward, MoreHorizontal,
  Sparkles, ChevronDown, ChevronUp, Loader2, X, Mail,
  Check, ShieldAlert, Ban, Printer, Download, AlertTriangle
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { ReplyAssistant } from '@/components/ai/reply-assistant'
import { AIBottomBar } from './ai-bottom-bar'
import { sanitizeEmailHtml } from '@/lib/email/html-sanitizer'
import { AttachmentList } from './attachment-list'
import type { Email } from '@/types'

interface Attachment {
  id: string
  filename: string
  content_type: string
  size: number
  is_inline: boolean
}

interface Props {
  email: Email
  onBack: () => void
  onRefresh: () => void
  onStar?: (id: string) => void
  onArchive?: (id: string) => void
  onDelete?: (id: string) => void
  fullWidth?: boolean
}

export function EmailDetailFull({
  email,
  onBack,
  onRefresh,
  onStar,
  onArchive,
  onDelete,
  fullWidth = false
}: Props) {
  const router = useRouter()
  const [showAIAssistant, setShowAIAssistant] = useState(false)
  const [showAIAnalysis, setShowAIAnalysis] = useState(false)
  const [actionLoading, setActionLoading] = useState<string | null>(null)
  const [feedbackLoading, setFeedbackLoading] = useState<string | null>(null)
  const [currentCategory, setCurrentCategory] = useState(email.category)
  const [attachments, setAttachments] = useState<Attachment[]>([])
  const [showBlockMenu, setShowBlockMenu] = useState(false)
  const [showMoreMenu, setShowMoreMenu] = useState(false)
  const blockMenuRef = useRef<HTMLDivElement>(null)
  const moreMenuRef = useRef<HTMLDivElement>(null)
  const previousEmailId = useRef<string | null>(null)

  // Reset UI state when switching emails - instant feedback
  useEffect(() => {
    if (email.id !== previousEmailId.current) {
      setShowAIAssistant(false)
      setShowAIAnalysis(false)
      setActionLoading(null)
      setFeedbackLoading(null)
      setCurrentCategory(email.category)
      setAttachments([])
      setShowBlockMenu(false)
      setShowMoreMenu(false)
      previousEmailId.current = email.id

      // Fetch attachments if email has them
      if (email.attachment_count && email.attachment_count > 0) {
        fetchAttachments(email.id)
      }
    }
  }, [email.id, email.category, email.attachment_count])

  // Close menus when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (blockMenuRef.current && !blockMenuRef.current.contains(event.target as Node)) {
        setShowBlockMenu(false)
      }
      if (moreMenuRef.current && !moreMenuRef.current.contains(event.target as Node)) {
        setShowMoreMenu(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // Fetch attachments
  const fetchAttachments = async (emailId: string) => {
    try {
      const res = await fetch(`/api/emails/${emailId}/attachments`)
      const data = await res.json()
      setAttachments(data.attachments || [])
    } catch (error) {
      console.error('Failed to fetch attachments:', error)
    }
  }

  const handleStar = () => {
    onStar?.(email.id)
  }

  // Handle "Not Spam" feedback
  const handleNotSpam = async () => {
    setFeedbackLoading('not_spam')
    try {
      const res = await fetch(`/api/emails/${email.id}/feedback`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'not_spam' })
      })
      const data = await res.json()
      if (data.success) {
        setCurrentCategory(data.newCategory || 'personal')
        onRefresh?.()
      }
    } catch (e) {
      console.error('Not spam error:', e)
    } finally {
      setFeedbackLoading(null)
    }
  }

  // Handle "Is Spam" feedback
  const handleIsSpam = async () => {
    setFeedbackLoading('is_spam')
    try {
      const res = await fetch(`/api/emails/${email.id}/feedback`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'is_spam' })
      })
      const data = await res.json()
      if (data.success) {
        setCurrentCategory('spam')
        onRefresh?.()
      }
    } catch (e) {
      console.error('Is spam error:', e)
    } finally {
      setFeedbackLoading(null)
    }
  }

  // Handle unsubscribe/block sender
  const handleUnsubscribe = async (blockDomain: boolean = false) => {
    const domain = email.from_address?.split('@')[1]
    const target = blockDomain ? `@${domain}` : email.from_address

    if (!confirm(`Chặn tất cả email từ ${target}?\n\nEmail từ ${target} sẽ không được đồng bộ nữa.`)) return

    setFeedbackLoading('block')
    try {
      const res = await fetch('/api/unsubscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email_address: email.from_address,
          sender_name: email.from_name,
          unsubscribe_domain: blockDomain,
          delete_existing: true
        })
      })
      const data = await res.json()
      if (data.success) {
        alert(`Đã chặn ${data.blocked}${data.deleted > 0 ? ` và xóa ${data.deleted} email` : ''}`)
        onRefresh?.()
        onBack()
      }
    } catch (e) {
      console.error('Unsubscribe error:', e)
      alert('Có lỗi xảy ra khi chặn người gửi')
    } finally {
      setFeedbackLoading(null)
    }
  }

  // Legacy block sender (for spam feedback)
  const handleBlockSender = async () => {
    handleUnsubscribe(false)
  }

  const handleArchive = () => {
    setActionLoading('archive')
    onArchive?.(email.id)
  }

  const handleDelete = () => {
    setActionLoading('delete')
    onDelete?.(email.id)
  }

  const handleClose = () => {
    onBack()
  }

  const handleUseDraft = (subject: string, body: string) => {
    const params = new URLSearchParams({
      replyTo: email.from_address || '',
      replyToEmailId: email.id,
      subject,
      body,
    })
    router.push(`/compose?${params.toString()}`)
  }

  const formatDate = (date: string | null) => {
    if (!date) return ''
    return new Date(date).toLocaleDateString('vi-VN', {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getCategoryLabel = (category: string | null) => {
    if (!category) return ''
    const labels: Record<string, string> = {
      work: 'Công việc',
      personal: 'Cá nhân',
      transaction: 'Giao dịch',
      newsletter: 'Newsletter',
      promotion: 'Khuyến mãi',
      social: 'Mạng XH',
    }
    return labels[category] || category
  }

  const getPriorityLabel = (priority: number | null) => {
    if (!priority) return 'Bình thường'
    if (priority >= 5) return 'Khẩn cấp'
    if (priority >= 4) return 'Cao'
    if (priority >= 3) return 'Bình thường'
    return 'Thấp'
  }

  return (
    <div className={cn('flex flex-col h-full', fullWidth && 'max-w-4xl mx-auto')}>
      {/* Action Bar */}
      <div className="flex items-center justify-between px-6 py-3 border-b border-[var(--border)]">
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={handleStar}
            className={cn(
              'p-2 rounded-lg transition-colors',
              email.is_starred
                ? 'text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20'
                : 'text-[var(--muted-foreground)] hover:text-[var(--muted)] hover:bg-[var(--hover)]'
            )}
          >
            <Star
              className="w-5 h-5"
              strokeWidth={1.5}
              fill={email.is_starred ? 'currentColor' : 'none'}
            />
          </button>
          <button
            type="button"
            onClick={handleArchive}
            disabled={actionLoading === 'archive'}
            className="p-2 rounded-lg text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors"
          >
            {actionLoading === 'archive' ? (
              <Loader2 className="w-5 h-5 animate-spin" strokeWidth={1.5} />
            ) : (
              <Archive className="w-5 h-5" strokeWidth={1.5} />
            )}
          </button>
          <button
            type="button"
            onClick={handleDelete}
            disabled={actionLoading === 'delete'}
            className="p-2 rounded-lg text-[var(--muted)] hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
          >
            {actionLoading === 'delete' ? (
              <Loader2 className="w-5 h-5 animate-spin" strokeWidth={1.5} />
            ) : (
              <Trash2 className="w-5 h-5" strokeWidth={1.5} />
            )}
          </button>
          {/* Spam Feedback Buttons */}
          {currentCategory === 'spam' ? (
            <button
              type="button"
              onClick={handleNotSpam}
              disabled={feedbackLoading === 'not_spam'}
              className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-[13px] font-medium text-gray-900 dark:text-white bg-green-50 dark:bg-green-900/30 hover:bg-green-100 dark:hover:bg-green-900/50 transition-colors"
            >
              {feedbackLoading === 'not_spam' ? (
                <Loader2 className="w-4 h-4 animate-spin" strokeWidth={1.5} />
              ) : (
                <Check className="w-4 h-4" strokeWidth={1.5} />
              )}
              Không phải spam
            </button>
          ) : (
            <button
              type="button"
              onClick={handleIsSpam}
              disabled={feedbackLoading === 'is_spam'}
              className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-[13px] font-medium text-gray-900 dark:text-white bg-orange-50 dark:bg-orange-900/30 hover:bg-orange-100 dark:hover:bg-orange-900/50 transition-colors"
            >
              {feedbackLoading === 'is_spam' ? (
                <Loader2 className="w-4 h-4 animate-spin" strokeWidth={1.5} />
              ) : (
                <ShieldAlert className="w-4 h-4" strokeWidth={1.5} />
              )}
              Spam
            </button>
          )}

          {/* Block Sender Dropdown */}
          <div className="relative" ref={blockMenuRef}>
            <button
              type="button"
              onClick={() => setShowBlockMenu(!showBlockMenu)}
              disabled={feedbackLoading === 'block'}
              className="p-2 rounded-lg text-[var(--muted-foreground)] hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
              title="Chặn người gửi"
            >
              {feedbackLoading === 'block' ? (
                <Loader2 className="w-5 h-5 animate-spin" strokeWidth={1.5} />
              ) : (
                <Ban className="w-5 h-5" strokeWidth={1.5} />
              )}
            </button>

            {showBlockMenu && (
              <div className="absolute left-0 top-full mt-1 w-56 bg-[var(--card)] rounded-lg border border-[var(--border)] shadow-lg z-50 py-1">
                <button
                  type="button"
                  onClick={() => {
                    setShowBlockMenu(false)
                    handleUnsubscribe(false)
                  }}
                  className="w-full px-3 py-2 text-left text-[13px] text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors"
                >
                  <span className="font-medium">Chặn {email.from_address?.split('@')[0]}</span>
                  <span className="block text-[12px] text-[var(--muted-foreground)]">
                    Chặn email từ {email.from_address}
                  </span>
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setShowBlockMenu(false)
                    handleUnsubscribe(true)
                  }}
                  className="w-full px-3 py-2 text-left text-[13px] text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors border-t border-[var(--border)]"
                >
                  <span className="font-medium">Chặn @{email.from_address?.split('@')[1]}</span>
                  <span className="block text-[12px] text-[var(--muted-foreground)]">
                    Chặn tất cả email từ domain này
                  </span>
                </button>
              </div>
            )}
          </div>

          {/* More Menu Dropdown */}
          <div className="relative" ref={moreMenuRef}>
            <button
              type="button"
              onClick={() => setShowMoreMenu(!showMoreMenu)}
              className="p-2 rounded-lg text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors"
            >
              <MoreHorizontal className="w-5 h-5" strokeWidth={1.5} />
            </button>

            {showMoreMenu && (
              <div className="absolute right-0 top-full mt-1 w-48 bg-[var(--card)] rounded-lg border border-[var(--border)] shadow-lg z-50 py-1">
                {/* Print */}
                <button
                  type="button"
                  onClick={() => {
                    setShowMoreMenu(false)
                    window.print()
                  }}
                  className="w-full flex items-center gap-3 px-3 py-2 text-left text-[13px] text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors"
                >
                  <Printer className="w-4 h-4" strokeWidth={1.5} />
                  In email
                </button>

                {/* Download */}
                <button
                  type="button"
                  onClick={() => {
                    setShowMoreMenu(false)
                    // Create email content for download
                    const content = `From: ${email.from_name} <${email.from_address}>\nTo: ${email.to_addresses?.join(', ') || ''}\nDate: ${email.received_at}\nSubject: ${email.subject}\n\n${email.body_text || ''}`
                    const blob = new Blob([content], { type: 'text/plain' })
                    const url = URL.createObjectURL(blob)
                    const a = document.createElement('a')
                    a.href = url
                    a.download = `${email.subject || 'email'}.eml`
                    a.click()
                    URL.revokeObjectURL(url)
                  }}
                  className="w-full flex items-center gap-3 px-3 py-2 text-left text-[13px] text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors"
                >
                  <Download className="w-4 h-4" strokeWidth={1.5} />
                  Tải xuống
                </button>

                <div className="my-1 border-t border-[var(--border)]" />

                {/* Report Phishing */}
                <button
                  type="button"
                  onClick={async () => {
                    setShowMoreMenu(false)
                    try {
                      await fetch('/api/ai/feedback', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                          emailId: email.id,
                          feedbackType: 'report_phishing',
                          context: { from: email.from_address, subject: email.subject }
                        })
                      })
                      alert('Đã báo cáo email lừa đảo. Cảm ơn bạn!')
                    } catch {
                      alert('Không thể báo cáo. Vui lòng thử lại.')
                    }
                  }}
                  className="w-full flex items-center gap-3 px-3 py-2 text-left text-[13px] text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                >
                  <AlertTriangle className="w-4 h-4" strokeWidth={1.5} />
                  Báo cáo lừa đảo
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setShowAIAssistant(!showAIAssistant)}
            className={cn(
              'flex items-center gap-2 px-3 py-1.5 rounded-lg text-[13px] font-medium transition-colors',
              showAIAssistant
                ? 'bg-[var(--primary)] text-[var(--primary-foreground)]'
                : 'text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--hover)]'
            )}
          >
            <Sparkles className="w-4 h-4" strokeWidth={1.5} />
            AI Trả lời
          </button>
          <button
            type="button"
            onClick={handleClose}
            className="p-2 rounded-lg text-[var(--muted-foreground)] hover:text-[var(--muted)] hover:bg-[var(--hover)] transition-colors"
            title="Đóng"
          >
            <X className="w-5 h-5" strokeWidth={1.5} />
          </button>
        </div>
      </div>

      {/* Email Header */}
      <div className="px-6 py-4 border-b border-[var(--border)]">
        <h1 className="text-[20px] font-medium text-[var(--foreground)] mb-4">
          {email.subject || '(Không có tiêu đề)'}
        </h1>

        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            {/* Avatar */}
            <div className="w-10 h-10 rounded-full bg-[var(--secondary)] flex items-center justify-center">
              <span className="text-[14px] font-medium text-[var(--muted)]">
                {(email.from_name || email.from_address)?.[0]?.toUpperCase()}
              </span>
            </div>

            <div>
              <div className="flex items-center gap-2">
                <span className="text-[15px] font-medium text-[var(--foreground)]">
                  {email.from_name || email.from_address?.split('@')[0]}
                </span>
                <span className="text-[13px] text-[var(--muted-foreground)]">
                  {'<'}{email.from_address}{'>'}
                </span>
              </div>
              <p className="text-[13px] text-[var(--muted)]">
                Đến: tôi
              </p>
            </div>
          </div>

          <div className="text-right">
            <p className="text-[13px] text-[var(--muted-foreground)]">
              {formatDate(email.received_at)}
            </p>
          </div>
        </div>

        {/* AI Analysis - Compact inline */}
        {(email.category || email.priority || email.summary) && (
          <div className="mt-4">
            <button
              type="button"
              onClick={() => setShowAIAnalysis(!showAIAnalysis)}
              className="flex items-center gap-2 text-[13px] text-[var(--muted)] hover:text-[var(--foreground)] transition-colors"
            >
              <Sparkles className="w-3.5 h-3.5" strokeWidth={1.5} />
              <span className="flex items-center gap-2">
                {email.priority && (
                  <span className={cn(
                    'px-1.5 py-0.5 rounded text-[11px] font-medium',
                    (email.priority || 0) >= 4 ? 'bg-red-100 dark:bg-red-900/30 text-gray-900 dark:text-white' : 'bg-[var(--secondary)] text-[var(--muted)]'
                  )}>
                    {getPriorityLabel(email.priority)}
                  </span>
                )}
                {email.category && (
                  <span className="px-1.5 py-0.5 rounded text-[11px] font-medium bg-[var(--secondary)] text-[var(--muted)]">
                    {getCategoryLabel(email.category)}
                  </span>
                )}
              </span>
              {showAIAnalysis ? (
                <ChevronUp className="w-3.5 h-3.5" strokeWidth={1.5} />
              ) : (
                <ChevronDown className="w-3.5 h-3.5" strokeWidth={1.5} />
              )}
            </button>

            {showAIAnalysis && email.summary && (
              <div className="mt-2 p-3 rounded-lg bg-[var(--secondary)] border border-[var(--border)]">
                <p className="text-[13px] text-[var(--muted)]">
                  {email.summary}
                </p>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Email Body */}
      <div className="flex-1 overflow-y-auto px-6 py-6">
        {email.body_html && email.body_html.replace(/<[^>]*>/g, '').trim().length > 10 ? (
          <div
            className="email-content prose prose-sm dark:prose-invert max-w-none text-[var(--foreground)] animate-fadeIn"
            dangerouslySetInnerHTML={{ __html: sanitizeEmailHtml(email.body_html, { allowImages: true }) }}
          />
        ) : email.body_text && email.body_text.trim().length > 0 ? (
          <pre className="whitespace-pre-wrap font-sans text-[15px] text-[var(--foreground)] leading-relaxed bg-transparent p-0 m-0 animate-fadeIn">
            {email.body_text}
          </pre>
        ) : email.snippet && email.snippet.trim().length > 0 ? (
          <div className="text-[15px] text-[var(--foreground)] leading-relaxed whitespace-pre-wrap animate-fadeIn">
            {email.snippet}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-16 text-center animate-fadeIn">
            <div className="w-16 h-16 rounded-full bg-[var(--secondary)] flex items-center justify-center mb-4">
              <Mail className="w-8 h-8 text-[var(--muted-foreground)]" strokeWidth={1.5} />
            </div>
            <p className="text-[15px] text-[var(--muted)] mb-1">
              Email này không có nội dung
            </p>
            <p className="text-[13px] text-[var(--muted-foreground)]">
              Có thể chỉ có tiêu đề hoặc là email test
            </p>
          </div>
        )}

        {/* Attachments */}
        {attachments.length > 0 && (
          <AttachmentList attachments={attachments} />
        )}
      </div>

      {/* AI Bottom Bar */}
      <AIBottomBar
        emailId={email.id}
        category={currentCategory}
        priority={email.priority}
        onReplySelect={(reply) => {
          handleUseDraft(`Re: ${email.subject}`, reply)
        }}
      />

      {/* Quick Reply Bar */}
      {!showAIAssistant && (
        <div className="px-6 py-4 border-t border-[var(--border)] bg-[var(--secondary)]">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => handleUseDraft(`Re: ${email.subject}`, '')}
              className="flex items-center gap-2 px-4 py-2 bg-[var(--primary)] text-[var(--primary-foreground)] rounded-lg text-[14px] font-medium hover:opacity-90 transition-colors"
            >
              <Reply className="w-4 h-4" strokeWidth={1.5} />
              Trả lời
            </button>
            <button
              type="button"
              className="flex items-center gap-2 px-4 py-2 border border-[var(--border)] rounded-lg text-[14px] text-[var(--muted)] hover:bg-[var(--hover)] transition-colors"
            >
              <Forward className="w-4 h-4" strokeWidth={1.5} />
              Chuyển tiếp
            </button>
          </div>
        </div>
      )}

      {/* AI Reply Assistant */}
      {showAIAssistant && (
        <div className="border-t border-[var(--border)]">
          <ReplyAssistant
            email={email}
            onUseDraft={handleUseDraft}
            onClose={() => setShowAIAssistant(false)}
          />
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import {
  ChevronLeft, Star, MoreVertical, Reply, Forward,
  Archive, Trash2, Mail, AlertCircle, Loader2,
  Tag, Flag, MailOpen, Ban, Check
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { sanitizeEmailHtml } from '@/lib/email/html-sanitizer'
import { AttachmentList } from './attachment-list'
import { AISummary } from './ai-summary'
import { SmartReply } from './smart-reply'
import { ActionItemsCard } from './action-items-card'
import type { Email } from '@/types'

interface Attachment {
  id: string
  filename: string
  content_type: string
  size: number
  is_inline: boolean
}

interface EmailDetailMobileProps {
  email: Email
  onBack: () => void
  onRefresh?: () => void
  onStar?: (id: string) => void
  onArchive?: (id: string) => void
  onDelete?: (id: string) => void
}

export function EmailDetailMobile({
  email,
  onBack,
  onRefresh,
  onStar,
  onArchive,
  onDelete
}: EmailDetailMobileProps) {
  const [showActions, setShowActions] = useState(false)
  const [isStarred, setIsStarred] = useState(email.is_starred)
  const [actionLoading, setActionLoading] = useState<string | null>(null)
  const [attachments, setAttachments] = useState<Attachment[]>([])
  const previousId = useRef<string | null>(null)

  // Fetch attachments - defined before useEffect to fix variable access order
  const fetchAttachments = async (emailId: string) => {
    try {
      const res = await fetch(`/api/emails/${emailId}/attachments`)
      const data = await res.json()
      setAttachments(data.attachments || [])
    } catch (error) {
      console.error('Failed to fetch attachments:', error)
    }
  }

  // Reset on email change
  useEffect(() => {
    if (email.id !== previousId.current) {
      setShowActions(false)
      setIsStarred(email.is_starred)
      setActionLoading(null)
      setAttachments([])
      previousId.current = email.id

      // Fetch attachments if email has them
      if (email.attachment_count && email.attachment_count > 0) {
        fetchAttachments(email.id)
      }
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [email.id, email.is_starred, email.attachment_count])

  const toggleStar = async () => {
    const newValue = !isStarred
    setIsStarred(newValue)
    if (onStar) {
      onStar(email.id)
    }
  }

  const handleArchive = () => {
    setShowActions(false)
    setActionLoading('archive')
    if (onArchive) {
      onArchive(email.id)
    }
  }

  const handleDelete = () => {
    setShowActions(false)
    setActionLoading('delete')
    if (onDelete) {
      onDelete(email.id)
    }
  }

  // Format date compact
  const formatDate = (date: string | null) => {
    if (!date) return ''
    const d = new Date(date)
    const now = new Date()
    const isToday = d.toDateString() === now.toDateString()

    if (isToday) {
      return d.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })
    }
    return d.toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' })
  }

  // Check for actual body content
  const hasBody = (email.body_text && email.body_text.trim().length > 10) ||
                  (email.body_html && email.body_html.trim().length > 10)

  return (
    <div className="fixed inset-0 z-50 bg-[var(--card)] flex flex-col">
      {/* COMPACT HEADER - single row */}
      <header className="flex items-center h-12 px-2 border-b border-[var(--border)] bg-[var(--card)] safe-area-top flex-shrink-0">
        {/* Back */}
        <button
          onClick={onBack}
          className="p-2 -ml-1 rounded-full active:bg-[var(--hover)]"
        >
          <ChevronLeft className="w-6 h-6 text-[var(--foreground)]" />
        </button>

        {/* Subject - truncate */}
        <h1 className="flex-1 text-[15px] font-medium text-[var(--foreground)] truncate mx-2">
          {email.subject || '(Không có tiêu đề)'}
        </h1>

        {/* Star */}
        <button
          onClick={toggleStar}
          className="p-2 rounded-full active:bg-[var(--hover)]"
        >
          <Star
            className={cn(
              'w-5 h-5',
              isStarred ? 'fill-yellow-400 text-yellow-400' : 'text-[var(--muted-foreground)]'
            )}
          />
        </button>

        {/* More actions */}
        <button
          onClick={() => setShowActions(true)}
          className="p-2 rounded-full active:bg-[var(--hover)]"
        >
          <MoreVertical className="w-5 h-5 text-[var(--muted)]" />
        </button>
      </header>

      {/* CONTENT - maximum space */}
      <div className="flex-1 overflow-y-auto overscroll-contain">
        {/* Sender info - compact 2 lines max */}
        <div className="flex items-start gap-3 px-4 py-3 border-b border-[var(--border)]">
          {/* Avatar */}
          <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center text-[15px] font-medium text-blue-600 dark:text-blue-400 flex-shrink-0">
            {(email.from_name || email.from_address || 'U')[0].toUpperCase()}
          </div>

          {/* Info */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between">
              <span className="text-[14px] font-medium text-[var(--foreground)] truncate">
                {email.from_name || email.from_address?.split('@')[0] || 'Unknown'}
              </span>
              <span className="text-[12px] text-[var(--muted-foreground)] ml-2 flex-shrink-0">
                {formatDate(email.received_at)}
              </span>
            </div>
            <div className="text-[13px] text-[var(--muted)] truncate">
              {email.from_address}
            </div>
          </div>
        </div>

        {/* AI Summary - Smart Allocation */}
        <div className="px-4 pt-3">
          <AISummary
            emailId={email.id}
            category={email.category || 'personal'}
            priority={email.priority || 3}
            bodyLength={(email.body_text || email.body_html || '').length}
            existingSummary={email.summary}
          />
        </div>

        {/* Smart Reply */}
        <div className="px-4">
          <SmartReply
            emailId={email.id}
            onReply={(content, subject) => {
              const params = new URLSearchParams({
                to: email.from_address || '',
                subject,
                body: content,
              })
              window.location.href = `/compose?${params.toString()}`
            }}
          />
        </div>

        {/* Action Items */}
        <div className="px-4">
          <ActionItemsCard
            emailId={email.id}
            onViewAll={() => window.location.href = '/actions'}
          />
        </div>

        {/* Email body */}
        <div className="px-4 py-3">
          {!hasBody ? (
            <div className="flex flex-col items-center justify-center py-12">
              <Mail className="w-10 h-10 text-[var(--muted-foreground)] mb-2" />
              <span className="text-[13px] text-[var(--muted-foreground)]">Không có nội dung</span>
            </div>
          ) : email.body_html ? (
            <div
              dangerouslySetInnerHTML={{ __html: sanitizeEmailHtml(email.body_html) }}
              className="prose prose-sm dark:prose-invert max-w-none text-[14px] leading-relaxed email-content animate-fadeIn"
            />
          ) : email.body_text ? (
            <pre className="whitespace-pre-wrap font-sans text-[14px] text-[var(--foreground)] leading-relaxed animate-fadeIn">
              {email.body_text}
            </pre>
          ) : null}

          {/* Attachments */}
          {attachments.length > 0 && (
            <AttachmentList attachments={attachments} />
          )}
        </div>
      </div>

      {/* Footer wrapper với spacing từ đáy màn hình */}
      <div className="pb-6 bg-[var(--card)] flex-shrink-0">
        {/* FLOATING ACTION BUTTONS - pill design */}
        <div className="flex items-center justify-center gap-4 px-6 py-3 border-t border-[var(--border)]">
          <button
            onClick={() => window.location.href = `/compose?replyTo=${email.id}`}
            className="flex-1 flex items-center justify-center gap-2 py-3 bg-[var(--primary)] text-[var(--primary-foreground)] rounded-full active:opacity-80 max-w-[160px]"
          >
            <Reply className="w-4 h-4" />
            <span className="text-[14px] font-medium">Trả lời</span>
          </button>
          <button
            onClick={() => window.location.href = `/compose?forward=${email.id}`}
            className="flex-1 flex items-center justify-center gap-2 py-3 bg-[var(--secondary)] text-[var(--foreground)] rounded-full active:bg-[var(--hover)] max-w-[160px]"
          >
            <Forward className="w-4 h-4" />
            <span className="text-[14px] font-medium">Chuyển tiếp</span>
          </button>
        </div>
      </div>

      {/* Actions Sheet */}
      {showActions && (
        <>
          {/* Backdrop */}
          <div
            className="fixed inset-0 bg-black/40 z-50 animate-fadeIn"
            onClick={() => setShowActions(false)}
          />

          {/* Sheet */}
          <div className="fixed bottom-0 left-0 right-0 z-50 bg-[var(--card)] rounded-t-2xl animate-slideUp safe-area-bottom">
            <div className="w-10 h-1 bg-[var(--border)] rounded-full mx-auto mt-3 mb-2" />

            <div className="px-2 pb-4">
              <ActionItem
                icon={Archive}
                label="Lưu trữ"
                onClick={handleArchive}
                loading={actionLoading === 'archive'}
              />
              <ActionItem
                icon={Trash2}
                label="Xóa"
                onClick={handleDelete}
                danger
                loading={actionLoading === 'delete'}
              />
              <ActionItem
                icon={Tag}
                label="Đổi nhãn"
                onClick={() => setShowActions(false)}
              />
              <ActionItem
                icon={Flag}
                label="Đánh dấu quan trọng"
                onClick={() => { toggleStar(); setShowActions(false); }}
              />
              <ActionItem
                icon={MailOpen}
                label="Đánh dấu chưa đọc"
                onClick={() => setShowActions(false)}
              />
              <ActionItem
                icon={Ban}
                label="Chặn người gửi"
                onClick={() => setShowActions(false)}
              />
            </div>
          </div>
        </>
      )}
    </div>
  )
}

function ActionItem({
  icon: Icon,
  label,
  onClick,
  danger,
  loading
}: {
  icon: React.ComponentType<{ className?: string }>
  label: string
  onClick: () => void
  danger?: boolean
  loading?: boolean
}) {
  return (
    <button
      onClick={onClick}
      disabled={loading}
      className={cn(
        'flex items-center gap-4 w-full px-4 py-3.5 rounded-xl active:bg-[var(--hover)] disabled:opacity-50 text-[var(--foreground)]',
        danger && 'text-red-600 dark:text-red-400'
      )}
    >
      {loading ? (
        <Loader2 className="w-5 h-5 animate-spin" />
      ) : (
        <Icon className="w-5 h-5" />
      )}
      <span className="text-[15px]">{label}</span>
    </button>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import { Star, Archive, Trash2, Reply, Forward, MoreHorizontal, X, AlertCircle, Clock, Sparkles, Loader2, MessageSquarePlus, Printer, Download, AlertTriangle } from 'lucide-react'
import { cn, formatDate } from '@/lib/utils'
import { useBehaviorTracker } from '@/hooks/use-behavior-tracker'
import { ReplyAssistant } from '@/components/ai/reply-assistant'
import { AIFeaturesPanel } from '@/components/ai'
import { sanitizeEmailHtml } from '@/lib/email/html-sanitizer'
import { PhishingWarning } from '@/components/email/phishing-warning'
import type { Email } from '@/types'

interface EmailDetailProps {
  email: Email
  onClose: () => void
  onStar: () => void
  onArchive: () => void
  onDelete: () => void
  onReply?: () => void
  onRefresh?: () => void
}

const priorityLabels: Record<number, { label: string; color: string }> = {
  1: { label: 'Rất thấp', color: 'bg-[var(--secondary)] text-[var(--muted-foreground)]' },
  2: { label: 'Thấp', color: 'bg-[var(--secondary)] text-[var(--muted)]' },
  3: { label: 'Bình thường', color: 'bg-[var(--secondary)] text-[var(--foreground)]' },
  4: { label: 'Cao', color: 'bg-amber-100 dark:bg-amber-900/30 text-gray-900 dark:text-white' },
  5: { label: 'Khẩn cấp', color: 'bg-red-100 dark:bg-red-900/30 text-gray-900 dark:text-white' },
}

const categoryLabels: Record<string, string> = {
  work: 'Công việc',
  personal: 'Cá nhân',
  newsletter: 'Bản tin',
  promotion: 'Khuyến mãi',
  transaction: 'Giao dịch',
  social: 'Mạng xã hội',
}

export function EmailDetail({ email, onClose, onStar, onArchive, onDelete, onReply, onRefresh }: EmailDetailProps) {
  const router = useRouter()
  const [classifying, setClassifying] = useState(false)
  const [showReplyAssistant, setShowReplyAssistant] = useState(false)
  const [showMoreMenu, setShowMoreMenu] = useState(false)
  const moreMenuRef = useRef<HTMLDivElement>(null)
  const priorityInfo = priorityLabels[email.priority || 3]

  // Behavior tracking
  const { trackOpen, trackRead, trackArchive, trackDelete, trackStar, trackUnstar, trackReply } = useBehaviorTracker()
  const openTimeRef = useRef<number>(0)
  const trackedEmailRef = useRef<string | null>(null)

  // Track email open when email changes
  useEffect(() => {
    if (email && email.id !== trackedEmailRef.current) {
      // Track read duration for previous email
      if (trackedEmailRef.current && openTimeRef.current > 0) {
        const duration = Math.floor((Date.now() - openTimeRef.current) / 1000)
        trackRead(trackedEmailRef.current, duration)
      }

      // Track open for new email
      trackOpen(email.id)
      trackedEmailRef.current = email.id
      openTimeRef.current = Date.now()
    }
  }, [email?.id, trackOpen, trackRead])

  // Track read duration when component unmounts or closes
  useEffect(() => {
    return () => {
      if (trackedEmailRef.current && openTimeRef.current > 0) {
        const duration = Math.floor((Date.now() - openTimeRef.current) / 1000)
        trackRead(trackedEmailRef.current, duration)
      }
    }
  }, [trackRead])

  // Close more menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (moreMenuRef.current && !moreMenuRef.current.contains(event.target as Node)) {
        setShowMoreMenu(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const handleClassify = async () => {
    setClassifying(true)
    try {
      const res = await fetch('/api/ai/classify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ emailId: email.id })
      })
      if (res.ok) {
        onRefresh?.()
      }
    } catch (err) {
      console.error('Classification failed:', err)
    } finally {
      setClassifying(false)
    }
  }

  const handleStar = () => {
    if (email.is_starred) {
      trackUnstar(email.id)
    } else {
      trackStar(email.id)
    }
    onStar()
  }

  const handleArchive = () => {
    trackArchive(email.id)
    onArchive()
  }

  const handleDelete = () => {
    trackDelete(email.id)
    onDelete()
  }

  const handleReply = () => {
    trackReply(email.id)
    onReply?.()
  }

  const handleUseDraft = (subject: string, body: string) => {
    // Navigate to compose with pre-filled draft
    const params = new URLSearchParams({
      replyTo: email.from_address || '',
      subject,
      body,
    })
    router.push(`/compose?${params.toString()}`)
  }


  return (
    <div className="h-full flex flex-col bg-[var(--card)]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[var(--border)]">
        <div className="flex items-center gap-2">
          <button
            onClick={(e) => {
              e.preventDefault()
              e.stopPropagation()
              onClose()
            }}
            className="p-2 text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--hover)] rounded-lg transition-colors"
          >
            <X className="w-5 h-5" strokeWidth={1.5} />
          </button>
          <h2 className="font-semibold text-[var(--foreground)] truncate">{email.subject || '(Không có tiêu đề)'}</h2>
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={handleStar}
            className="p-2 text-[var(--muted)] hover:text-amber-500 hover:bg-[var(--hover)] rounded-lg transition-colors"
            title={email.is_starred ? 'Bỏ gắn sao' : 'Gắn sao'}
          >
            <Star className={cn('w-5 h-5', email.is_starred && 'fill-amber-500 text-amber-500')} strokeWidth={1.5} />
          </button>
          <button
            onClick={handleArchive}
            className="p-2 text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--hover)] rounded-lg transition-colors"
            title="Lưu trữ"
          >
            <Archive className="w-5 h-5" strokeWidth={1.5} />
          </button>
          <button
            onClick={handleDelete}
            className="p-2 text-[var(--muted)] hover:text-red-500 hover:bg-[var(--hover)] rounded-lg transition-colors"
            title="Xóa"
          >
            <Trash2 className="w-5 h-5" strokeWidth={1.5} />
          </button>
          <button
            onClick={handleClassify}
            disabled={classifying}
            className="p-2 text-[var(--foreground)] hover:bg-[var(--hover)] rounded-lg transition-colors disabled:opacity-50"
            title="Phân tích AI"
          >
            {classifying ? (
              <Loader2 className="w-5 h-5 animate-spin" strokeWidth={1.5} />
            ) : (
              <Sparkles className="w-5 h-5" strokeWidth={1.5} />
            )}
          </button>
          <button
            onClick={() => setShowReplyAssistant(!showReplyAssistant)}
            className={cn(
              'p-2 rounded-lg transition-colors',
              showReplyAssistant
                ? 'bg-[var(--primary)] text-[var(--primary-foreground)]'
                : 'text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--hover)]'
            )}
            title="Trợ lý phản hồi AI"
          >
            <MessageSquarePlus className="w-5 h-5" strokeWidth={1.5} />
          </button>
          {/* More Menu Dropdown */}
          <div className="relative" ref={moreMenuRef}>
            <button
              onClick={() => setShowMoreMenu(!showMoreMenu)}
              className="p-2 text-[var(--muted)] hover:text-[var(--foreground)] hover:bg-[var(--hover)] rounded-lg transition-colors"
            >
              <MoreHorizontal className="w-5 h-5" strokeWidth={1.5} />
            </button>

            {showMoreMenu && (
              <div className="absolute right-0 top-full mt-1 w-48 bg-[var(--card)] rounded-lg border border-[var(--border)] shadow-lg z-50 py-1">
                {/* Print */}
                <button
                  type="button"
                  onClick={() => {
                    setShowMoreMenu(false)
                    window.print()
                  }}
                  className="w-full flex items-center gap-3 px-3 py-2 text-left text-[13px] text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors"
                >
                  <Printer className="w-4 h-4" strokeWidth={1.5} />
                  In email
                </button>

                {/* Download */}
                <button
                  type="button"
                  onClick={() => {
                    setShowMoreMenu(false)
                    const content = `From: ${email.from_name} <${email.from_address}>\nTo: ${email.to_addresses?.join(', ') || ''}\nDate: ${email.received_at}\nSubject: ${email.subject}\n\n${email.body_text || ''}`
                    const blob = new Blob([content], { type: 'text/plain' })
                    const url = URL.createObjectURL(blob)
                    const a = document.createElement('a')
                    a.href = url
                    a.download = `${email.subject || 'email'}.eml`
                    a.click()
                    URL.revokeObjectURL(url)
                  }}
                  className="w-full flex items-center gap-3 px-3 py-2 text-left text-[13px] text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors"
                >
                  <Download className="w-4 h-4" strokeWidth={1.5} />
                  Tải xuống
                </button>

                <div className="my-1 border-t border-[var(--border)]" />

                {/* Report Phishing */}
                <button
                  type="button"
                  onClick={async () => {
                    setShowMoreMenu(false)
                    try {
                      await fetch('/api/ai/feedback', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                          emailId: email.id,
                          feedbackType: 'report_phishing',
                          context: { from: email.from_address, subject: email.subject }
                        })
                      })
                      alert('Đã báo cáo email lừa đảo. Cảm ơn bạn!')
                    } catch {
                      alert('Không thể báo cáo. Vui lòng thử lại.')
                    }
                  }}
                  className="w-full flex items-center gap-3 px-3 py-2 text-left text-[13px] text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                >
                  <AlertTriangle className="w-4 h-4" strokeWidth={1.5} />
                  Báo cáo lừa đảo
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Email Content */}
      <div className="flex-1 overflow-auto">
        {/* Sender Info */}
        <div className="p-4 border-b border-[var(--border)]">
          <div className="flex items-start gap-3">
            <div className="w-10 h-10 bg-[var(--primary)] rounded-full flex items-center justify-center text-[var(--primary-foreground)] font-medium flex-shrink-0">
              {(email.from_name || email.from_address || '?')[0].toUpperCase()}
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="font-medium text-[var(--foreground)]">{email.from_name || email.from_address}</span>
                <span className="text-[13px] text-[var(--muted)]">&lt;{email.from_address}&gt;</span>
              </div>
              <p className="text-[13px] text-[var(--muted)]">
                Đến: tôi • {email.received_at ? formatDate(email.received_at) : ''}
              </p>
            </div>
          </div>
        </div>

        {/* Phishing Warning */}
        {email.phishing_score != null && email.phishing_score > 0 && email.phishing_risk && email.phishing_risk !== 'safe' && (
          <div className="p-4 pb-0">
            <PhishingWarning
              score={email.phishing_score ?? 0}
              risk={email.phishing_risk as 'safe' | 'low' | 'medium' | 'high' | 'critical'}
              reasons={(email.phishing_reasons as Array<{type: string; pattern: string; severity: number; description: string}>) || []}
              isPhishing={(email.phishing_score ?? 0) >= 70}
              onMarkSafe={async () => {
                // Mark email as reviewed (safe)
                try {
                  await fetch(`/api/emails/${email.id}/phishing-review`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ safe: true })
                  })
                  onRefresh?.()
                } catch (err) {
                  console.error('Failed to mark as safe:', err)
                }
              }}
            />
          </div>
        )}

        {/* AI Summary & Meta */}
        {(email.summary || email.needs_reply || email.detected_deadline) && (
          <div className="p-4 bg-[var(--background)] border-b border-[var(--border)]">
            <div className="flex items-center gap-2 mb-2">
              <span className="text-[11px] font-medium text-[var(--muted-foreground)] uppercase tracking-wide">AI Phân tích</span>
            </div>
            {email.summary && (
              <p className="text-[14px] text-[var(--foreground)] mb-3">{email.summary}</p>
            )}
            <div className="flex flex-wrap gap-2">
              <span className={cn('px-2 py-1 text-[12px] rounded-full', priorityInfo.color)}>
                {priorityInfo.label}
              </span>
              {email.category && (
                <span className="px-2 py-1 text-[12px] rounded-full bg-[var(--secondary)] text-[var(--muted)]">
                  {categoryLabels[email.category] || email.category}
                </span>
              )}
              {email.needs_reply && (
                <span className="px-2 py-1 text-[12px] rounded-full bg-amber-100 dark:bg-amber-900/30 text-gray-900 dark:text-white flex items-center gap-1">
                  <AlertCircle className="w-3 h-3" strokeWidth={1.5} />
                  Cần trả lời
                </span>
              )}
              {email.detected_deadline && (
                <span className="px-2 py-1 text-[12px] rounded-full bg-red-100 dark:bg-red-900/30 text-gray-900 dark:text-white flex items-center gap-1">
                  <Clock className="w-3 h-3" strokeWidth={1.5} />
                  Deadline: {new Date(email.detected_deadline).toLocaleDateString('vi-VN')}
                </span>
              )}
            </div>
          </div>
        )}

        {/* AI Features Panel - Unified with fallback */}
        <div className="p-4">
          <AIFeaturesPanel emailId={email.id} />
        </div>

        {/* Email Body */}
        <div className="p-4">
          <div className="email-content prose max-w-none text-[var(--foreground)]">
            {email.body_html ? (
              <div dangerouslySetInnerHTML={{ __html: sanitizeEmailHtml(email.body_html, { allowImages: true }) }} />
            ) : (
              <pre className="whitespace-pre-wrap font-sans text-[var(--foreground)]">
                {email.body_text || email.snippet || '(Không có nội dung)'}
              </pre>
            )}
          </div>
        </div>

        {/* Reply Assistant */}
        {showReplyAssistant && (
          <div className="p-4 border-t border-[var(--border)]">
            <ReplyAssistant
              email={email}
              onUseDraft={handleUseDraft}
              onClose={() => setShowReplyAssistant(false)}
            />
          </div>
        )}
      </div>

      {/* Actions Footer */}
      <div className="p-4 border-t border-[var(--border)] bg-[var(--background)]">
        <div className="flex items-center gap-2">
          <button
            onClick={handleReply}
            className="flex items-center gap-2 px-4 py-2 bg-[var(--primary)] text-[var(--primary-foreground)] rounded-lg font-medium hover:opacity-90 transition-colors"
          >
            <Reply className="w-4 h-4" strokeWidth={1.5} />
            Trả lời
          </button>
          <button className="flex items-center gap-2 px-4 py-2 border border-[var(--border)] rounded-lg text-[var(--foreground)] hover:bg-[var(--hover)] transition-colors">
            <Forward className="w-4 h-4" strokeWidth={1.5} />
            Chuyển tiếp
          </button>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef, useCallback, useMemo, MouseEvent, TouchEvent } from 'react'
import { Star, Zap, Inbox, Newspaper, ChevronDown, ChevronRight, Loader2, Paperclip, Check, X, Archive, Trash2, Mail, MailOpen } from 'lucide-react'
import { cn } from '@/lib/utils'
import { useSelection } from '@/contexts/email-selection-context'
import { ContextMenu } from './context-menu'
import { CategoryPicker } from './category-picker'
import type { Email } from '@/types'

interface Props {
  emails: Email[]
  selectedId: string | null
  onSelect: (id: string) => void
  onStar?: (id: string) => void
  onCategoryClick?: (category: string) => void
  compact?: boolean
  smartSort?: boolean
  hasMore?: boolean
  loadingMore?: boolean
  onLoadMore?: () => void
  onBulkAction?: (action: string, emailIds: string[], data?: Record<string, unknown>) => void
  selectionEnabled?: boolean
}

interface EmailSection {
  id: string
  title: string
  icon: React.ComponentType<{ className?: string; strokeWidth?: number }>
  emails: Email[]
  defaultCollapsed?: boolean
}

// Long press duration in milliseconds
const LONG_PRESS_DURATION = 500

export function EmailListCompact({
  emails,
  selectedId,
  onSelect,
  onStar,
  onCategoryClick,
  compact = false,
  smartSort = false,
  hasMore = false,
  loadingMore = false,
  onLoadMore,
  onBulkAction,
  selectionEnabled = true
}: Props) {
  const [collapsedSections, setCollapsedSections] = useState<Record<string, boolean>>({
    readLater: true // Collapsed by default
  })
  const loadMoreRef = useRef<HTMLDivElement>(null)

  // Selection state - always call hook to follow rules of hooks
  const selectionHook = useSelection()
  const { selectedIds, isSelecting, toggleSelect, isSelected, clearSelection, selectAll, setIsSelecting } = selectionEnabled
    ? selectionHook
    : {
        selectedIds: new Set<string>(),
        isSelecting: false,
        toggleSelect: () => {},
        isSelected: () => false,
        clearSelection: () => {},
        selectAll: () => {},
        setIsSelecting: () => {}
      }

  // Context menu state
  const [contextMenu, setContextMenu] = useState<{
    x: number
    y: number
    email: Email
  } | null>(null)
  const [showCategoryPicker, setShowCategoryPicker] = useState(false)
  const [lastClickedId, setLastClickedId] = useState<string | null>(null)

  // Long press state
  const longPressTimer = useRef<NodeJS.Timeout | null>(null)
  const longPressTriggered = useRef(false)
  const touchStartPos = useRef<{ x: number; y: number } | null>(null)

  const emailIds = emails.map(e => e.id)

  // Cleanup long press timer
  const clearLongPressTimer = useCallback(() => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current)
      longPressTimer.current = null
    }
  }, [])

  // Handle touch start - begin long press detection
  const handleTouchStart = useCallback((e: TouchEvent, email: Email) => {
    longPressTriggered.current = false
    touchStartPos.current = {
      x: e.touches[0].clientX,
      y: e.touches[0].clientY
    }

    longPressTimer.current = setTimeout(() => {
      longPressTriggered.current = true

      // Vibrate feedback if available
      if (navigator.vibrate) {
        navigator.vibrate(50)
      }

      // Enter selection mode and select this email
      if (setIsSelecting) {
        setIsSelecting(true)
      }
      if (!isSelected(email.id)) {
        toggleSelect(email.id)
      }
    }, LONG_PRESS_DURATION)
  }, [isSelected, toggleSelect, setIsSelecting])

  // Handle touch move - cancel long press if moved too much
  const handleTouchMove = useCallback((e: TouchEvent) => {
    if (!touchStartPos.current) return

    const moveThreshold = 10 // pixels
    const deltaX = Math.abs(e.touches[0].clientX - touchStartPos.current.x)
    const deltaY = Math.abs(e.touches[0].clientY - touchStartPos.current.y)

    if (deltaX > moveThreshold || deltaY > moveThreshold) {
      clearLongPressTimer()
    }
  }, [clearLongPressTimer])

  // Handle touch end - cleanup
  const handleTouchEnd = useCallback(() => {
    clearLongPressTimer()
    touchStartPos.current = null
  }, [clearLongPressTimer])

  // Handle tap/click - only fires if not long press
  const handleTap = useCallback((email: Email, e?: MouseEvent) => {
    // Prevent click from firing after long press
    if (longPressTriggered.current) {
      longPressTriggered.current = false
      e?.preventDefault()
      e?.stopPropagation()
      return
    }

    if (isSelecting) {
      toggleSelect(email.id)
    } else {
      onSelect(email.id)
    }
  }, [isSelecting, toggleSelect, onSelect])

  // Exit selection mode
  const exitSelectionMode = useCallback(() => {
    clearSelection()
    if (setIsSelecting) {
      setIsSelecting(false)
    }
  }, [clearSelection, setIsSelecting])

  // Infinite scroll: observe the load more sentinel with PREFETCH
  // rootMargin: '400px' triggers load 400px before reaching the end
  useEffect(() => {
    if (!onLoadMore || !hasMore) return

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore && !loadingMore) {
          onLoadMore()
        }
      },
      {
        threshold: 0,
        rootMargin: '400px', // Start loading 400px before reaching end (approx 5-6 emails)
      }
    )

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current)
    }

    return () => observer.disconnect()
  }, [hasMore, loadingMore, onLoadMore])

  // Cleanup on unmount
  useEffect(() => {
    return () => clearLongPressTimer()
  }, [clearLongPressTimer])

  // Memoized helper functions
  const formatTime = useCallback((date: string | null) => {
    if (!date) return ''
    const d = new Date(date)
    const now = new Date()
    const diffDays = Math.floor((now.getTime() - d.getTime()) / (1000 * 60 * 60 * 24))

    if (diffDays === 0) {
      return d.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })
    } else if (diffDays === 1) {
      return 'Hôm qua'
    } else if (diffDays < 7) {
      return `${diffDays} ngày`
    } else {
      return d.toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' })
    }
  }, [])

  // Static category styles - memoized
  // Use CSS variables for text color to ensure correct theme contrast
  const categoryStyles = useMemo(() => ({
    work: {
      bg: 'bg-blue-100 dark:bg-blue-900/40',
      text: 'text-[var(--foreground)] font-semibold',
      hoverBg: 'hover:bg-blue-200 dark:hover:bg-blue-900/60'
    },
    personal: {
      bg: 'bg-purple-100 dark:bg-purple-900/40',
      text: 'text-[var(--foreground)] font-semibold',
      hoverBg: 'hover:bg-purple-200 dark:hover:bg-purple-900/60'
    },
    transaction: {
      bg: 'bg-emerald-100 dark:bg-emerald-900/40',
      text: 'text-[var(--foreground)] font-semibold',
      hoverBg: 'hover:bg-emerald-200 dark:hover:bg-emerald-900/60'
    },
    newsletter: {
      bg: 'bg-gray-100 dark:bg-gray-800/60',
      text: 'text-[var(--foreground)] font-semibold',
      hoverBg: 'hover:bg-gray-200 dark:hover:bg-gray-800/80'
    },
    promotion: {
      bg: 'bg-orange-100 dark:bg-orange-900/40',
      text: 'text-[var(--foreground)] font-semibold',
      hoverBg: 'hover:bg-orange-200 dark:hover:bg-orange-900/60'
    },
    social: {
      bg: 'bg-cyan-100 dark:bg-cyan-900/40',
      text: 'text-[var(--foreground)] font-semibold',
      hoverBg: 'hover:bg-cyan-200 dark:hover:bg-cyan-900/60'
    },
    spam: {
      bg: 'bg-red-100 dark:bg-red-900/40',
      text: 'text-[var(--foreground)] font-semibold',
      hoverBg: 'hover:bg-red-200 dark:hover:bg-red-900/60'
    },
    uncategorized: {
      bg: 'bg-gray-100 dark:bg-gray-800/40',
      text: 'text-[var(--foreground)] font-semibold',
      hoverBg: 'hover:bg-gray-200 dark:hover:bg-gray-800/60'
    },
  }), [])

  const getCategoryStyle = useCallback((category: string | null) => {
    if (!category) return null
    return categoryStyles[category as keyof typeof categoryStyles] || categoryStyles.newsletter
  }, [categoryStyles])

  // Static category labels - memoized
  const categoryLabels = useMemo(() => ({
    work: 'Công việc',
    personal: 'Cá nhân',
    transaction: 'Giao dịch',
    newsletter: 'Newsletter',
    promotion: 'Khuyến mãi',
    social: 'Mạng XH',
    spam: 'Spam',
    uncategorized: 'Chưa phân loại',
  }), [])

  const getCategoryLabel = useCallback((category: string | null) => {
    if (!category) return ''
    return categoryLabels[category as keyof typeof categoryLabels] || category
  }, [categoryLabels])

  // Group emails into sections for smart sort - memoized
  const sections = useMemo(() => {
    if (!smartSort) return []

    const needsAction: Email[] = []
    const primary: Email[] = []
    const readLater: Email[] = []

    emails.forEach(email => {
      if (!email.is_read && (
        (email.priority || 0) >= 4 ||
        email.needs_reply ||
        email.detected_deadline
      )) {
        needsAction.push(email)
      } else if (email.category === 'newsletter' || email.category === 'promotion') {
        readLater.push(email)
      } else {
        primary.push(email)
      }
    })

    return [
      { id: 'needsAction', title: 'Cần xử lý', icon: Zap, emails: needsAction },
      { id: 'primary', title: 'Hộp thư chính', icon: Inbox, emails: primary },
      { id: 'readLater', title: 'Đọc sau', icon: Newspaper, emails: readLater, defaultCollapsed: true }
    ].filter(section => section.emails.length > 0)
  }, [emails, smartSort])

  const toggleSection = useCallback((sectionId: string) => {
    setCollapsedSections(prev => ({
      ...prev,
      [sectionId]: !prev[sectionId]
    }))
  }, [])

  // Handle checkbox click (desktop) - memoized
  const handleCheckboxClick = useCallback((e: MouseEvent, email: Email) => {
    e.stopPropagation()

    if (e.shiftKey && lastClickedId) {
      const fromIndex = emailIds.indexOf(lastClickedId)
      const toIndex = emailIds.indexOf(email.id)
      if (fromIndex !== -1 && toIndex !== -1) {
        const start = Math.min(fromIndex, toIndex)
        const end = Math.max(fromIndex, toIndex)
        const rangeIds = emailIds.slice(start, end + 1)
        rangeIds.forEach(id => {
          if (!isSelected(id)) toggleSelect(id)
        })
      }
    } else {
      toggleSelect(email.id)
    }

    setLastClickedId(email.id)
  }, [lastClickedId, emailIds, isSelected, toggleSelect])

  // Handle right-click context menu (desktop only) - memoized
  // On mobile, we use long press instead
  const handleContextMenu = useCallback((e: MouseEvent, email: Email) => {
    e.preventDefault()
    e.stopPropagation()

    // Skip on mobile - long press handles selection
    if ('ontouchstart' in window) {
      return
    }

    if (!isSelected(email.id)) {
      clearSelection()
      toggleSelect(email.id)
    }

    setContextMenu({
      x: e.clientX,
      y: e.clientY,
      email
    })
  }, [isSelected, clearSelection, toggleSelect])

  // Handle context menu action
  const handleAction = useCallback((action: string, data?: Record<string, unknown>) => {
    const ids = Array.from(selectedIds)

    if (action === 'change-category') {
      setShowCategoryPicker(true)
      return
    }

    onBulkAction?.(action, ids, data)

    if (['archive', 'delete', 'mark-spam', 'block-sender'].includes(action)) {
      clearSelection()
      if (setIsSelecting) setIsSelecting(false)
    }

    setContextMenu(null)
  }, [selectedIds, onBulkAction, clearSelection, setIsSelecting])

  // Handle category change from picker - memoized
  const handleCategoryChange = useCallback((category: string) => {
    const ids = Array.from(selectedIds)
    onBulkAction?.('change-category', ids, { category })
    setShowCategoryPicker(false)
    clearSelection()
    if (setIsSelecting) setIsSelecting(false)
  }, [selectedIds, onBulkAction, clearSelection, setIsSelecting])

  // Mobile Selection Toolbar Component
  const renderMobileSelectionToolbar = () => {
    if (!isSelecting || selectedIds.size === 0) return null

    return (
      <div className="fixed bottom-0 left-0 right-0 z-50 md:hidden bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-700 shadow-lg safe-area-bottom">
        <div className="flex items-center justify-between px-4 py-3">
          {/* Left: Cancel + Count */}
          <div className="flex items-center gap-3">
            <button
              onClick={exitSelectionMode}
              className="p-2 -m-2 text-gray-600 dark:text-gray-400"
            >
              <X className="w-5 h-5" />
            </button>
            <span className="text-sm font-medium text-gray-900 dark:text-white">
              {selectedIds.size} đã chọn
            </span>
          </div>

          {/* Right: Actions */}
          <div className="flex items-center gap-1">
            <button
              onClick={() => handleAction('mark-read')}
              className="p-3 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"
              title="Đánh dấu đã đọc"
            >
              <MailOpen className="w-5 h-5" />
            </button>
            <button
              onClick={() => handleAction('mark-unread')}
              className="p-3 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"
              title="Đánh dấu chưa đọc"
            >
              <Mail className="w-5 h-5" />
            </button>
            <button
              onClick={() => handleAction('archive')}
              className="p-3 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"
              title="Lưu trữ"
            >
              <Archive className="w-5 h-5" />
            </button>
            <button
              onClick={() => handleAction('delete')}
              className="p-3 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full"
              title="Xóa"
            >
              <Trash2 className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Select All bar */}
        <div className="flex items-center justify-between px-4 py-2 bg-gray-50 dark:bg-gray-800/50 border-t border-gray-100 dark:border-gray-800">
          <button
            onClick={() => selectAll(emailIds)}
            className="text-sm text-blue-700 dark:text-blue-400 font-semibold"
          >
            Chọn tất cả ({emails.length})
          </button>
          <button
            onClick={clearSelection}
            className="text-sm text-gray-700 dark:text-gray-400 font-medium"
          >
            Bỏ chọn
          </button>
        </div>
      </div>
    )
  }

  const renderEmailItem = (email: Email) => {
    const categoryStyle = email.category ? getCategoryStyle(email.category) : null
    const emailIsSelected = isSelected(email.id)

    return (
      <div
        key={email.id}
        onClick={(e) => handleTap(email, e)}
        onContextMenu={(e) => handleContextMenu(e, email)}
        onTouchStart={(e) => handleTouchStart(e, email)}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onTouchCancel={handleTouchEnd}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            handleTap(email, e as unknown as MouseEvent)
          }
        }}
        style={{
          touchAction: 'manipulation',
          WebkitTouchCallout: 'none',
          WebkitUserSelect: 'none',
        }}
        className={cn(
          'w-full transition-colors cursor-pointer group select-none',
          compact ? 'px-3 py-2.5' : 'px-4 py-3',
          selectedId === email.id && !isSelecting
            ? 'bg-[var(--secondary)]'
            : emailIsSelected
              ? 'bg-blue-100 text-gray-900 dark:bg-blue-600/40 dark:text-white'
              : 'hover:bg-[var(--hover)] active:bg-[var(--secondary)]',
          !email.is_read && !emailIsSelected && 'bg-blue-50/30 dark:bg-blue-900/10'
        )}
      >
        <div className="flex items-start gap-3">
          {/* Mobile: Checkbox when selecting, Avatar when not */}
          <div className="md:hidden flex-shrink-0">
            {isSelecting ? (
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  toggleSelect(email.id)
                }}
                className={cn(
                  'w-10 h-10 rounded-full flex items-center justify-center transition-all',
                  emailIsSelected
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-100 dark:bg-gray-800 border-2 border-gray-300 dark:border-gray-600'
                )}
              >
                {emailIsSelected && <Check className="w-5 h-5" strokeWidth={2.5} />}
              </button>
            ) : (
              <div className={cn(
                'w-10 h-10 rounded-full flex items-center justify-center text-[14px] font-medium',
                !email.is_read
                  ? 'bg-blue-100 dark:bg-blue-900/30 text-gray-900 dark:text-white'
                  : 'bg-[var(--secondary)] text-[var(--muted)]'
              )}>
                {(email.from_name || email.from_address || 'U')[0].toUpperCase()}
              </div>
            )}
          </div>

          {/* Desktop: Checkbox */}
          <button
            onClick={(e) => handleCheckboxClick(e, email)}
            className={cn(
              'w-5 h-5 rounded border-2 flex items-center justify-center flex-shrink-0 mt-0.5 transition-all hidden md:flex',
              emailIsSelected
                ? 'bg-[var(--primary)] border-[var(--primary)] text-white'
                : 'border-gray-500 dark:border-gray-400 hover:border-[var(--primary)]',
              !isSelecting && !emailIsSelected && 'opacity-0 group-hover:opacity-100'
            )}
          >
            {emailIsSelected && <Check className="w-3 h-3" strokeWidth={2.5} />}
          </button>

          {/* Star - desktop only */}
          <button
            onClick={(e) => {
              e.stopPropagation()
              onStar?.(email.id)
            }}
            className={cn(
              'mt-0.5 flex-shrink-0 hidden md:block',
              email.is_starred ? 'text-amber-500' : 'text-gray-500 dark:text-gray-400 hover:text-amber-400'
            )}
          >
            <Star
              className="w-4 h-4"
              strokeWidth={1.5}
              fill={email.is_starred ? 'currentColor' : 'none'}
            />
          </button>

          {/* Content */}
          <div className="flex-1 min-w-0">
            {/* Row 1: Sender + Time */}
            <div className="flex items-center justify-between gap-2">
              <span className={cn(
                'text-[14px] truncate',
                email.is_read ? 'text-[var(--muted)] font-medium' : 'text-[var(--foreground)] font-semibold'
              )}>
                {email.from_name || email.from_address?.split('@')[0]}
              </span>
              <span className="text-[12px] text-[var(--muted-foreground)] flex-shrink-0">
                {formatTime(email.received_at)}
              </span>
            </div>

            {/* Row 2: Priority + Subject + Attachment */}
            <div className="flex items-center gap-1.5 mt-0.5">
              {(email.priority || 0) >= 4 && (
                <span className="w-1.5 h-1.5 rounded-full bg-red-600 flex-shrink-0" />
              )}
              <span className={cn(
                'text-[14px] truncate',
                email.is_read ? 'text-[var(--muted)]' : 'text-[var(--foreground)]'
              )}>
                {email.subject || '(Không có tiêu đề)'}
              </span>
              {(email.attachment_count || 0) > 0 && (
                <span className="flex items-center gap-0.5 text-[var(--muted-foreground)] flex-shrink-0">
                  <Paperclip className="w-3.5 h-3.5" strokeWidth={1.5} />
                  {(email.attachment_count || 0) > 1 && (
                    <span className="text-[11px]">{email.attachment_count}</span>
                  )}
                </span>
              )}
            </div>

            {/* Row 3: Preview */}
            <p className="text-[13px] text-[var(--muted-foreground)] truncate mt-0.5">
              {(email.body_text || email.snippet || '')?.replace(/\\n/g, ' ').slice(0, 80)}
            </p>
          </div>

          {/* Unread indicator - mobile (when not selecting) */}
          {!email.is_read && !isSelecting && (
            <div className="w-2 h-2 bg-blue-500 rounded-full flex-shrink-0 mt-2 md:hidden" />
          )}

          {/* Category Tag - desktop only */}
          {email.category && categoryStyle && (
            <button
              onClick={(e) => {
                e.stopPropagation()
                onCategoryClick?.(email.category!)
              }}
              className={cn(
                'px-2 py-0.5 rounded text-[11px] font-medium flex-shrink-0 transition-colors hidden md:block',
                categoryStyle.bg,
                categoryStyle.text,
                categoryStyle.hoverBg
              )}
            >
              {getCategoryLabel(email.category)}
            </button>
          )}
        </div>
      </div>
    )
  }

  if (emails.length === 0) {
    return (
      <div className="flex items-center justify-center h-32 text-[14px] text-[var(--muted-foreground)]">
        Không có email
      </div>
    )
  }

  const renderLoadMoreIndicator = () => (
    <div ref={loadMoreRef} className="py-4 flex justify-center">
      {loadingMore ? (
        <div className="flex items-center gap-2 text-[var(--muted-foreground)]">
          <Loader2 className="w-4 h-4 animate-spin" strokeWidth={1.5} />
          <span className="text-[13px]">Đang tải...</span>
        </div>
      ) : hasMore ? (
        <button onClick={onLoadMore} className="text-[13px] text-[var(--muted)] hover:text-[var(--foreground)]">
          Tải thêm
        </button>
      ) : emails.length > 0 ? (
        <span className="text-[12px] text-[var(--muted-foreground)]">Đã hiển thị tất cả</span>
      ) : null}
    </div>
  )

  const ContextMenuPortal = contextMenu && (
    <ContextMenu
      x={contextMenu.x}
      y={contextMenu.y}
      onClose={() => setContextMenu(null)}
      selectedCount={selectedIds.size}
      isSingleSelect={selectedIds.size === 1}
      selectedEmail={{
        id: contextMenu.email.id,
        is_read: contextMenu.email.is_read,
        is_starred: contextMenu.email.is_starred,
        from_address: contextMenu.email.from_address
      }}
      onAction={handleAction}
    />
  )

  const CategoryPickerPortal = showCategoryPicker && (
    <CategoryPicker
      onSelect={handleCategoryChange}
      onClose={() => setShowCategoryPicker(false)}
      currentCategory={contextMenu?.email?.category || undefined}
    />
  )

  if (smartSort) {
    // sections is already memoized above
    return (
      <>
        <div className={cn(isSelecting && 'pb-32 md:pb-0')}>
          {sections.map((section) => {
            const Icon = section.icon
            const isCollapsed = collapsedSections[section.id] ?? section.defaultCollapsed

            return (
              <div key={section.id}>
                <button
                  onClick={() => toggleSection(section.id)}
                  className="w-full flex items-center gap-2 px-4 py-2 bg-[var(--secondary)] border-b border-[var(--border)] hover:bg-[var(--hover)]"
                >
                  {isCollapsed ? (
                    <ChevronRight className="w-4 h-4 text-[var(--muted-foreground)]" strokeWidth={1.5} />
                  ) : (
                    <ChevronDown className="w-4 h-4 text-[var(--muted-foreground)]" strokeWidth={1.5} />
                  )}
                  <Icon
                    className={cn(
                      'w-4 h-4',
                      section.id === 'needsAction' ? 'text-red-600 dark:text-red-400' : 'text-[var(--muted)]'
                    )}
                    strokeWidth={1.5}
                  />
                  <span className={cn(
                    'text-[13px] font-medium',
                    section.id === 'needsAction' ? 'text-red-600 dark:text-red-400' : 'text-[var(--foreground)]'
                  )}>
                    {section.title}
                  </span>
                  <span className="text-[12px] text-[var(--muted-foreground)]">
                    ({section.emails.length})
                  </span>
                </button>

                {!isCollapsed && (
                  <div className="divide-y divide-[var(--border)]">
                    {section.emails.map(renderEmailItem)}
                  </div>
                )}
              </div>
            )
          })}
          {onLoadMore && renderLoadMoreIndicator()}
        </div>
        {renderMobileSelectionToolbar()}
        {ContextMenuPortal}
        {CategoryPickerPortal}
      </>
    )
  }

  return (
    <>
      <div className={cn(isSelecting && 'pb-32 md:pb-0')}>
        <div className="divide-y divide-[var(--border)]">
          {emails.map(renderEmailItem)}
        </div>
        {onLoadMore && renderLoadMoreIndicator()}
      </div>
      {renderMobileSelectionToolbar()}
      {ContextMenuPortal}
      {CategoryPickerPortal}
    </>
  )
}

'use client'

import { Star, Paperclip } from 'lucide-react'
import { cn, formatDate, truncate } from '@/lib/utils'
import { Badge } from '@/components/ui/badge'

interface EmailListItemProps {
  id: string
  fromName: string
  fromAddress: string
  subject: string
  snippet: string
  receivedAt: string
  isRead: boolean
  isStarred: boolean
  priority?: number
  category?: string
  hasAttachments?: boolean
  onClick?: () => void
  onStar?: () => void
}

const priorityColors: Record<number, string> = {
  1: 'bg-red-600',
  2: 'bg-amber-600',
  3: 'bg-[var(--foreground)]',
  4: 'bg-[var(--muted)]',
  5: 'bg-[var(--border)]',
}

const categoryLabels: Record<string, { label: string; variant: 'default' | 'secondary' | 'success' | 'warning' | 'urgent' | 'info' }> = {
  work: { label: 'Công việc', variant: 'info' },
  personal: { label: 'Cá nhân', variant: 'success' },
  newsletter: { label: 'Bản tin', variant: 'default' },
  promotion: { label: 'Khuyến mãi', variant: 'warning' },
  transaction: { label: 'Giao dịch', variant: 'urgent' },
  social: { label: 'Mạng xã hội', variant: 'secondary' },
}

export function EmailListItem({
  id,
  fromName,
  fromAddress,
  subject,
  snippet,
  receivedAt,
  isRead,
  isStarred,
  priority = 3,
  category,
  hasAttachments,
  onClick,
  onStar,
}: EmailListItemProps) {
  const categoryInfo = category ? categoryLabels[category] : null

  return (
    <div
      onClick={onClick}
      className={cn(
        'flex items-start gap-3 p-4 border-b border-[var(--border)] cursor-pointer transition-colors',
        isRead ? 'bg-[var(--card)]' : 'bg-[var(--secondary)]',
        'hover:bg-[var(--hover)]'
      )}
    >
      {/* Priority Indicator */}
      <div className={cn('w-1 h-12 rounded-full flex-shrink-0', priorityColors[priority])} />

      {/* Star */}
      <button
        onClick={(e) => {
          e.stopPropagation()
          onStar?.()
        }}
        className="flex-shrink-0 mt-0.5"
      >
        <Star
          className={cn(
            'w-5 h-5 transition-colors',
            isStarred ? 'fill-amber-500 text-amber-500' : 'text-[var(--muted)] hover:text-amber-500'
          )}
          strokeWidth={1.5}
        />
      </button>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 mb-1">
          <span className={cn('text-[14px] truncate', isRead ? 'text-[var(--muted-foreground)]' : 'font-semibold text-[var(--foreground)]')}>
            {fromName || fromAddress}
          </span>
          {categoryInfo && (
            <Badge variant={categoryInfo.variant} size="sm">
              {categoryInfo.label}
            </Badge>
          )}
          {hasAttachments && <Paperclip className="w-3.5 h-3.5 text-[var(--muted)] flex-shrink-0" strokeWidth={1.5} />}
        </div>
        <p className={cn('text-[14px] truncate mb-1', isRead ? 'text-[var(--muted-foreground)]' : 'font-medium text-[var(--foreground)]')}>
          {subject || '(Không có tiêu đề)'}
        </p>
        <p className="text-[13px] text-[var(--muted)] truncate">{truncate(snippet, 80)}</p>
      </div>

      {/* Time */}
      <span className="text-[12px] text-[var(--muted)] flex-shrink-0 mt-0.5">
        {formatDate(receivedAt)}
      </span>
    </div>
  )
}

'use client'

import { useRef, memo, useCallback } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { Star, Zap } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Email } from '@/types'

interface Props {
  emails: Email[]
  selectedId: string | null
  onSelect: (id: string) => void
  onStar?: (id: string, currentStarred: boolean) => void
  onCategoryClick?: (category: string) => void
  onLoadMore?: () => void
  hasMore?: boolean
  isFetchingMore?: boolean
}

// Memoized email row component for performance
const EmailRow = memo(function EmailRow({
  email,
  isSelected,
  onSelect,
  onStar,
  onCategoryClick,
}: {
  email: Email
  isSelected: boolean
  onSelect: () => void
  onStar?: (starred: boolean) => void
  onCategoryClick?: (category: string) => void
}) {
  const formatTime = (date: string | null) => {
    if (!date) return ''
    const d = new Date(date)
    const now = new Date()
    const diffDays = Math.floor((now.getTime() - d.getTime()) / (1000 * 60 * 60 * 24))

    if (diffDays === 0) {
      return d.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })
    } else if (diffDays === 1) {
      return 'Hôm qua'
    } else if (diffDays < 7) {
      return `${diffDays} ngày`
    }
    return d.toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' })
  }

  const getCategoryStyle = (category: string | null) => {
    if (!category) return null
    const styles: Record<string, { bg: string; text: string }> = {
      work: { bg: 'bg-blue-100 dark:bg-blue-500/20', text: 'text-[var(--foreground)] font-semibold' },
      personal: { bg: 'bg-purple-100 dark:bg-purple-500/20', text: 'text-[var(--foreground)] font-semibold' },
      transaction: { bg: 'bg-emerald-100 dark:bg-emerald-500/20', text: 'text-[var(--foreground)] font-semibold' },
      newsletter: { bg: 'bg-gray-100 dark:bg-gray-800/60', text: 'text-[var(--foreground)] font-semibold' },
      uncategorized: { bg: 'bg-gray-100 dark:bg-gray-800/40', text: 'text-[var(--foreground)] font-semibold' },
      promotion: { bg: 'bg-amber-100 dark:bg-amber-500/20', text: 'text-[var(--foreground)] font-semibold' },
      social: { bg: 'bg-cyan-100 dark:bg-cyan-500/20', text: 'text-[var(--foreground)] font-semibold' },
      spam: { bg: 'bg-red-100 dark:bg-red-500/20', text: 'text-[var(--foreground)] font-semibold' },
    }
    return styles[category] || styles.newsletter
  }

  const getCategoryLabel = (category: string | null) => {
    if (!category) return ''
    const labels: Record<string, string> = {
      work: 'Công việc',
      personal: 'Cá nhân',
      transaction: 'Giao dịch',
      newsletter: 'Newsletter',
      promotion: 'Khuyến mãi',
      social: 'Mạng XH',
      spam: 'Spam',
      uncategorized: 'Chưa phân loại',
    }
    return labels[category] || category
  }

  const categoryStyle = email.category ? getCategoryStyle(email.category) : null

  return (
    <div
      className={cn(
        'flex items-start gap-3 px-4 py-3 cursor-pointer transition-colors border-b border-[var(--border)]',
        isSelected ? 'bg-[var(--secondary)]' : 'hover:bg-[var(--hover)]',
        !email.is_read && 'bg-[var(--card)]'
      )}
    >
      {/* Star button */}
      <button
        onClick={(e) => {
          e.stopPropagation()
          onStar?.(email.is_starred)
        }}
        className={cn(
          'mt-0.5 flex-shrink-0 transition-colors',
          email.is_starred ? 'text-amber-500' : 'text-gray-500 dark:text-gray-400 hover:text-amber-400'
        )}
      >
        <Star
          className="w-4 h-4"
          strokeWidth={1.5}
          fill={email.is_starred ? 'currentColor' : 'none'}
        />
      </button>

      {/* Content - clickable */}
      <div onClick={onSelect} className="flex-1 min-w-0 cursor-pointer">
        {/* Row 1: Sender + Time */}
        <div className="flex items-center justify-between gap-2">
          <span className={cn(
            'text-[14px] truncate',
            email.is_read ? 'text-[var(--muted)] font-medium' : 'text-[var(--foreground)] font-bold'
          )}>
            {email.from_name || email.from_address?.split('@')[0]}
          </span>
          <span className="text-[12px] text-[var(--muted-foreground)] flex-shrink-0">
            {formatTime(email.received_at)}
          </span>
        </div>

        {/* Row 2: Priority + Subject */}
        <div className="flex items-center gap-1.5 mt-0.5">
          {(email.priority || 0) >= 4 && (
            <span className="w-1.5 h-1.5 rounded-full bg-red-600 flex-shrink-0" />
          )}
          <span className={cn(
            'text-[14px] truncate',
            email.is_read ? 'text-[var(--muted-foreground)] font-normal' : 'text-[var(--foreground)] font-semibold'
          )}>
            {email.subject || '(Không có tiêu đề)'}
          </span>
        </div>

        {/* Row 3: Summary preview */}
        {email.summary && (
          <p className="text-[13px] text-[var(--muted-foreground)] truncate mt-0.5">
            {email.summary}
          </p>
        )}
      </div>

      {/* Category tag */}
      {email.category && categoryStyle && (
        <button
          onClick={(e) => {
            e.stopPropagation()
            onCategoryClick?.(email.category!)
          }}
          className={cn(
            'px-2 py-0.5 rounded text-[11px] font-medium flex-shrink-0 transition-colors hover:opacity-80',
            categoryStyle.bg,
            categoryStyle.text
          )}
        >
          {getCategoryLabel(email.category)}
        </button>
      )}
    </div>
  )
})

export function EmailListVirtual({
  emails,
  selectedId,
  onSelect,
  onStar,
  onCategoryClick,
  onLoadMore,
  hasMore,
  isFetchingMore,
}: Props) {
  const parentRef = useRef<HTMLDivElement>(null)

  const virtualizer = useVirtualizer({
    count: emails.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 76, // Estimated row height
    overscan: 10, // Render extra items for smoother scrolling
  })

  const items = virtualizer.getVirtualItems()

  // Load more when scrolled near bottom
  const handleScroll = useCallback(() => {
    if (!parentRef.current || !hasMore || !onLoadMore || isFetchingMore) return

    const { scrollTop, scrollHeight, clientHeight } = parentRef.current
    if (scrollHeight - scrollTop <= clientHeight + 300) {
      onLoadMore()
    }
  }, [hasMore, onLoadMore, isFetchingMore])

  if (emails.length === 0) {
    return (
      <div className="flex items-center justify-center h-32 text-[14px] text-[var(--muted-foreground)]">
        Không có email
      </div>
    )
  }

  return (
    <div
      ref={parentRef}
      onScroll={handleScroll}
      className="h-full overflow-auto"
    >
      <div
        style={{
          height: `${virtualizer.getTotalSize()}px`,
          width: '100%',
          position: 'relative',
        }}
      >
        {items.map((virtualItem) => {
          const email = emails[virtualItem.index]
          return (
            <div
              key={email.id}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: `${virtualItem.size}px`,
                transform: `translateY(${virtualItem.start}px)`,
              }}
            >
              <EmailRow
                email={email}
                isSelected={selectedId === email.id}
                onSelect={() => onSelect(email.id)}
                onStar={(starred) => onStar?.(email.id, starred)}
                onCategoryClick={onCategoryClick}
              />
            </div>
          )
        })}
      </div>

      {/* Load more indicator */}
      {isFetchingMore && (
        <div className="py-4 text-center text-[13px] text-[var(--muted-foreground)]">
          Đang tải thêm...
        </div>
      )}

      {!hasMore && emails.length > 0 && (
        <div className="py-4 text-center text-[12px] text-[var(--muted-foreground)]">
          Đã hiển thị tất cả
        </div>
      )}
    </div>
  )
}

'use client'

import { Star, Paperclip, AlertCircle } from 'lucide-react'
import { cn, formatDate, truncate } from '@/lib/utils'
import { Badge } from '@/components/ui/badge'
import type { Email } from '@/types'

interface EmailListProps {
  emails: Email[]
  selectedId?: string
  onSelect: (email: Email) => void
  onStar: (emailId: string) => void
}

const priorityColors: Record<number, string> = {
  1: 'bg-red-600',
  2: 'bg-amber-600',
  3: 'bg-[var(--primary)]',
  4: 'bg-[var(--muted-foreground)]',
  5: 'bg-[var(--border)]',
}

const categoryLabels: Record<string, { label: string; variant: 'default' | 'secondary' | 'success' | 'warning' | 'urgent' | 'info' }> = {
  work: { label: 'Công việc', variant: 'info' },
  personal: { label: 'Cá nhân', variant: 'success' },
  newsletter: { label: 'Bản tin', variant: 'default' },
  promotion: { label: 'Khuyến mãi', variant: 'warning' },
  transaction: { label: 'Giao dịch', variant: 'urgent' },
  social: { label: 'Mạng XH', variant: 'secondary' },
}

export function EmailList({ emails, selectedId, onSelect, onStar }: EmailListProps) {
  if (emails.length === 0) {
    return null
  }

  return (
    <div className="divide-y divide-[var(--border)]">
      {emails.map((email) => {
        const categoryInfo = email.category ? categoryLabels[email.category] : null
        const isSelected = email.id === selectedId

        return (
          <div
            key={email.id}
            onClick={() => onSelect(email)}
            className={cn(
              'flex items-start gap-3 p-4 cursor-pointer transition-colors',
              isSelected
                ? 'bg-[var(--secondary)]'
                : email.is_read
                  ? 'bg-[var(--card)] hover:bg-[var(--hover)]'
                  : 'bg-[var(--background)] hover:bg-[var(--secondary)]'
            )}
          >
            {/* Priority Indicator */}
            <div className={cn('w-1 h-14 rounded-full flex-shrink-0', priorityColors[email.priority || 3])} />

            {/* Star */}
            <button
              onClick={(e) => {
                e.stopPropagation()
                onStar(email.id)
              }}
              className="flex-shrink-0 mt-0.5"
            >
              <Star
                className={cn(
                  'w-5 h-5 transition-colors',
                  email.is_starred ? 'fill-amber-500 text-amber-500' : 'text-gray-500 dark:text-gray-400 hover:text-amber-400'
                )}
                strokeWidth={1.5}
              />
            </button>

            {/* Content */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-1">
                <span className={cn(
                  'text-[14px] truncate',
                  email.is_read ? 'text-[var(--muted)]' : 'font-semibold text-[var(--foreground)]'
                )}>
                  {email.from_name || email.from_address}
