import { Badge } from '@/components/ui/badge'

interface WeeklyReport {
  period: { start: string; end: string }
  stats: {
    totalReceived: number
    totalProcessed: number
    processRate: number
    avgResponseTime: number
    inboxZeroDays: number
    busiestDay: string
    busiestHour: number
    categoryBreakdown: Record<string, number>
  }
  topSenders: Array<{
    email: string
    name: string
    totalEmails: number
    openRate: number
    suggestion: string
    reason: string
  }>
  productivity: {
    score: number
    grade: string
    trend: string
    trendValue: number
    factors: Array<{ name: string; score: number; weight: number }>
  }
  suggestions: Array<{
    type: string
    title: string
    description: string
    actionable: boolean
  }>
  comparison: Array<{
    metric: string
    current: number
    previous: number
    change: number
    changePercent: number
  }>
}

export function WeeklyReportView() {
  const [report, setReport] = useState<WeeklyReport | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetchReport()
  }, [])

  const fetchReport = async () => {
    try {
      const res = await fetch('/api/ai/insights/weekly')
      const data = await res.json()
      setReport(data)
    } catch (error) {
      console.error('Failed to fetch report:', error)
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return (
      <div className="p-12 text-center">
        <Loader2 className="w-8 h-8 animate-spin mx-auto mb-4 text-[var(--muted)]" strokeWidth={1.5} />
        <p className="text-[15px] text-[var(--muted-foreground)]">Đang phân tích dữ liệu...</p>
      </div>
    )
  }

  if (!report) {
    return (
      <div className="p-12 text-center">
        <AlertCircle className="w-12 h-12 mx-auto mb-4 text-[var(--muted)]" strokeWidth={1.5} />
        <p className="text-[15px] text-[var(--muted-foreground)]">Không thể tải báo cáo</p>
      </div>
    )
  }

  const TrendIcon = report.productivity.trend === 'up' ? TrendingUp :
                    report.productivity.trend === 'down' ? TrendingDown : Minus

  const formatDate = (iso: string) => {
    return new Date(iso).toLocaleDateString('vi-VN', { day: 'numeric', month: 'short' })
  }

  return (
    <div className="p-6 space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-[20px] font-semibold text-[var(--foreground)]">
            Báo cáo tuần
          </h2>
          <p className="text-[14px] text-[var(--muted-foreground)] mt-1">
            {formatDate(report.period.start)} - {formatDate(report.period.end)}
          </p>
        </div>
        <div className={cn(
          "flex items-center gap-2 px-4 py-2 rounded-full !text-gray-900 dark:!text-gray-100",
          report.productivity.grade === 'Xuất sắc' && "bg-green-100 dark:bg-green-900/30",
          report.productivity.grade === 'Tốt' && "bg-blue-100 dark:bg-blue-900/30",
          report.productivity.grade === 'Khá' && "bg-amber-100 dark:bg-amber-900/30",
          report.productivity.grade === 'Cần cải thiện' && "bg-red-100 dark:bg-red-900/30"
        )}>
          <span className="text-[24px] font-semibold">{report.productivity.score}</span>
          <div className="text-left">
            <p className="text-[11px] uppercase tracking-wide font-semibold">Điểm</p>
            <p className="text-[13px] font-semibold">{report.productivity.grade}</p>
          </div>
          <TrendIcon className="w-5 h-5 ml-2" strokeWidth={1.5} />
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-4 gap-4">
        <StatCard
          icon={<Mail className="w-4 h-4" strokeWidth={1.5} />}
          label="Email nhận"
          value={report.stats.totalReceived}
          subtext={`${report.stats.processRate}% đã xử lý`}
        />
        <StatCard
          icon={<Clock className="w-4 h-4" strokeWidth={1.5} />}
          label="Phản hồi TB"
          value={`${report.stats.avgResponseTime}h`}
          subtext="Thời gian trung bình"
        />
        <StatCard
          icon={<Inbox className="w-4 h-4" strokeWidth={1.5} />}
          label="Inbox Zero"
          value={`${report.stats.inboxZeroDays}/7`}
          subtext="ngày đạt được"
        />
        <StatCard
          icon={<Zap className="w-4 h-4" strokeWidth={1.5} />}
          label="Bận nhất"
          value={report.stats.busiestDay}
          subtext={`${report.stats.busiestHour}:00`}
        />
      </div>

      {/* Comparison */}
      <div className="bg-[var(--secondary)] rounded-xl p-5">
        <h3 className="text-[14px] font-medium text-[var(--foreground)] mb-4">
          So với tuần trước
        </h3>
        <div className="grid grid-cols-3 gap-6">
          {report.comparison.map((item, index) => (
            <div key={index}>
              <p className="text-[13px] text-[var(--muted-foreground)] mb-1">{item.metric}</p>
              <div className="flex items-baseline gap-2">
                <span className="text-[20px] font-semibold text-[var(--foreground)]">
                  {item.current}
                </span>
                <span className={cn(
                  "text-[13px] font-medium flex items-center",
                  item.change > 0 && "text-green-700 dark:text-green-400",
                  item.change < 0 && "text-red-700 dark:text-red-400",
                  item.change === 0 && "text-[var(--muted)]"
                )}>
                  {item.change > 0 ? '+' : ''}{item.changePercent}%
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Top Senders */}
      <div>
        <h3 className="text-[14px] font-medium text-[var(--foreground)] mb-4 flex items-center gap-2">
          <Users className="w-4 h-4" strokeWidth={1.5} />
          Top người gửi
        </h3>
        <div className="space-y-2">
          {report.topSenders.slice(0, 5).map((sender, index) => (
            <div
              key={index}
              className="flex items-center gap-4 p-3 rounded-xl border border-[var(--border)] bg-[var(--card)]"
            >
              <div className="w-10 h-10 rounded-full bg-[var(--secondary)] flex items-center justify-center text-[14px] font-medium text-[var(--muted-foreground)]">
                {sender.name.charAt(0).toUpperCase()}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[14px] font-medium text-[var(--foreground)] truncate">
                  {sender.name}
                </p>
                <p className="text-[13px] text-[var(--muted-foreground)]">
                  {sender.totalEmails} email · {sender.openRate}% mở
                </p>
              </div>
              {sender.suggestion !== 'none' && (
                <Badge
                  variant={sender.suggestion === 'vip' ? 'warning' : sender.suggestion === 'unsubscribe' ? 'urgent' : 'default'}
                  size="md"
                  className="flex items-center gap-1.5"
                >
                  {sender.suggestion === 'vip' && <Star className="w-3 h-3" strokeWidth={1.5} />}
                  {sender.suggestion === 'unsubscribe' && <UserX className="w-3 h-3" strokeWidth={1.5} />}
                  {sender.suggestion === 'mute' && <Bell className="w-3 h-3" strokeWidth={1.5} />}
                  {sender.suggestion === 'vip' ? 'Đánh dấu VIP' :
                   sender.suggestion === 'unsubscribe' ? 'Unsubscribe?' : 'Tắt thông báo'}
                </Badge>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Suggestions */}
      {report.suggestions.length > 0 && (
        <div>
          <h3 className="text-[14px] font-medium text-[var(--foreground)] mb-4 flex items-center gap-2">
            <Lightbulb className="w-4 h-4" strokeWidth={1.5} />
            Gợi ý từ AI
          </h3>
          <div className="space-y-2">
            {report.suggestions.map((suggestion, index) => {
              const getVariant = () => {
                switch (suggestion.type) {
                  case 'unsubscribe': return 'red'
                  case 'vip': return 'amber'
                  case 'rule': return 'blue'
                  case 'habit': return 'emerald'
                  default: return 'default'
                }
              }
              return (
                <div
                  key={index}
                  className="flex items-center gap-4 p-4 rounded-xl border border-[var(--border)] bg-[var(--card)] hover:bg-[var(--hover)] transition-colors cursor-pointer"
                >
                  {suggestion.type === 'unsubscribe' && <UserX className="w-5 h-5 text-red-500 dark:text-red-400 flex-shrink-0" strokeWidth={1.5} />}
                  {suggestion.type === 'vip' && <Star className="w-5 h-5 text-amber-500 dark:text-amber-400 flex-shrink-0" strokeWidth={1.5} />}
                  {suggestion.type === 'rule' && <Zap className="w-5 h-5 text-blue-500 dark:text-blue-400 flex-shrink-0" strokeWidth={1.5} />}
                  {suggestion.type === 'habit' && <Clock className="w-5 h-5 text-emerald-500 dark:text-emerald-400 flex-shrink-0" strokeWidth={1.5} />}
                  <div className="flex-1">
                    <p className="text-[14px] font-medium text-[var(--foreground)]">
                      {suggestion.title}
                    </p>
                    <p className="text-[13px] text-[var(--muted-foreground)]">
                      {suggestion.description}
                    </p>
                  </div>
                  {suggestion.actionable && (
                    <ChevronRight className="w-5 h-5 text-[var(--muted)]" strokeWidth={1.5} />
                  )}
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* Productivity Factors */}
      <div className="bg-[var(--secondary)] rounded-xl p-5">
        <h3 className="text-[14px] font-medium text-[var(--foreground)] mb-4">
          Phân tích điểm Productivity
        </h3>
        <div className="space-y-3">
          {report.productivity.factors.map((factor, index) => (
            <div key={index}>
              <div className="flex items-center justify-between mb-1">
                <span className="text-[13px] text-[var(--muted-foreground)]">{factor.name}</span>
                <span className="text-[13px] font-medium text-[var(--foreground)]">
                  {Math.round(factor.score)}/100
                </span>
              </div>
              <div className="h-2 bg-[var(--border)] rounded-full overflow-hidden">
                <div
                  className={cn(
                    "h-full rounded-full transition-all",
                    factor.score >= 70 ? "bg-green-500" :
                    factor.score >= 50 ? "bg-amber-500" : "bg-red-500"
                  )}
                  style={{ width: `${factor.score}%` }}
                />
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

'use client'

import Link from 'next/link'
import { usePathname, useSearchParams } from 'next/navigation'
import { Inbox, Send, Star, Archive, Settings, Pencil } from 'lucide-react'
import { cn } from '@/lib/utils'

const navItems = [
  { href: '/inbox', icon: Inbox, label: 'Inbox' },
  { href: '/sent', icon: Send, label: 'Gửi' },
  { href: '/compose', icon: Pencil, label: 'Soạn', isCompose: true },
  { href: '/starred', icon: Star, label: 'Sao' },
  { href: '/settings', icon: Settings, label: 'Cài đặt' },
]

export function MobileNav() {
  const pathname = usePathname()
  const searchParams = useSearchParams()

  // Hide bottom nav when viewing email detail on mobile
  const isViewingEmail = searchParams.get('email') !== null

  if (isViewingEmail) {
    return null
  }

  return (
    <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-[var(--card)] border-t border-[var(--border)] flex items-center justify-around px-2 z-50 pb-safe" style={{ paddingBottom: 'max(0.5rem, env(safe-area-inset-bottom))' }}>
      {navItems.map((item) => {
        const isActive = pathname === item.href || pathname.startsWith(item.href + '/')

        if (item.isCompose) {
          return (
            <Link
              key={item.href}
              href={item.href}
              className="flex flex-col items-center justify-center w-14 h-14 -mt-4 bg-[var(--primary)] rounded-full text-[var(--primary-foreground)] shadow-lg"
            >
              <item.icon className="w-5 h-5" strokeWidth={1.5} />
            </Link>
          )
        }

        return (
          <Link
            key={item.href}
            href={item.href}
            className={cn(
              'flex flex-col items-center justify-center gap-1 py-2 px-3 rounded-lg transition-colors',
              isActive
                ? 'text-[var(--foreground)]'
                : 'text-[var(--muted-foreground)]'
            )}
          >
            <item.icon
              className="w-5 h-5"
              strokeWidth={1.5}
              fill={isActive && item.icon === Star ? 'currentColor' : 'none'}
            />
            <span className="text-[10px] font-medium">{item.label}</span>
          </Link>
        )
      })}
    </nav>
  )
}

'use client';

/**
 * Unified Top Bar - Desktop
 * Single bar with search + filter dropdown
 */

import { memo, useState, useCallback, useRef, useEffect } from 'react';
import {
  Search,
  Menu,
  ChevronDown,
  Check,
  Inbox,
  Zap,
  Briefcase,
  User,
  CreditCard,
  Newspaper,
  Gift,
  Users,
  AlertOctagon,
  X,
  Sparkles,
  Sun,
  Moon,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useRouter } from 'next/navigation';
import { NotificationDropdown } from '@/components/notifications/notification-dropdown';
import { useTheme } from '@/contexts/theme-context';

// Category definitions
const CATEGORIES = [
  { id: 'all', label: 'Tất cả', icon: Inbox, color: 'text-gray-600 dark:text-gray-400' },
  { id: 'needs_action', label: 'Cần xử lý', icon: Zap, color: 'text-red-500', dividerAfter: true },
  { id: 'work', label: 'Công việc', icon: Briefcase, color: 'text-blue-500' },
  { id: 'personal', label: 'Cá nhân', icon: User, color: 'text-purple-500' },
  { id: 'transaction', label: 'Giao dịch', icon: CreditCard, color: 'text-green-500' },
  { id: 'newsletter', label: 'Newsletter', icon: Newspaper, color: 'text-gray-500' },
  { id: 'promotion', label: 'Khuyến mãi', icon: Gift, color: 'text-orange-500' },
  { id: 'social', label: 'Mạng XH', icon: Users, color: 'text-cyan-500', dividerAfter: true },
  { id: 'spam', label: 'Spam', icon: AlertOctagon, color: 'text-red-400' },
];

interface BriefingItem {
  type: string;
  title: string;
  count: number;
  emailIds?: string[];
}

interface BriefingData {
  unread: number;
  needsAttention: number;
  items: BriefingItem[];
}

interface UnifiedTopBarProps {
  currentFilter: string;
  onFilterChange: (filter: string) => void;
  emailCounts: Record<string, number>;
  totalEmails: number;
  onSearch: (query: string) => void;
  onMenuClick?: () => void;
  onProfileClick?: () => void;
  className?: string;
  noBorder?: boolean;
}

export const UnifiedTopBar = memo(function UnifiedTopBar({
  currentFilter,
  onFilterChange,
  emailCounts,
  totalEmails,
  onSearch,
  onMenuClick,
  onProfileClick,
  className,
  noBorder,
}: UnifiedTopBarProps) {
  const router = useRouter();
  const { theme, toggleTheme } = useTheme();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [showAIPopover, setShowAIPopover] = useState(false);
  const [briefing, setBriefing] = useState<BriefingData | null>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const aiPopoverRef = useRef<HTMLDivElement>(null);

  // Get current category info
  const currentCategory = CATEGORIES.find(c => c.id === currentFilter) || CATEGORIES[0];

  // Close dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
      if (aiPopoverRef.current && !aiPopoverRef.current.contains(event.target as Node)) {
        setShowAIPopover(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Fetch AI briefing data
  useEffect(() => {
    const fetchBriefing = async () => {
      try {
        const res = await fetch('/api/ai/briefing');
        if (res.ok) {
          const data = await res.json();
          setBriefing({
            unread: data.summary?.unread || 0,
            needsAttention: data.briefingItems?.length || 0,
            items: data.briefingItems || []
          });
        }
      } catch {
        console.error('Failed to fetch briefing');
      }
    };

    fetchBriefing();
    // Refresh every 5 minutes
    const interval = setInterval(fetchBriefing, 300000);
    return () => clearInterval(interval);
  }, []);

  // Handle navigate to inbox with filter
  const handleNavigateToInbox = useCallback((item?: BriefingItem) => {
    setShowAIPopover(false);
    if (item?.emailIds && item.emailIds.length > 0) {
      sessionStorage.setItem('briefing_filter', JSON.stringify({
        type: item.type,
        title: item.title,
        emailIds: item.emailIds
      }));
      router.push(`/inbox?briefing=${item.type}`);
    }
  }, [router]);

  // Handle filter select
  const handleFilterSelect = useCallback((filterId: string) => {
    onFilterChange(filterId);
    setIsDropdownOpen(false);
  }, [onFilterChange]);

  // Handle search
  const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(e.target.value);
  }, []);

  const handleSearchSubmit = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    onSearch(searchQuery);
  }, [onSearch, searchQuery]);

  const handleSearchClear = useCallback(() => {
    setSearchQuery('');
    onSearch('');
    searchInputRef.current?.focus();
  }, [onSearch]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Cmd/Ctrl + K to focus search
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
      // Escape to clear/blur search
      if (e.key === 'Escape') {
        if (isSearchFocused) {
          searchInputRef.current?.blur();
          setIsSearchFocused(false);
        }
        setIsDropdownOpen(false);
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isSearchFocused]);

  return (
    <div className={cn(
      'flex items-center gap-3 px-4 py-2.5 bg-[var(--card)]',
      !noBorder && 'border-b border-[var(--border)]',
      className
    )}>
      {/* Menu Button */}
      <button
        onClick={onMenuClick}
        className="p-2 hover:bg-[var(--hover)] rounded-lg transition-colors lg:hidden"
      >
        <Menu className="w-5 h-5 text-[var(--foreground-muted)]" />
      </button>

      {/* Search Bar */}
      <form
        onSubmit={handleSearchSubmit}
        className={cn(
          'flex-1 flex items-center gap-2 px-3 py-2 rounded-xl transition-all',
          'bg-[var(--secondary)]',
          isSearchFocused && 'ring-2 ring-blue-500 bg-[var(--card)]'
        )}
      >
        <Search className="w-4 h-4 text-[var(--foreground-muted)] flex-shrink-0" />
        <input
          ref={searchInputRef}
          type="text"
          value={searchQuery}
          onChange={handleSearchChange}
          onFocus={() => setIsSearchFocused(true)}
          onBlur={() => setIsSearchFocused(false)}
          placeholder="Tìm kiếm email... (⌘K)"
          className="flex-1 bg-transparent text-sm text-[var(--foreground)] placeholder-[var(--foreground-muted)] outline-none"
        />
        {searchQuery && (
          <button
            type="button"
            onClick={handleSearchClear}
            className="p-1 hover:bg-[var(--hover)] rounded-full transition-colors"
          >
            <X className="w-3.5 h-3.5 text-[var(--foreground-muted)]" />
          </button>
        )}
      </form>

      {/* Filter Dropdown */}
      <div className="relative" ref={dropdownRef}>
        <button
          onClick={() => setIsDropdownOpen(!isDropdownOpen)}
          className={cn(
            'flex items-center gap-2 px-3 py-2 rounded-xl transition-all',
            'hover:bg-[var(--hover)]',
            isDropdownOpen && 'bg-[var(--hover)]'
          )}
        >
          <currentCategory.icon className={cn('w-4 h-4', currentCategory.color)} />
          <span className="text-sm font-semibold text-[var(--foreground)] hidden sm:inline">
            {currentCategory.label}
          </span>
          <ChevronDown className={cn(
            'w-4 h-4 text-[var(--foreground-muted)] transition-transform',
            isDropdownOpen && 'rotate-180'
          )} />
        </button>

        {/* Dropdown Menu */}
        {isDropdownOpen && (
          <div className={cn(
            'absolute right-0 top-full mt-2 w-56 py-2 z-50',
            'bg-[var(--card)] rounded-xl shadow-xl',
            'border border-[var(--border)]',
            'animate-in fade-in slide-in-from-top-2 duration-200'
          )}>
            {CATEGORIES.map((category) => (
              <div key={category.id}>
                <button
                  onClick={() => handleFilterSelect(category.id)}
                  className={cn(
                    'w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors',
                    'hover:bg-[var(--hover)]',
                    currentFilter === category.id && 'bg-[var(--accent)]'
                  )}
                >
                  <category.icon className={cn('w-4 h-4', category.color)} />
                  <span className="flex-1 text-sm font-medium text-[var(--foreground)]">
                    {category.label}
                  </span>
                  {emailCounts[category.id] !== undefined && emailCounts[category.id] > 0 && (
                    <span className="text-xs text-[var(--foreground-muted)] tabular-nums">
                      {emailCounts[category.id]}
                    </span>
                  )}
                  {currentFilter === category.id && (
                    <Check className="w-4 h-4 text-blue-500" />
                  )}
                </button>
                {category.dividerAfter && (
                  <div className="my-1 border-t border-[var(--border)]" />
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Theme Toggle - Show current theme icon */}
      <button
        type="button"
        onClick={toggleTheme}
        className="p-2 text-[var(--foreground-muted)] hover:text-[var(--foreground)] transition-colors"
        title={theme === 'dark' ? 'Chuyển sang sáng' : 'Chuyển sang tối'}
      >
        {theme === 'dark' ? (
          <Moon className="w-5 h-5" />
        ) : (
          <Sun className="w-5 h-5" />
        )}
      </button>

      {/* AI Assistant Button */}
      <div className="relative" ref={aiPopoverRef}>
        <button
          type="button"
          onClick={() => setShowAIPopover(!showAIPopover)}
          className="relative p-2 text-gray-500 dark:text-gray-400 hover:text-[var(--foreground)] transition-colors"
        >
          <Sparkles className="w-5 h-5" strokeWidth={1.5} />
          {briefing && briefing.needsAttention > 0 && (
            <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] flex items-center justify-center px-1 text-[10px] font-bold text-white bg-red-500 rounded-full">
              {briefing.needsAttention}
            </span>
          )}
        </button>

        {/* AI Popover */}
        {showAIPopover && (
          <div className="absolute right-0 top-full mt-2 w-80 bg-[var(--card)] rounded-xl border border-[var(--border)] shadow-lg z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
            <div className="p-4 border-b border-[var(--border)] bg-[var(--secondary)]">
