            </div>
          </div>
        )}
      </div>

      {/* Notification Dropdown */}
      <NotificationDropdown />

      {/* Profile */}
      <button
        onClick={onProfileClick}
        className="w-8 h-8 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center"
      >
        <span className="text-xs font-semibold text-white">U</span>
      </button>
    </div>
  );
});

export default UnifiedTopBar;

'use client'

import { useState, useEffect } from 'react'
import { X, Mail, Loader2, CheckCircle, AlertCircle, Eye, EyeOff, Server } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { ConnectGoogleButton } from './connect-google'

interface AddAccountModalProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: () => void
}

interface EmailProvider {
  id: string
  name: string
  imap_host: string
  imap_port: number
  smtp_host: string
  smtp_port: number
  requires_app_password?: boolean
  notes?: string
  help_url?: string
}

// Provider icons and colors
const PROVIDER_STYLES: Record<string, { icon: string; color: string }> = {
  gmail: { icon: '📧', color: 'bg-red-50 dark:bg-red-500/10 border-red-200 dark:border-red-500/30' },
  outlook: { icon: '📨', color: 'bg-blue-50 dark:bg-blue-500/10 border-blue-200 dark:border-blue-500/30' },
  yahoo: { icon: '📩', color: 'bg-purple-50 dark:bg-purple-500/10 border-purple-200 dark:border-purple-500/30' },
  zoho: { icon: '🔷', color: 'bg-orange-50 dark:bg-orange-500/10 border-orange-200 dark:border-orange-500/30' },
  icloud: { icon: '☁️', color: 'bg-sky-50 dark:bg-sky-500/10 border-sky-200 dark:border-sky-500/30' },
  yandex: { icon: '🔴', color: 'bg-red-50 dark:bg-red-500/10 border-red-200 dark:border-red-500/30' },
  fastmail: { icon: '⚡', color: 'bg-indigo-50 dark:bg-indigo-500/10 border-indigo-200 dark:border-indigo-500/30' },
  hostinger: { icon: '🌐', color: 'bg-violet-50 dark:bg-violet-500/10 border-violet-200 dark:border-violet-500/30' },
  namecheap: { icon: '🏷️', color: 'bg-orange-50 dark:bg-orange-500/10 border-orange-200 dark:border-orange-500/30' },
  custom: { icon: '⚙️', color: 'bg-[var(--secondary)] border-[var(--border)]' },
}

type Step = 'select-provider' | 'enter-credentials' | 'connecting' | 'success' | 'error'

export function AddAccountModal({ isOpen, onClose, onSuccess }: AddAccountModalProps) {
  const [step, setStep] = useState<Step>('select-provider')
  const [providers, setProviders] = useState<EmailProvider[]>([])
  const [loadingProviders, setLoadingProviders] = useState(false)
  const [provider, setProvider] = useState<string>('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Custom IMAP/SMTP settings
  const [imapHost, setImapHost] = useState('')
  const [imapPort, setImapPort] = useState('993')
  const [smtpHost, setSmtpHost] = useState('')
  const [smtpPort, setSmtpPort] = useState('587')

  // Fetch providers when modal opens
  useEffect(() => {
    if (isOpen && providers.length === 0) {
      setLoadingProviders(true)
      fetch('/api/email-providers')
        .then(res => res.json())
        .then(data => {
          setProviders(data.providers || [])
        })
        .catch(err => {
          console.error('Failed to load providers:', err)
        })
        .finally(() => {
          setLoadingProviders(false)
        })
    }
  }, [isOpen, providers.length])

  const resetForm = () => {
    setStep('select-provider')
    setProvider('')
    setEmail('')
    setPassword('')
    setError(null)
    setImapHost('')
    setImapPort('993')
    setSmtpHost('')
    setSmtpPort('587')
  }

  const handleClose = () => {
    resetForm()
    onClose()
  }

  const handleSelectProvider = (providerId: string) => {
    setProvider(providerId)
    // Auto-fill IMAP/SMTP settings from provider preset
    const selectedProvider = providers.find(p => p.id === providerId)
    if (selectedProvider && providerId !== 'custom') {
      setImapHost(selectedProvider.imap_host)
      setImapPort(String(selectedProvider.imap_port))
      setSmtpHost(selectedProvider.smtp_host)
      setSmtpPort(String(selectedProvider.smtp_port))
    }
    setStep('enter-credentials')
  }

  // Get provider style (icon, color)
  const getProviderStyle = (providerId: string) => {
    return PROVIDER_STYLES[providerId] || PROVIDER_STYLES.custom
  }

  // Get selected provider object
  const selectedProvider = providers.find(p => p.id === provider)

  const handleConnect = async () => {
    if (!email || !password) {
      setError('Vui lòng nhập email và mật khẩu')
      return
    }

    setStep('connecting')
    setError(null)

    try {
      const payload: Record<string, unknown> = {
        email_address: email,
        provider,
        username: email,
        password
      }

      // Add custom settings if provider is custom
      if (provider === 'custom') {
        payload.imap_host = imapHost
        payload.imap_port = parseInt(imapPort)
        payload.smtp_host = smtpHost
        payload.smtp_port = parseInt(smtpPort)
      }

      const response = await fetch('/api/source-accounts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })

      const result = await response.json()

      if (!response.ok) {
        throw new Error(result.details || result.error || 'Kết nối thất bại')
      }

      setStep('success')
      setTimeout(() => {
        onSuccess()
        handleClose()
      }, 1500)
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : 'Kết nối thất bại'
      setError(errorMsg)
      setStep('error')
    }
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={handleClose} />
      <div className="relative bg-[var(--card)] rounded-xl shadow-xl w-full max-w-lg mx-4 overflow-hidden border border-[var(--border)]">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-[var(--border)]">
          <h2 className="text-[16px] font-semibold text-[var(--foreground)]">
            Kết nối tài khoản email
          </h2>
          <button
            onClick={handleClose}
            className="p-1 text-[var(--muted)] hover:text-[var(--muted-foreground)] transition-colors"
          >
            <X className="w-5 h-5" strokeWidth={1.5} />
          </button>
        </div>

        {/* Content */}
        <div className="p-6">
          {/* Step 1: Select Provider */}
          {step === 'select-provider' && (
            <div className="space-y-4">
              {/* OAuth Options */}
              <div className="space-y-3">
                <p className="text-[14px] text-[var(--muted-foreground)] text-center">
                  Kết nối nhanh với 1 click
                </p>
                <ConnectGoogleButton />
              </div>

              {/* Divider */}
              <div className="relative my-4">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-[var(--border)]" />
                </div>
                <div className="relative flex justify-center text-sm">
                  <span className="px-3 bg-[var(--card)] text-[var(--muted-foreground)]">
                    hoặc dùng App Password
                  </span>
                </div>
              </div>

              {/* IMAP Providers */}
              <div className="space-y-2 max-h-[300px] overflow-y-auto">
                {loadingProviders ? (
                  <div className="flex items-center justify-center py-4">
                    <Loader2 className="w-5 h-5 animate-spin text-[var(--muted-foreground)]" />
                  </div>
                ) : (
                  providers.map(p => {
                    const style = getProviderStyle(p.id)
                    return (
                      <button
                        key={p.id}
                        onClick={() => handleSelectProvider(p.id)}
                        className={`w-full flex items-center gap-4 p-3 rounded-lg border transition-colors hover:bg-[var(--hover)] ${style.color}`}
                      >
                        <span className="text-xl">{style.icon}</span>
                        <div className="flex-1 text-left">
                          <span className="text-[14px] font-medium text-[var(--foreground)]">{p.name}</span>
                          {p.requires_app_password && (
                            <span className="ml-2 text-[11px] px-1.5 py-0.5 rounded bg-amber-100 dark:bg-amber-500/20 text-amber-700 dark:text-amber-300">
                              App Password
                            </span>
                          )}
                        </div>
                      </button>
                    )
                  })
                )}
              </div>
            </div>
          )}

          {/* Step 2: Enter Credentials */}
          {step === 'enter-credentials' && selectedProvider && (
            <div className="space-y-4">
              <button
                onClick={() => setStep('select-provider')}
                className="text-[14px] text-[var(--muted-foreground)] hover:text-[var(--foreground)]"
              >
                ← Quay lại
              </button>

              {(() => {
                const style = getProviderStyle(selectedProvider.id)
                return (
                  <div className={`flex items-center gap-3 p-3 rounded-lg ${style.color}`}>
                    <span className="text-xl">{style.icon}</span>
                    <span className="font-medium text-[var(--foreground)]">{selectedProvider.name}</span>
                  </div>
                )
              })()}

              <div className="bg-amber-50 dark:bg-amber-500/10 border border-amber-200 dark:border-amber-500/30 rounded-lg p-3 text-[13px] text-gray-900 dark:text-white">
                {selectedProvider.notes || 'Nhập thông tin đăng nhập email của bạn'}
                {selectedProvider.help_url && (
                  <a
                    href={selectedProvider.help_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="ml-2 text-blue-600 dark:text-blue-400 underline"
                  >
                    Hướng dẫn
                  </a>
                )}
              </div>

              <div className="space-y-3">
                <div>
                  <label className="block text-[13px] font-medium text-[var(--muted-foreground)] mb-1">
                    Email
                  </label>
                  <input
                    type="email"
                    value={email}
                    onChange={e => setEmail(e.target.value)}
                    placeholder="your-email@gmail.com"
                    className="w-full px-3 py-2 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] placeholder-[var(--muted)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-[13px] font-medium text-[var(--muted-foreground)] mb-1">
                    Mật khẩu / App Password
                  </label>
                  <div className="relative">
                    <input
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={e => setPassword(e.target.value)}
                      placeholder="xxxx xxxx xxxx xxxx"
                      className="w-full px-3 py-2 pr-10 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] placeholder-[var(--muted)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--muted)] hover:text-[var(--muted-foreground)]"
                    >
                      {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>
                </div>

                {/* Custom IMAP/SMTP fields */}
                {provider === 'custom' && (
                  <>
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <label className="block text-[13px] font-medium text-[var(--muted-foreground)] mb-1">
                          IMAP Host
                        </label>
                        <input
                          type="text"
                          value={imapHost}
                          onChange={e => setImapHost(e.target.value)}
                          placeholder="imap.example.com"
                          className="w-full px-3 py-2 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] placeholder-[var(--muted)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                        />
                      </div>
                      <div>
                        <label className="block text-[13px] font-medium text-[var(--muted-foreground)] mb-1">
                          IMAP Port
                        </label>
                        <input
                          type="text"
                          value={imapPort}
                          onChange={e => setImapPort(e.target.value)}
                          placeholder="993"
                          className="w-full px-3 py-2 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] placeholder-[var(--muted)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                        />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <label className="block text-[13px] font-medium text-[var(--muted-foreground)] mb-1">
                          SMTP Host
                        </label>
                        <input
                          type="text"
                          value={smtpHost}
                          onChange={e => setSmtpHost(e.target.value)}
                          placeholder="smtp.example.com"
                          className="w-full px-3 py-2 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] placeholder-[var(--muted)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                        />
                      </div>
                      <div>
                        <label className="block text-[13px] font-medium text-[var(--muted-foreground)] mb-1">
                          SMTP Port
                        </label>
                        <input
                          type="text"
                          value={smtpPort}
                          onChange={e => setSmtpPort(e.target.value)}
                          placeholder="587"
                          className="w-full px-3 py-2 border border-[var(--border)] rounded-lg bg-[var(--background)] text-[var(--foreground)] placeholder-[var(--muted)] focus:outline-none focus:ring-2 focus:ring-[var(--primary)] focus:border-transparent"
                        />
                      </div>
                    </div>
                  </>
                )}
              </div>

              {error && (
                <div className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/30 rounded-lg text-red-600 dark:text-red-400 text-[13px]">
                  <AlertCircle className="w-4 h-4 flex-shrink-0" />
                  {error}
                </div>
              )}

              <Button
                onClick={handleConnect}
                className="w-full"
                disabled={!email || !password}
              >
                <Mail className="w-4 h-4 mr-2" />
                Kết nối
              </Button>
            </div>
          )}

          {/* Step 3: Connecting */}
          {step === 'connecting' && (
            <div className="py-8 text-center">
              <Loader2 className="w-12 h-12 mx-auto text-[var(--foreground)] animate-spin mb-4" />
              <p className="text-[15px] text-[var(--muted-foreground)]">
                Đang kết nối và xác thực...
              </p>
              <p className="text-[13px] text-[var(--muted)] mt-1">
                Vui lòng đợi trong giây lát
              </p>
            </div>
          )}

          {/* Step 4: Success */}
          {step === 'success' && (
            <div className="py-8 text-center">
              <CheckCircle className="w-12 h-12 mx-auto text-green-500 mb-4" />
              <p className="text-[15px] font-medium text-[var(--foreground)]">
                Kết nối thành công!
              </p>
              <p className="text-[13px] text-[var(--muted-foreground)] mt-1">
                Email đã được thêm vào InboxAI
              </p>
            </div>
          )}

          {/* Step 5: Error */}
          {step === 'error' && (
            <div className="py-6 text-center">
              <AlertCircle className="w-12 h-12 mx-auto text-red-500 mb-4" />
              <p className="text-[15px] font-medium text-[var(--foreground)] mb-2">
                Kết nối thất bại
              </p>
              {error && (
                <p className="text-[13px] text-red-600 dark:text-red-400 mb-4 px-4">
                  {error}
                </p>
              )}
              <div className="flex gap-3 justify-center">
                <Button variant="secondary" onClick={() => setStep('enter-credentials')}>
                  Thử lại
                </Button>
                <Button variant="secondary" onClick={handleClose}>
                  Đóng
                </Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { Plus, RefreshCw, Trash2, Mail, AlertCircle, CheckCircle, Loader2, Sparkles, ChevronDown, Star, Edit2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { AddAccountModal } from './add-account-modal'
import { ConfirmDialog } from '@/components/ui/confirm-dialog'
import { cn } from '@/lib/utils'

// Account colors for color picker
const ACCOUNT_COLORS = [
  '#2563EB', // Blue
  '#10B981', // Green
  '#F59E0B', // Amber
  '#EF4444', // Red
  '#8B5CF6', // Purple
  '#EC4899', // Pink
  '#06B6D4', // Cyan
  '#F97316', // Orange
]

interface SourceAccount {
  id: string
  email_address: string
  display_name?: string
  provider: string
  avatar_url?: string
  is_primary: boolean
  color: string
  is_active: boolean
  last_sync_at?: string
  sync_status?: 'idle' | 'syncing' | 'error'
  sync_error?: string
  total_emails_synced: number
  email_count?: number
  unread_count?: number
  auth_type?: string
  created_at: string
}

export function SourceAccountsSection() {
  const [accounts, setAccounts] = useState<SourceAccount[]>([])
  const [loading, setLoading] = useState(true)
  const [showAddModal, setShowAddModal] = useState(false)
  const [syncingId, setSyncingId] = useState<string | null>(null)
  const [deleteConfirm, setDeleteConfirm] = useState<{ show: boolean; account?: SourceAccount }>({ show: false })
  const [deleting, setDeleting] = useState(false)
  const [classifying, setClassifying] = useState(false)
  const [syncDropdownId, setSyncDropdownId] = useState<string | null>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)

  const fetchAccounts = useCallback(async () => {
    try {
      const res = await fetch('/api/source-accounts')
      if (res.ok) {
        const data = await res.json()
        setAccounts(data.accounts || [])
      }
    } catch (error) {
      console.error('Failed to fetch accounts:', error)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setSyncDropdownId(null)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const handleSync = async (accountId: string, fullSync = false) => {
    setSyncingId(accountId)
    try {
      const res = await fetch(`/api/source-accounts/${accountId}/sync`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fullSync,
          limit: fullSync ? 500 : 100  // Optimized: 100 for quick, 500 for full
        })
      })
      const data = await res.json()

      if (res.ok) {
        // Refresh accounts to show updated sync info
        fetchAccounts()
        alert(data.message || `Đã đồng bộ ${data.synced} email`)
      } else {
        alert(data.error || 'Đồng bộ thất bại')
      }
    } catch (error) {
      console.error('Sync error:', error)
      alert('Đồng bộ thất bại')
    } finally {
      setSyncingId(null)
    }
  }

  const handleClassify = async () => {
    setClassifying(true)
    try {
      const res = await fetch('/api/ai/classify-batch', {
        method: 'POST'
      })
      const data = await res.json()

      if (res.ok) {
        alert(data.message || `Đã phân loại ${data.classified}/${data.total} email`)
      } else {
        alert(data.error || 'Phân loại thất bại')
      }
    } catch (error) {
      console.error('Classify error:', error)
      alert('Phân loại thất bại')
    } finally {
      setClassifying(false)
    }
  }

  const handleDelete = async () => {
    if (!deleteConfirm.account) return

    setDeleting(true)
    try {
      const res = await fetch(`/api/source-accounts/${deleteConfirm.account.id}`, {
        method: 'DELETE'
      })

      if (res.ok) {
        setAccounts(prev => prev.filter(a => a.id !== deleteConfirm.account!.id))
