  user_id: string
  sender_email: string
  sender_name: string | null
  total_received: number
  total_opened: number
  total_replied: number
  total_deleted: number
  total_archived: number
  avg_read_time: number
  importance_score: number
  engagement_score: number
  annoyance_score: number
}

export async function generateWeeklyReport(userId: string): Promise<WeeklyReport> {
  const now = new Date()
  const weekStart = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)
  const prevWeekStart = new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000)

  // Fetch this week's data
  const { data: thisWeekEmails } = await getSupabase()
    .from('emails')
    .select('*')
    .eq('user_id', userId)
    .gte('received_at', weekStart.toISOString())
    .order('received_at', { ascending: false })

  // Fetch last week's data for comparison
  const { data: lastWeekEmails } = await getSupabase()
    .from('emails')
    .select('*')
    .eq('user_id', userId)
    .gte('received_at', prevWeekStart.toISOString())
    .lt('received_at', weekStart.toISOString())

  // Fetch ALL emails for sender analysis (last 30 days for more data)
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000)
  const { data: allRecentEmails } = await getSupabase()
    .from('emails')
    .select('*')
    .eq('user_id', userId)
    .gte('received_at', thirtyDaysAgo.toISOString())
    .order('received_at', { ascending: false })

  const emails = (thisWeekEmails || []) as Email[]
  const prevEmails = (lastWeekEmails || []) as Email[]
  const allEmails = (allRecentEmails || []) as Email[]

  // === CALCULATE STATS ===
  const stats = calculateWeeklyStats(emails, [])
  const prevStats = calculateWeeklyStats(prevEmails, [])

  // === TOP SENDERS WITH INSIGHTS (from all recent emails) ===
  const topSenders = analyzeSendersFromEmails(allEmails)

  // === PRODUCTIVITY SCORE ===
  const productivity = calculateProductivityScore(stats, prevStats)

  // === SUGGESTIONS ===
  const suggestions = generateSuggestions(stats, topSenders)

  // === COMPARISON ===
  const comparison = [
    {
      metric: 'Email nhận',
      current: stats.totalReceived,
      previous: prevStats.totalReceived,
      change: stats.totalReceived - prevStats.totalReceived,
      changePercent: prevStats.totalReceived > 0
        ? Math.round((stats.totalReceived - prevStats.totalReceived) / prevStats.totalReceived * 100)
        : 0
    },
    {
      metric: 'Tỷ lệ xử lý',
      current: stats.processRate,
      previous: prevStats.processRate,
      change: stats.processRate - prevStats.processRate,
      changePercent: Math.round(stats.processRate - prevStats.processRate)
    },
    {
      metric: 'Thời gian phản hồi (giờ)',
      current: stats.avgResponseTime,
      previous: prevStats.avgResponseTime,
      change: stats.avgResponseTime - prevStats.avgResponseTime,
      changePercent: prevStats.avgResponseTime > 0
        ? Math.round((stats.avgResponseTime - prevStats.avgResponseTime) / prevStats.avgResponseTime * 100)
        : 0
    }
  ]

  return {
    period: {
      start: weekStart.toISOString(),
      end: now.toISOString()
    },
    stats,
    topSenders,
    productivity,
    suggestions,
    comparison
  }
}

function calculateWeeklyStats(emails: Email[], behaviors: Behavior[]): WeeklyStats {
  const totalReceived = emails.length
  const processed = emails.filter(e => e.is_read || e.is_archived || e.is_deleted)
  const totalProcessed = processed.length
  const processRate = totalReceived > 0 ? Math.round(totalProcessed / totalReceived * 100) : 0

  // Avg response time (for emails that were replied to)
  const repliedBehaviors = behaviors.filter(b => b.action === 'reply' && b.time_to_action)
  const avgResponseTime = repliedBehaviors.length > 0
    ? Math.round(repliedBehaviors.reduce((sum, b) => sum + (b.time_to_action || 0), 0) / repliedBehaviors.length / 3600 * 10) / 10
    : 0

  // Inbox zero days (days where all emails were processed)
  const emailsByDay: Record<string, { received: number; processed: number }> = {}
  emails.forEach(e => {
    const day = new Date(e.received_at).toDateString()
    if (!emailsByDay[day]) emailsByDay[day] = { received: 0, processed: 0 }
    emailsByDay[day].received++
    if (e.is_read || e.is_archived || e.is_deleted) emailsByDay[day].processed++
  })
  const inboxZeroDays = Object.values(emailsByDay).filter(d => d.received === d.processed).length

  // Busiest day
  const dayNames = ['Chủ nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7']
  const emailsByDayOfWeek: Record<number, number> = {}
  emails.forEach(e => {
    const day = new Date(e.received_at).getDay()
    emailsByDayOfWeek[day] = (emailsByDayOfWeek[day] || 0) + 1
  })
  const busiestDayNum = Object.entries(emailsByDayOfWeek)
    .sort((a, b) => b[1] - a[1])[0]?.[0] || '1'
  const busiestDay = dayNames[parseInt(busiestDayNum)]

  // Busiest hour
  const emailsByHour: Record<number, number> = {}
  emails.forEach(e => {
    const hour = new Date(e.received_at).getHours()
    emailsByHour[hour] = (emailsByHour[hour] || 0) + 1
  })
  const busiestHour = parseInt(
    Object.entries(emailsByHour).sort((a, b) => b[1] - a[1])[0]?.[0] || '9'
  )

  // Category breakdown
  const categoryBreakdown: Record<string, number> = {}
  emails.forEach(e => {
    const cat = e.category || 'uncategorized'
    categoryBreakdown[cat] = (categoryBreakdown[cat] || 0) + 1
  })

  // Priority breakdown
  const priorityBreakdown: Record<number, number> = {}
  emails.forEach(e => {
    const pri = e.priority || 3
    priorityBreakdown[pri] = (priorityBreakdown[pri] || 0) + 1
  })

  return {
    totalReceived,
    totalProcessed,
    processRate,
    avgResponseTime,
    inboxZeroDays,
    busiestDay,
    busiestHour,
    categoryBreakdown,
    priorityBreakdown
  }
}

function analyzeSendersFromEmails(emails: Email[]): SenderInsight[] {
  // Group emails by sender
  const senderMap: Record<string, {
    email: string
    name: string
    total: number
    read: number
    deleted: number
    archived: number
  }> = {}

  emails.forEach(e => {
    const key = e.from_address || 'unknown'
    if (!senderMap[key]) {
      senderMap[key] = {
        email: key,
        name: e.from_name || key.split('@')[0],
        total: 0,
        read: 0,
        deleted: 0,
        archived: 0
      }
    }
    senderMap[key].total++
    if (e.is_read) senderMap[key].read++
    if (e.is_deleted) senderMap[key].deleted++
    if (e.is_archived) senderMap[key].archived++
  })

  // Convert to array and sort by total
  const senders = Object.values(senderMap)
    .sort((a, b) => b.total - a.total)
    .slice(0, 10)

  return senders.map(sender => {
    const openRate = sender.total > 0
      ? Math.round(sender.read / sender.total * 100)
      : 0

    let suggestion: 'vip' | 'unsubscribe' | 'mute' | 'none' = 'none'
    let reason = ''

    // Suggest VIP if high engagement
    if (openRate >= 90 && sender.total >= 3) {
      suggestion = 'vip'
      reason = 'Luôn mở email từ người này'
    }
    // Suggest unsubscribe if very low engagement
    else if (openRate < 20 && sender.total >= 5) {
      suggestion = 'unsubscribe'
      reason = `${sender.total} email, chỉ mở ${sender.read}`
    }
    // Suggest mute if mostly deleted
    else if (sender.deleted > sender.read && sender.total >= 3) {
      suggestion = 'mute'
      reason = 'Thường xóa email từ người này'
    }

    return {
      email: sender.email,
      name: sender.name,
      totalEmails: sender.total,
      openRate,
      avgReadTime: 0,
      importance: openRate,
      suggestion,
      reason
    }
  })
}

function calculateProductivityScore(stats: WeeklyStats, prevStats: WeeklyStats): ProductivityScore {
  const factors = [
    {
      name: 'Tỷ lệ xử lý email',
      score: Math.min(100, stats.processRate),
      weight: 0.3
    },
    {
      name: 'Inbox Zero',
      score: Math.min(100, stats.inboxZeroDays / 7 * 100),
      weight: 0.2
    },
    {
      name: 'Thời gian phản hồi',
      score: Math.max(0, 100 - stats.avgResponseTime * 5), // Penalty for slow response
      weight: 0.25
    },
    {
      name: 'Xử lý email quan trọng',
      score: Math.min(100, (stats.priorityBreakdown[4] || 0) + (stats.priorityBreakdown[5] || 0) > 0 ? 80 : 100),
      weight: 0.25
    }
  ]

  const score = Math.round(
    factors.reduce((sum, f) => sum + f.score * f.weight, 0)
  )

  const prevScore = prevStats.totalReceived > 0
    ? Math.round(prevStats.processRate * 0.3 + (prevStats.inboxZeroDays / 7 * 100) * 0.2 + 50 * 0.5)
    : score

  let grade: 'Xuất sắc' | 'Tốt' | 'Khá' | 'Cần cải thiện'
  if (score >= 85) grade = 'Xuất sắc'
  else if (score >= 70) grade = 'Tốt'
  else if (score >= 50) grade = 'Khá'
  else grade = 'Cần cải thiện'

  const trendValue = score - prevScore
  let trend: 'up' | 'down' | 'stable'
  if (trendValue > 3) trend = 'up'
  else if (trendValue < -3) trend = 'down'
  else trend = 'stable'

  return { score, grade, trend, trendValue, factors }
}

function generateSuggestions(
  stats: WeeklyStats,
  senders: SenderInsight[]
): WeeklyReport['suggestions'] {
  const suggestions: WeeklyReport['suggestions'] = []

  // Unsubscribe suggestions
  const unsubscribeCandidates = senders.filter(s => s.suggestion === 'unsubscribe')
  if (unsubscribeCandidates.length > 0) {
    suggestions.push({
      type: 'unsubscribe',
      title: `Unsubscribe ${unsubscribeCandidates.length} nguồn email`,
      description: `Các nguồn này gửi nhiều nhưng sếp hầu như không mở`,
      actionable: true,
      data: unsubscribeCandidates.map(s => s.email)
    })
  }

  // VIP suggestions
  const vipCandidates = senders.filter(s => s.suggestion === 'vip')
  if (vipCandidates.length > 0) {
    suggestions.push({
      type: 'vip',
      title: `Đánh dấu VIP cho ${vipCandidates.length} người gửi`,
      description: `Email từ những người này luôn được mở nhanh`,
      actionable: true,
      data: vipCandidates.map(s => s.email)
    })
  }

  // Rule suggestion based on patterns
  const newsletterCount = stats.categoryBreakdown['newsletter'] || 0
  if (newsletterCount > 10) {
    suggestions.push({
      type: 'rule',
      title: 'Tạo rule tự động cho Newsletter',
      description: `Tuần này có ${newsletterCount} newsletter. Gom lại và đọc 1 lần/tuần?`,
      actionable: true
    })
  }

  // Habit suggestion
  if (stats.busiestHour >= 9 && stats.busiestHour <= 11) {
    suggestions.push({
      type: 'habit',
      title: 'Email tập trung buổi sáng',
      description: `Phần lớn email đến lúc ${stats.busiestHour}h. Cân nhắc check email cố định 9h và 14h.`,
      actionable: false
    })
  }

  return suggestions
}

// Daily digest for quick check
export async function generateDailyDigest(userId: string) {
  const now = new Date()
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate())

  const { data: todayEmails } = await getSupabase()
    .from('emails')
    .select('*')
    .eq('user_id', userId)
    .gte('received_at', todayStart.toISOString())

  const { data: unreadImportant } = await getSupabase()
    .from('emails')
    .select('*')
    .eq('user_id', userId)
    .eq('is_read', false)
    .eq('is_deleted', false)
    .eq('is_archived', false)
    .gte('priority', 4)

  const emails = (todayEmails || []) as Email[]
  const important = (unreadImportant || []) as Email[]

  return {
    date: todayStart.toISOString(),
    todayCount: emails.length,
    unreadCount: emails.filter(e => !e.is_read).length,
    importantUnread: important.length,
    byCategory: {
      work: emails.filter(e => e.category === 'work').length,
      personal: emails.filter(e => e.category === 'personal').length,
      newsletter: emails.filter(e => e.category === 'newsletter').length,
      promotion: emails.filter(e => e.category === 'promotion').length,
    },
    topSenders: Object.entries(
      emails.reduce((acc: Record<string, number>, e) => {
        const key = e.from_name || e.from_address
        acc[key] = (acc[key] || 0) + 1
        return acc
      }, {})
    ).sort((a, b) => b[1] - a[1]).slice(0, 5)
  }
}

import type { Category, Priority } from '@/types'

interface PriorityInput {
  category: Category
  subject: string
  fromAddress: string
  bodyText: string
  hasAttachment: boolean
  isRepliedThread: boolean
  senderTrustLevel?: 'trusted' | 'neutral' | 'untrusted' | 'blocked'
}

// Priority mapping:
// 5 = Urgent/Critical - Need immediate attention
// 4 = High - Important, should address soon
// 3 = Normal - Regular priority
// 2 = Low - Can wait
// 1 = Very Low - Promotions, spam

/**
 * Determine email priority based on category and signals
 */
export function determinePriority(input: PriorityInput): Priority {
  const { category, subject, fromAddress, bodyText, hasAttachment, isRepliedThread, senderTrustLevel } = input
  const subjectLower = subject.toLowerCase()
  const textLower = `${subject} ${bodyText}`.toLowerCase()

  // SPAM and BLOCKED → Always priority 1
  if (category === 'spam' || senderTrustLevel === 'blocked') {
    return 1
  }

  // TRANSACTION category
  if (category === 'transaction') {
    // OTP, verification → Highest priority (time-sensitive)
    if (/otp|mã xác nhận|verification|xác thực|mã code|security code/i.test(subjectLower)) {
      return 5
    }
    // Bank alerts - account activity
    if (/biến động|alert|cảnh báo|security alert|fraud|unusual activity/i.test(subjectLower)) {
      return 5
    }
    // Payment due, bills
    if (/payment due|hạn thanh toán|hóa đơn|invoice due/i.test(subjectLower)) {
      return 4
    }
    // Order confirmation, delivery
    if (/đơn hàng|order|delivery|giao hàng|shipped|shipment/i.test(subjectLower)) {
      return 3
    }
    // Other transactions
    return 3
  }

  // WORK category
  if (category === 'work') {
    // Urgent keywords
    if (/urgent|gấp|khẩn|asap|deadline today|eod|immediately|quan trọng|critical/i.test(subjectLower)) {
      return 5
    }
    // Meeting invites for today
    if (/meeting.*today|họp.*hôm nay|cuộc họp.*ngay/i.test(textLower)) {
      return 5
    }
    // Deadline mentions
    if (/deadline|due date|hạn chót|trước ngày/i.test(subjectLower)) {
      return 4
    }
    // Review requests
    if (/review|phê duyệt|approval|xin ý kiến|for your review/i.test(subjectLower)) {
      return 4
    }
    // Is a reply in thread → Ongoing conversation
    if (isRepliedThread) {
      return 4
    }
    // Has attachment → Could be important document
    if (hasAttachment) {
      return 3
    }
    // From trusted sender
    if (senderTrustLevel === 'trusted') {
      return 3
    }
    // Regular work email
    return 3
  }

  // PERSONAL category
  if (category === 'personal') {
    // From trusted contacts
    if (senderTrustLevel === 'trusted') {
      return 3
    }
    // Is a reply → Active conversation
    if (isRepliedThread) {
      return 3
    }
    // Birthday, special occasions
    if (/sinh nhật|birthday|anniversary|kỷ niệm|wedding|đám cưới/i.test(subjectLower)) {
      return 3
    }
    // Regular personal
    return 3
  }

  // SOCIAL category
  if (category === 'social') {
    // Direct messages
    if (/message|tin nhắn|dm|direct/i.test(subjectLower)) {
      return 3
    }
    // Friend requests, mentions
    if (/friend|bạn bè|mention|tag|nhắc đến/i.test(subjectLower)) {
      return 2
    }
    // Other social notifications
    return 2
  }

  // NEWSLETTER category
  if (category === 'newsletter') {
    // From trusted newsletter sources
    if (senderTrustLevel === 'trusted') {
      return 2
    }
    // Regular newsletters
    return 2
  }

  // PROMOTION category
  if (category === 'promotion') {
    // From stores user has bought from (would be marked as trusted)
    if (senderTrustLevel === 'trusted') {
      return 2
    }
    // Regular promotions
    return 1
  }

  // Default
  return 3
}

/**
 * Extract deadline from email content
 */
export function extractDeadline(subject: string, bodyText: string): string | null {
  const text = `${subject} ${bodyText}`

  // Vietnamese date patterns
  const vnPatterns = [
    /trước\s*(ngày)?\s*(\d{1,2})[\/\-](\d{1,2})[\/\-]?(\d{2,4})?/i,
    /hạn\s*(chót|cuối)?\s*[:\s]?\s*(\d{1,2})[\/\-](\d{1,2})[\/\-]?(\d{2,4})?/i,
    /deadline[:\s]+(\d{1,2})[\/\-](\d{1,2})[\/\-]?(\d{2,4})?/i,
  ]

  // English date patterns
  const enPatterns = [
    /due\s*(by|date)?[:\s]+(\w+\s+\d{1,2}(st|nd|rd|th)?,?\s*\d{4}?)/i,
    /deadline[:\s]+(\w+\s+\d{1,2},?\s*\d{4}?)/i,
    /by\s+(\w+\s+\d{1,2}(st|nd|rd|th)?)/i,
    /before\s+(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/i,
  ]

  // Relative dates
  const relativePatterns = [
    /today|hôm nay/i,
    /tomorrow|ngày mai/i,
    /this week|tuần này/i,
    /next week|tuần sau/i,
    /end of (week|day)|cuối (tuần|ngày)/i,
  ]

  // Try to find dates
  for (const pattern of [...vnPatterns, ...enPatterns]) {
    const match = text.match(pattern)
    if (match) {
      try {
        // Try to parse the date - return as ISO string
        const dateStr = match[0]
        // This is simplified - in production would need proper date parsing
        return dateStr
      } catch {
        continue
      }
    }
  }

  // Check relative dates
  for (const pattern of relativePatterns) {
    if (pattern.test(text)) {
      const now = new Date()
      if (/today|hôm nay/i.test(text)) {
        return now.toISOString().split('T')[0]
      }
      if (/tomorrow|ngày mai/i.test(text)) {
        now.setDate(now.getDate() + 1)
        return now.toISOString().split('T')[0]
      }
    }
  }

  return null
}

/**
 * Determine if email needs reply based on content
 */
export function needsReply(
  category: Category,
  subject: string,
  bodyText: string,
  fromAddress: string
): boolean {
  // Spam, newsletter, promotion → No reply needed
  if (['spam', 'newsletter', 'promotion', 'social'].includes(category)) {
    return false
  }

  // No-reply addresses → No reply expected
  if (/noreply|no-reply|donotreply|mailer-daemon|bounce/i.test(fromAddress)) {
    return false
  }

  const text = `${subject} ${bodyText}`.toLowerCase()

  // Transaction → Usually no reply needed
  if (category === 'transaction') {
    // Unless it's asking for action
    return /please (confirm|verify|respond)|vui lòng (xác nhận|phản hồi)/i.test(text)
  }

  // Work emails
  if (category === 'work') {
    // Questions → Need reply
    if (/\?|please (advise|confirm|let me know)|xin (ý kiến|phản hồi|cho biết)/i.test(text)) {
      return true
    }
    // Review requests → Need reply
    if (/for your (review|approval)|xin phê duyệt|review needed/i.test(text)) {
      return true
    }
    // Action required
    if (/action required|cần (xử lý|phản hồi)/i.test(text)) {
      return true
    }
  }

  // Personal → Usually needs reply if it's a question
  if (category === 'personal') {
    return /\?/.test(text)
  }

  return false
}

/**
 * Suggest action for email
 */
export function suggestAction(
  category: Category,
  priority: Priority,
  needsReply: boolean
): 'reply' | 'archive' | 'delete' | 'read_later' | 'none' {
  // High priority needs reply → Reply
  if (needsReply && priority >= 4) {
    return 'reply'
  }

  // Spam → Delete
  if (category === 'spam') {
    return 'delete'
  }

  // Low priority promotions → Archive or delete
  if (category === 'promotion' && priority <= 1) {
    return 'archive'
  }

  // Newsletters → Read later or archive
  if (category === 'newsletter') {
    return 'read_later'
  }

  // Transaction completed → Archive
  if (category === 'transaction') {
    return 'archive'
  }

  // Work/Personal needing reply
  if (needsReply) {
    return 'reply'
  }

  return 'none'
}

import { createClient, SupabaseClient } from '@supabase/supabase-js'

let supabaseInstance: SupabaseClient | null = null

function getSupabase(): SupabaseClient {
  if (!supabaseInstance) {
    supabaseInstance = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    )
  }
  return supabaseInstance
}

export interface SenderTrust {
  id: string
  user_id: string
  email_address: string
  domain: string | null
  trust_level: 'trusted' | 'neutral' | 'untrusted' | 'blocked'
  trust_score: number
  is_contact: boolean
  has_replied: boolean
  times_received: number
  times_opened: number
  times_replied: number
  last_email_at: string | null
}

/**
 * Lấy trust info của sender
 */
export async function getSenderTrust(
  userId: string,
  senderEmail: string
): Promise<SenderTrust | null> {
  const { data, error } = await getSupabase()
    .from('sender_trust')
    .select('*')
    .eq('user_id', userId)
    .eq('email_address', senderEmail.toLowerCase())
    .single()

  if (error || !data) return null
  return data as SenderTrust
}

/**
 * Cập nhật sender trust khi nhận email mới
 */
export async function updateSenderOnReceive(
  userId: string,
  senderEmail: string,
  senderName?: string
): Promise<void> {
  const email = senderEmail.toLowerCase()
  const domain = email.split('@')[1] || null

  const { data: existing } = await getSupabase()
    .from('sender_trust')
    .select('*')
    .eq('user_id', userId)
    .eq('email_address', email)
    .single()

  if (existing) {
    // Update existing record
    await getSupabase()
      .from('sender_trust')
      .update({
        times_received: (existing.times_received || 0) + 1,
        last_email_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      })
      .eq('id', existing.id)
  } else {
    // Create new record
    await getSupabase()
      .from('sender_trust')
      .insert({
        user_id: userId,
        email_address: email,
        domain,
        trust_level: 'neutral',
        trust_score: 0,
        times_received: 1,
        last_email_at: new Date().toISOString()
      })
  }
}

/**
 * Đánh dấu sender là TRUSTED
 * - Khi user reply
 * - Khi user mark "Not spam"
 * - Khi thêm vào contacts
 */
export async function markSenderAsTrusted(
  userId: string,
  senderEmail: string,
  reason: 'replied' | 'marked_not_spam' | 'contact'
): Promise<void> {
  const email = senderEmail.toLowerCase()
  const domain = email.split('@')[1] || null

  const updateData: Record<string, unknown> = {
    trust_level: 'trusted',
    trust_score: 100,
    updated_at: new Date().toISOString()
  }

  if (reason === 'replied') {
    updateData.has_replied = true
    updateData.times_replied = 1
  } else if (reason === 'contact') {
    updateData.is_contact = true
  }

  const { data: existing } = await getSupabase()
    .from('sender_trust')
    .select('id, times_replied')
    .eq('user_id', userId)
    .eq('email_address', email)
    .single()

  if (existing) {
    if (reason === 'replied') {
      updateData.times_replied = (existing.times_replied || 0) + 1
    }
    await getSupabase()
      .from('sender_trust')
      .update(updateData)
      .eq('id', existing.id)
  } else {
    await getSupabase()
      .from('sender_trust')
      .insert({
        user_id: userId,
        email_address: email,
        domain,
        ...updateData,
        times_received: 0
      })
  }
}

/**
 * Đánh dấu sender là UNTRUSTED (khi user mark spam)
 */
export async function markSenderAsUntrusted(
  userId: string,
  senderEmail: string
): Promise<void> {
  const email = senderEmail.toLowerCase()
  const domain = email.split('@')[1] || null

  const { data: existing } = await getSupabase()
    .from('sender_trust')
    .select('id')
    .eq('user_id', userId)
    .eq('email_address', email)
    .single()

  const updateData = {
    trust_level: 'untrusted',
    trust_score: -100,
    updated_at: new Date().toISOString()
  }

  if (existing) {
    await getSupabase()
      .from('sender_trust')
      .update(updateData)
      .eq('id', existing.id)
  } else {
    await getSupabase()
      .from('sender_trust')
      .insert({
        user_id: userId,
        email_address: email,
        domain,
        ...updateData,
        times_received: 0
      })
  }
}

/**
 * Block sender hoàn toàn
 */
export async function blockSender(
  userId: string,
  senderEmail: string
): Promise<void> {
  const email = senderEmail.toLowerCase()
  const domain = email.split('@')[1] || null

  await getSupabase()
    .from('sender_trust')
    .upsert({
      user_id: userId,
      email_address: email,
      domain,
      trust_level: 'blocked',
      trust_score: -100,
      updated_at: new Date().toISOString()
    }, {
      onConflict: 'user_id,email_address'
    })
}

/**
 * Tính trust score tổng hợp từ nhiều signals
 */
export function calculateTrustScore(sender: SenderTrust | null): number {
  if (!sender) return 0

  let score = sender.trust_score || 0

  // Đã reply = rất trusted (+50)
  if (sender.has_replied) score += 50

  // Là contact = trusted (+30)
  if (sender.is_contact) score += 30

  // Đã nhận nhiều email và không block = có thể trusted
  if (sender.times_received > 5 && sender.trust_level !== 'untrusted') {
    score += 10
  }

  // Đã mở nhiều lần = quan tâm
  if (sender.times_opened > 3) score += 15

  // Đã reply nhiều lần = rất trusted
  if (sender.times_replied > 1) score += 20

  return Math.max(-100, Math.min(100, score))
}

/**
 * Extract email signals để hỗ trợ AI classification
 */
export function extractEmailSignals(email: {
  from_address: string
  from_name?: string
  subject?: string
  body_text?: string
  body_html?: string
}): Record<string, unknown> {
  const fromEmail = email.from_address.toLowerCase()
  const fromName = email.from_name || ''
  const subject = email.subject || ''
  const body = email.body_text || ''

  return {
    // Sender signals
    isNoReply: /noreply|no-reply|donotreply|do-not-reply/i.test(fromEmail),
    isMarketing: /marketing|promo|newsletter|campaign|bulk|notify|notification/i.test(fromEmail),
    isSupportOrInfo: /support|info|help|service|contact/i.test(fromEmail),

    // Name signals - check for real Vietnamese or English names
    hasRealName: hasRealPersonName(fromName),

    // Content signals
    hasPersonalGreeting: /^(hi|hello|hey|dear|chào|anh|chị|em|bạn|ông|bà|thân|kính)\s/i.test(body.trim()),
    hasRecipientName: false, // Would need recipient's name to check
    hasUnsubscribe: /unsubscribe|hủy đăng ký|ngừng nhận|opt.out/i.test(body),
    hasPromoWords: /(sale|discount|off|free|limited|exclusive|deal|giảm giá|khuyến mãi|miễn phí|ưu đãi|%\s*off)/i.test(subject + ' ' + body),
    hasUrgentWords: /(urgent|asap|immediately|ngay|gấp|khẩn|important|quan trọng)/i.test(subject),

    // Structure signals
    bodyLength: body.length,
    subjectLength: subject.length,
    hasImages: /<img\s/i.test(email.body_html || ''),
    linkCount: (body.match(/https?:\/\//g) || []).length,

    // Spam indicators
    hasExcessiveCaps: (subject.match(/[A-Z]{3,}/g) || []).length > 2,
    hasExcessivePunctuation: (subject.match(/[!?]{2,}/g) || []).length > 0,
    hasCurrencySymbols: /[$€£¥₫]\s*\d|đ\s*\d/i.test(subject + ' ' + body),
  }
}

/**
 * Check if name looks like a real person (Vietnamese or English)
 */
function hasRealPersonName(name: string): boolean {
  if (!name || name.length < 3) return false

  // Vietnamese name pattern: Họ Tên (e.g., "Nguyễn Văn An", "Trần Thị Hương")
  const vietnamesePattern = /^[A-ZÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ][a-zàáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]+\s+[A-ZÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ][a-zàáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]+/

  // English name pattern: First Last (e.g., "John Smith", "Mary Jane")
  const englishPattern = /^[A-Z][a-z]+\s+[A-Z][a-z]+/

  // Check if it's NOT a company/service name
  const companyIndicators = /team|support|service|company|inc|ltd|corp|noreply|newsletter|marketing|sales/i

  if (companyIndicators.test(name)) return false

  return vietnamesePattern.test(name) || englishPattern.test(name)
}

/**
 * Check if same domain as user (likely colleague)
 */
export function isSameDomain(userEmail: string, senderEmail: string): boolean {
  const userDomain = userEmail.toLowerCase().split('@')[1]
  const senderDomain = senderEmail.toLowerCase().split('@')[1]

  if (!userDomain || !senderDomain) return false

  // Ignore common email providers
  const commonProviders = ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com']
  if (commonProviders.includes(userDomain) || commonProviders.includes(senderDomain)) {
    return false
  }

  return userDomain === senderDomain
}

