/**
 * Gmail Sync Service - OPTIMIZED
 * Sync emails from Gmail API to database with batch processing
 */

import { createClient as createSupabaseAdmin } from '@supabase/supabase-js';
import {
  refreshAccessToken,
  isTokenExpired
} from '@/lib/oauth/google';
import {
  listMessages,
  getMessage,
  parseHeaders,
  extractBody,
} from '@/lib/gmail/api';
import { gmailLogger } from '@/lib/logger';

// Create admin client lazily to avoid edge runtime issues
function getSupabaseAdmin() {
  return createSupabaseAdmin(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  );
}

interface SyncResult {
  success: boolean;
  syncedCount: number;
  error?: string;
}

// Parallel processing limit
const PARALLEL_FETCH_LIMIT = 10;

/**
 * Process items with concurrency limit
 */
async function parallelLimit<T, R>(
  items: T[],
  limit: number,
  fn: (item: T) => Promise<R>
): Promise<R[]> {
  const results: R[] = [];
  let index = 0;

  async function worker(): Promise<void> {
    while (index < items.length) {
      const currentIndex = index++;
      try {
        const result = await fn(items[currentIndex]);
        results[currentIndex] = result;
      } catch {
        results[currentIndex] = null as R;
      }
    }
  }

  const workers = Array(Math.min(limit, items.length)).fill(null).map(() => worker());
  await Promise.all(workers);
  return results;
}

/**
 * Get valid access token (refresh if expired)
 * Supports both old (oauth_*) and new (access_token, etc.) column names
 */
export async function getValidAccessToken(
  accountId: string
): Promise<string | null> {
  const supabase = getSupabaseAdmin();

  const { data: account } = await supabase
    .from('source_accounts')
    .select('access_token, refresh_token, token_expires_at, oauth_access_token, oauth_refresh_token, oauth_expires_at')
    .eq('id', accountId)
    .single();

  if (!account) return null;

  // Support both old and new column names
  const accessToken = account.access_token || account.oauth_access_token;
  const refreshToken = account.refresh_token || account.oauth_refresh_token;
  const expiresAt = account.token_expires_at || account.oauth_expires_at;

  // Check if token is expired
  if (expiresAt && isTokenExpired(new Date(expiresAt))) {
    if (!refreshToken) {
      return null;
    }

    try {
      // Refresh the token
      const newTokens = await refreshAccessToken(refreshToken);
      const newExpiresAt = new Date(Date.now() + newTokens.expires_in * 1000);

      // Update in database using new column names
      await supabase
        .from('source_accounts')
        .update({
          access_token: newTokens.access_token,
          token_expires_at: newExpiresAt.toISOString(),
          ...(newTokens.refresh_token && {
            refresh_token: newTokens.refresh_token
          }),
        })
        .eq('id', accountId);

      return newTokens.access_token;
    } catch {
      return null;
    }
  }

  return accessToken;
}

/**
 * Sync emails from Gmail
 */
export async function syncGmailEmails(
  userId: string,
  accountId: string,
  options: {
    maxResults?: number;
    fullSync?: boolean;
  } = {}
): Promise<SyncResult> {
  const supabase = getSupabaseAdmin();

  // Set sync status to syncing
  await supabase
    .from('source_accounts')
    .update({ sync_status: 'syncing', sync_error: null })
    .eq('id', accountId);

  try {
    // Get valid access token
    const accessToken = await getValidAccessToken(accountId);
    if (!accessToken) {
      await supabase
        .from('source_accounts')
        .update({ sync_status: 'error', sync_error: 'Invalid access token' })
        .eq('id', accountId);
      return { success: false, syncedCount: 0, error: 'Invalid access token' };
    }

    // Get account info
    const { data: account } = await supabase
      .from('source_accounts')
      .select('email_address, last_sync_at')
      .eq('id', accountId)
      .single();

    if (!account) {
      return { success: false, syncedCount: 0, error: 'Account not found' };
    }

    gmailLogger.info(`Starting sync for ${account.email_address}, maxResults=${options.maxResults || 50}`);

    // Build query for new emails - only use 'after:' filter, not 'in:inbox' since we use labelIds
    let query = '';
    if (!options.fullSync && account.last_sync_at) {
      const afterDate = new Date(account.last_sync_at);
      query = `after:${Math.floor(afterDate.getTime() / 1000)}`;
    }

    gmailLogger.debug(`Query: "${query}", labelIds: INBOX`);

    // List messages
    const messageList = await listMessages(accessToken, {
      maxResults: options.maxResults || 50,
      q: query || undefined, // Don't send empty query
      labelIds: ['INBOX'],
    });

    if (!messageList.messages || messageList.messages.length === 0) {
      gmailLogger.debug('No new messages found');
      // Update last sync time even if no new messages
      await supabase
        .from('source_accounts')
        .update({
          last_sync_at: new Date().toISOString(),
          sync_status: 'idle',
          sync_error: null,
        })
        .eq('id', accountId);

      return { success: true, syncedCount: 0 };
    }

    gmailLogger.info(`Found ${messageList.messages.length} messages to sync`);

    // Get existing message IDs to filter duplicates
    const messageIds = messageList.messages.map(m => m.id);
    const { data: existingEmails } = await supabase
      .from('emails')
      .select('message_id')
      .eq('user_id', userId)
      .in('message_id', messageIds);

    const existingIds = new Set(existingEmails?.map(e => e.message_id) || []);
    const newMessages = messageList.messages.filter(m => !existingIds.has(m.id));

    gmailLogger.debug(`${newMessages.length} new messages (${existingIds.size} already exist)`);

    if (newMessages.length === 0) {
      await supabase
        .from('source_accounts')
        .update({
          last_sync_at: new Date().toISOString(),
          sync_status: 'idle',
          sync_error: null,
        })
        .eq('id', accountId);
      return { success: true, syncedCount: 0 };
    }

    // OPTIMIZED: Fetch messages in parallel
    const startTime = Date.now();
    const fetchedMessages = await parallelLimit(
      newMessages,
      PARALLEL_FETCH_LIMIT,
      async (msg) => {
        try {
          const fullMessage = await getMessage(accessToken, msg.id);
          const headers = parseHeaders(fullMessage.payload.headers);
          const body = extractBody(fullMessage);

          // Parse from address
          const fromHeader = headers['from'] || '';
          const fromMatch = fromHeader.match(/(?:"?([^"]*)"?\s)?<?([^>]+@[^>]+)>?/);
          const fromName = fromMatch?.[1] || '';
          const fromAddress = fromMatch?.[2] || fromHeader;

          return {
            user_id: userId,
            source_account_id: accountId,
            message_id: msg.id,
            original_uid: msg.id, // Use Gmail message ID as UID
            // Note: Gmail threadId is hex string, not UUID. Store in original_uid for grouping
            // thread_id column in DB expects UUID, so we skip it
            subject: headers['subject'] || '(Không có tiêu đề)',
            from_name: fromName,
            from_address: fromAddress,
            to_addresses: [headers['to'] || ''],
            body_text: body.text?.slice(0, 100000) || '',
            body_html: body.html?.slice(0, 200000) || null,
            body_fetched: true,
            snippet: fullMessage.snippet,
            received_at: new Date(parseInt(fullMessage.internalDate)).toISOString(),
            is_read: !fullMessage.labelIds.includes('UNREAD'),
            is_starred: fullMessage.labelIds.includes('STARRED'),
            is_archived: false,
            is_deleted: false,
            direction: 'inbound',
          };
        } catch {
          return null;
        }
      }
    );

    const validEmails = fetchedMessages.filter((e): e is NonNullable<typeof e> => e !== null);
    gmailLogger.debug(`Fetched ${validEmails.length} messages in ${Date.now() - startTime}ms`);

    // Batch insert emails
    let syncedCount = 0;
    if (validEmails.length > 0) {
      const { error: insertError, count } = await supabase
        .from('emails')
        .upsert(validEmails, {
          onConflict: 'source_account_id,original_uid',
          ignoreDuplicates: true
        });

      if (!insertError) {
        syncedCount = validEmails.length;
      }
    }

    // Update last sync time, sync status and increment total count
    const { error: updateError } = await supabase
      .from('source_accounts')
      .update({
        last_sync_at: new Date().toISOString(),
        sync_status: 'idle',
        sync_error: null,
      })
      .eq('id', accountId);

    if (updateError) {
      gmailLogger.error('Failed to update source_account:', updateError);
    }

    // Increment total_emails_synced using raw SQL for atomic increment
    if (syncedCount > 0) {
      await supabase.rpc('increment_total_emails_synced', {
        account_id: accountId,
        count: syncedCount
      }).then(({ error }) => {
        if (error) {
          // Fallback: Get current count and update
          supabase
            .from('source_accounts')
            .select('total_emails_synced')
            .eq('id', accountId)
            .single()
            .then(({ data }) => {
              const currentCount = data?.total_emails_synced || 0;
              supabase
                .from('source_accounts')
                .update({ total_emails_synced: currentCount + syncedCount })
                .eq('id', accountId);
            });
        }
      });
    }

    gmailLogger.info(`Sync complete: ${syncedCount} emails synced`);
    return { success: true, syncedCount };

  } catch (error) {
    gmailLogger.error('Gmail sync error:', error);

    // Update error status
    await supabase
      .from('source_accounts')
      .update({
        sync_status: 'error',
        sync_error: error instanceof Error ? error.message : 'Sync failed',
      })
      .eq('id', accountId);

    return {
      success: false,
      syncedCount: 0,
      error: error instanceof Error ? error.message : 'Unknown error'
    };
  }
}

import { createServerClient, type CookieOptions } from '@supabase/ssr'
import { createClient as createSupabaseClient } from '@supabase/supabase-js'
import { cookies } from 'next/headers'
import { NextRequest } from 'next/server'

/**
 * Create Supabase client for server-side use with cookies
 * Use for web app (browser) requests
 */
export async function createClient() {
  const cookieStore = await cookies()

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // The `setAll` method was called from a Server Component.
            // This can be ignored if you have middleware refreshing sessions.
          }
        },
      },
    }
  )
}

/**
 * Create Supabase client with Bearer token authentication
 * Use for mobile app requests that send Authorization header
 */
export function createClientFromToken(token: string) {
  return createSupabaseClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      global: {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      },
    }
  )
}

/**
 * Create Supabase client that supports both:
 * - Bearer token auth (mobile apps)
 * - Cookie auth (web browser)
 *
 * Automatically detects which method to use based on request headers
 */
export async function createClientForRequest(request: NextRequest) {
  // Check for Bearer token first (mobile apps)
  const authHeader = request.headers.get('authorization')
  const bearerToken = authHeader?.replace('Bearer ', '')

  if (bearerToken) {
    // Mobile: Use Bearer token
    return createClientFromToken(bearerToken)
  }

  // Web: Use cookie-based auth
  return createClient()
}

/**
 * Toast Utility
 * Wrapper around the toast system with error integration
 */

import { toast as showToast, type ToastType } from '@/components/ui/toast'
import { ApiError, getErrorMessage, isApiError } from '@/lib/api/errors'

// =============================================================================
// Toast Functions
// =============================================================================

/**
 * Show success toast
 */
export function toastSuccess(message: string, description?: string) {
  showToast('success', message, description)
}

/**
 * Show error toast
 */
export function toastError(message: string, description?: string) {
  showToast('error', message, description)
}

/**
 * Show warning toast
 */
export function toastWarning(message: string, description?: string) {
  showToast('warning', message, description)
}

/**
 * Show info toast
 */
export function toastInfo(message: string, description?: string) {
  showToast('info', message, description)
}

/**
 * Show toast from Error object
 */
export function toastFromError(error: unknown, defaultMessage?: string) {
  const message = getErrorMessage(error) || defaultMessage || 'Đã xảy ra lỗi'

  if (isApiError(error)) {
    // For retryable errors, show as warning
    if (error.retryable) {
      showToast('warning', message, 'Vui lòng thử lại sau giây lát')
    } else {
      showToast('error', message)
    }
  } else {
    showToast('error', message)
  }
}

/**
 * Show network error toast
 */
export function toastNetworkError() {
  showToast('error', 'Lỗi kết nối mạng', 'Vui lòng kiểm tra internet và thử lại')
}

/**
 * Show offline toast
 */
export function toastOffline() {
  showToast('warning', 'Bạn đang offline', 'Một số tính năng có thể bị hạn chế')
}

/**
 * Show back online toast
 */
export function toastBackOnline() {
  showToast('success', 'Đã kết nối lại', 'Bạn đã online trở lại')
}

// =============================================================================
// Promise Toast
// =============================================================================

interface PromiseToastOptions<T> {
  loading?: string
  success?: string | ((data: T) => string)
  error?: string | ((error: unknown) => string)
}

/**
 * Show toast for async operations (loading -> success/error)
 */
export async function toastPromise<T>(
  promise: Promise<T>,
  options: PromiseToastOptions<T>
): Promise<T> {
  // Show loading toast
  if (options.loading) {
    showToast('info', options.loading, undefined, 0) // No auto-dismiss
  }

  try {
    const result = await promise

    // Show success toast
    const successMessage =
      typeof options.success === 'function'
        ? options.success(result)
        : options.success || 'Thành công'
    showToast('success', successMessage)

    return result
  } catch (error) {
    // Show error toast
    const errorMessage =
      typeof options.error === 'function'
        ? options.error(error)
        : options.error || getErrorMessage(error)
    showToast('error', errorMessage)

    throw error
  }
}

// =============================================================================
// Re-export base toast for flexibility
// =============================================================================

export { showToast as toast }
export type { ToastType }
